import { Prisma } from '@prisma/client'
import { formatInTimeZone } from 'date-fns-tz'

const TIMEZONE = 'Asia/Shanghai'
const DATETIME_FORMAT = 'yyyy-MM-dd HH:mm:ss'

/**
 * 递归转换对象中的所有 Date 类型为 Asia/Shanghai 时区字符串
 * @param obj 要转换的对象
 * @returns 转换后的对象
 */
function convertDatesToTimezone(obj: any): any {
  if (obj === null || obj === undefined) return obj

  // 如果是 Date 对象，转换为 Asia/Shanghai 时区字符串
  if (obj instanceof Date) {
    return formatInTimeZone(obj, TIMEZONE, DATETIME_FORMAT)
  }

  // 如果是数组，递归处理每个元素
  if (Array.isArray(obj)) {
    return obj.map(item => convertDatesToTimezone(item))
  }

  // 如果是对象，递归处理每个属性
  if (typeof obj === 'object') {
    const converted: any = {}
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        converted[key] = convertDatesToTimezone(obj[key])
      }
    }
    return converted
  }

  // 其他类型直接返回
  return obj
}

/**
 * Prisma 时区扩展
 * 自动将所有查询结果中的 DateTime 字段转换为 Asia/Shanghai 时区字符串
 */
export const timezoneExtension = Prisma.defineExtension({
  name: 'timezone',
  query: {
    $allModels: {
      async $allOperations({ operation, model, args, query }) {
        const result = await query(args)

        // 只对查询操作进行转换（不影响写入）
        const readOperations = [
          'findUnique',
          'findUniqueOrThrow',
          'findFirst',
          'findFirstOrThrow',
          'findMany',
          'create',
          'createMany',
          'update',
          'updateMany',
          'upsert',
          'delete',
          'deleteMany',
          'aggregate',
          'groupBy',
          'count',
        ]

        if (readOperations.includes(operation)) {
          return convertDatesToTimezone(result)
        }

        return result
      },
    },
  },
})

﻿import { Page } from '@playwright/test';
import { TEST_API_KEY } from './auth-helpers';

/**
 * 判断是否需要使用 API Key
 * 只有外部 API 接口才需要使用 API Key，内部接口使用 Session
 */
function shouldUseApiKey(url: string): boolean {
  // 只有明确的外部 API 路径才需要 API Key
  const apiKeyEndpoints = [
    '/api/external/',
    // 内部 API 不需要 API Key，因为测试使用的是内部 Session 认证
  ];

  return apiKeyEndpoints.some(endpoint => url.includes(endpoint));
}

/**
 * 通用的 API 请求方法
 * 自动根据 URL 和方法决定使用 API Key 还是 Session
 */
export async function apiRequest(
  page: Page,
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE',
  url: string,
  options?: {
    data?: any;
    headers?: Record<string, string>;
  }
) {
  const headers = { ...options?.headers };

  // 自动添加 API Key（如果需要）
  if (shouldUseApiKey(url)) {
    headers['X-API-Key'] = TEST_API_KEY;
  }

  const requestOptions: any = {
    headers: Object.keys(headers).length > 0 ? headers : undefined,
  };

  // 只有非 GET 请求才添加 data
  if (method !== 'GET' && options?.data !== undefined) {
    requestOptions.data = options.data;
  }

  const response = await page.request[method.toLowerCase() as 'get' | 'post' | 'put' | 'patch' | 'delete'](url, requestOptions);

  return response;
}

/**
 * 创建客户
 */
export async function createClient(page: Page, data: {
  clientCode: string;
  clientName: string;
  clientType?: string;
  status?: string;
}) {
  const response = await apiRequest(page, 'POST', '/api/v1/clients', {
    data: {
      clientCode: data.clientCode,
      clientName: data.clientName,
      clientType: data.clientType || 'STANDARD',
      status: data.status || 'ACTIVE',
    },
  });
  const result = await response.json();
  return result;
}

