  // 如果已有存储状态，直接使用
  if (adminStorageState) {
    await page.context().addCookies(adminStorageState.cookies);
    return;
  }

  // 执行登录
  await loginAsAdmin(page);

  // 保存登录状态
  adminStorageState = await page.context().storageState();
}

