// 可用的权限范围
const getScopeLabel = (t: (key: string) => string, scope: string) => {
  return t(`apiKey.scopeLabels.${scope}`)
}

const AVAILABLE_SCOPES = (t: (key: string) => string) => [
  { value: 'sku:read', label: getScopeLabel(t, 'sku:read'), group: t('apiKey.scopeGroups.SKU') },
  { value: 'sku:create', label: getScopeLabel(t, 'sku:create'), group: t('apiKey.scopeGroups.SKU') },
  { value: 'sku:write', label: getScopeLabel(t, 'sku:write'), group: t('apiKey.scopeGroups.SKU') },
  { value: 'sku:delete', label: getScopeLabel(t, 'sku:delete'), group: t('apiKey.scopeGroups.SKU') },
  { value: 'asn:read', label: getScopeLabel(t, 'asn:read'), group: t('apiKey.scopeGroups.ASN') },
  { value: 'asn:create', label: getScopeLabel(t, 'asn:create'), group: t('apiKey.scopeGroups.ASN') },
  { value: 'asn:write', label: getScopeLabel(t, 'asn:write'), group: t('apiKey.scopeGroups.ASN') },
  { value: 'asn:delete', label: getScopeLabel(t, 'asn:delete'), group: t('apiKey.scopeGroups.ASN') },
]

interface ApiKey {
  id: string
  name: string
  description?: string
  keyPrefix: string
  scopes: string[]
  rateLimit: number
  isActive: boolean
  expiresAt?: string
  lastUsedAt?: string
  createdAt: string
}

export default function ApiKeysPage() {
  const t = useTranslations()
  const tCommon = useTranslations('common')
  const tMenuGroup = useTranslations('menuGroup')
  const breadcrumb = createBreadcrumbFactory({
    parents: [{ label: tMenuGroup('system') }],
    module: { label: t('apiKey.title'), href: '/api-keys' },
  })
  const [apiKeys, setApiKeys] = useState<ApiKey[]>([])
  const [loading, setLoading] = useState(true)
  const [createDialogOpen, setCreateDialogOpen] = useState(false)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [selectedKey, setSelectedKey] = useState<ApiKey | null>(null)
  const [newKeyVisible, setNewKeyVisible] = useState(false)
  const [newKey, setNewKey] = useState('')
  const [copied, setCopied] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    rateLimit: 100,
    scopes: [] as string[],
  })

  // 获取可用的权限范围
  const availableScopes = AVAILABLE_SCOPES(t)

  // 切换权限范围
  const toggleScope = (scope: string) => {
    setFormData((prev) => ({
      ...prev,
      scopes: prev.scopes.includes(scope)
        ? prev.scopes.filter((s) => s !== scope)
        : [...prev.scopes, scope],
    }))
  }

  // 按组分组权限
  const scopeGroups = availableScopes.reduce((acc, scope) => {
    if (!acc[scope.group]) acc[scope.group] = []
    acc[scope.group].push(scope)
    return acc
  }, {} as Record<string, typeof availableScopes>)

  // 加载API密钥列表
  const loadApiKeys = async () => {
    try {
      setLoading(true)
      const res = await fetch('/api/v1/api-keys')
      const data = await res.json()
      if (data.success) {
        setApiKeys(data.data || [])
      }
    } catch (error) {
      console.error(t('apiKey.messages.loadFailed'), error)
      toast.error(t('apiKey.messages.loadFailed'))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadApiKeys()
  }, [])

  // 创建API密钥
  const handleCreate = async () => {
    if (!formData.name.trim()) {
      toast.error(t('apiKey.messages.nameRequired'))
      return
    }

    try {
      const res = await fetch('/api/v1/api-keys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      })
      const data = await res.json()
      if (data.success) {
        setNewKey(data.data.key)
        setNewKeyVisible(true)
        setCreateDialogOpen(false)
        setFormData({ name: '', description: '', rateLimit: 100, scopes: [] })
        loadApiKeys()
        toast.success(t('apiKey.messages.createSuccess'))
      } else {
        toast.error(data.message || t('apiKey.messages.createFailed'))
      }
    } catch (error) {
      console.error(t('apiKey.messages.createError'), error)
      toast.error(t('apiKey.messages.createError'))
    }
  }

  // 删除API密钥
  const handleDelete = async () => {
    if (!selectedKey) return

    try {
      const res = await fetch(`/api/v1/api-keys/${selectedKey.id}`, {
        method: 'DELETE',
      })
      const data = await res.json()
      if (data.success) {
        toast.success(t('apiKey.messages.deleteSuccess'))
        loadApiKeys()
      } else {
        toast.error(data.message || t('apiKey.messages.deleteFailed'))
      }
    } catch (error) {
      console.error(t('apiKey.messages.deleteError'), error)
      toast.error(t('apiKey.messages.deleteError'))
    } finally {
      setDeleteDialogOpen(false)
      setSelectedKey(null)
    }
  }

  // 复制密钥
  const copyToClipboard = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      toast.success(t('apiKey.messages.copySuccess'))
      setTimeout(() => setCopied(false), 2000)
    } catch {
      toast.error(t('apiKey.messages.copyFailed'))
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <Breadcrumb items={breadcrumb.list()} />
          <p className="text-muted-foreground mt-1">{t('apiKey.description')}</p>
        </div>
        <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
          <DialogTrigger asChild>
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              {t('apiKey.createButton')}
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{t('apiKey.createTitle')}</DialogTitle>
              <DialogDescription>
                {t('apiKey.createDescription')}
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="name">{t('apiKey.nameRequired')}</Label>
                <Input
                  id="name"
                  placeholder={t('apiKey.namePlaceholder')}
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="description">{t('apiKey.description')}</Label>
                <Input
                  id="description"
                  placeholder={t('apiKey.descriptionPlaceholder')}
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="rateLimit">{t('apiKey.rateLimit')}</Label>
                <Input
                  id="rateLimit"
                  type="number"
                  min={1}
                  max={10000}
                  value={formData.rateLimit}
                  onChange={(e) => setFormData({ ...formData, rateLimit: parseInt(e.target.value) || 100 })}
                />
              </div>
              <div className="space-y-2">
                <Label>{t('apiKey.scopes')}</Label>
                <div className="border rounded-lg p-3 space-y-3 max-h-48 overflow-y-auto">
                  {Object.entries(scopeGroups).map(([group, scopes]) => (
                    <div key={group}>
                      <div className="text-sm font-medium text-muted-foreground mb-2">{group}</div>
                      <div className="grid grid-cols-2 gap-2">
                        {scopes.map((scope) => (
                          <div key={scope.value} className="flex items-center space-x-2">
                            <Checkbox
                              id={scope.value}
                              checked={formData.scopes.includes(scope.value)}
                              onCheckedChange={() => toggleScope(scope.value)}
                            />
                            <label
                              htmlFor={scope.value}
                              className="text-sm cursor-pointer"
                            >
                              {scope.label}
                            </label>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
                <p className="text-xs text-muted-foreground">
                  {t('apiKey.scopesHint')}
                </p>
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>
                {tCommon('cancel')}
              </Button>
              <Button onClick={handleCreate}>{tCommon('create')}</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      {/* 新创建的密钥显示 */}
      {newKeyVisible && newKey && (
        <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <Key className="h-5 w-5 text-yellow-600 mt-0.5" />
            <div className="flex-1">
              <h3 className="font-medium text-yellow-800 dark:text-yellow-200">
                {t('apiKey.saveKeyTitle')}
              </h3>
              <p className="text-sm text-yellow-700 dark:text-yellow-300 mt-1">
                {t('apiKey.saveKeyDescription')}
              </p>
              <div className="flex items-center gap-2 mt-3">
                <code className="flex-1 bg-yellow-100 dark:bg-yellow-900/40 px-3 py-2 rounded text-sm font-mono break-all">
                  {newKey}
                </code>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => copyToClipboard(newKey)}
                >
                  {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                </Button>
              </div>
              <Button
                variant="ghost"
                size="sm"
                className="mt-2"
                onClick={() => {
                  setNewKeyVisible(false)
                  setNewKey('')
                }}
              >
                {t('apiKey.savedButton')}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* API密钥列表 */}
      <div className="border rounded-lg">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{t('apiKey.name')}</TableHead>
              <TableHead>{t('apiKey.keyPrefix')}</TableHead>
              <TableHead>{t('apiKey.scopes')}</TableHead>
              <TableHead>{t('apiKey.rateLimit')}</TableHead>
              <TableHead>{t('apiKey.status')}</TableHead>
              <TableHead>{t('apiKey.lastUsed')}</TableHead>
              <TableHead>{tCommon('createdAt')}</TableHead>
              <TableHead className="w-[100px]">{tCommon('actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={8} className="text-center py-8">
                  {tCommon('loading')}
                </TableCell>
              </TableRow>
            ) : apiKeys.length === 0 ? (
              <TableRow>
                <TableCell colSpan={8} className="text-center py-8 text-muted-foreground">
                  {t('apiKey.noKeys')}
                </TableCell>
              </TableRow>
            ) : (
              apiKeys.map((key) => (
                <TableRow key={key.id}>
                  <TableCell>
                    <div>
                      <div className="font-medium">{key.name}</div>
                      {key.description && (
                        <div className="text-sm text-muted-foreground">{key.description}</div>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <code className="text-sm bg-muted px-2 py-1 rounded">
                      {key.keyPrefix}...
                    </code>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-wrap gap-1 max-w-[200px]">
                      {key.scopes.length === 0 ? (
                        <Badge variant="outline">{t('apiKey.allScopes')}</Badge>
                      ) : (
                        key.scopes.slice(0, 3).map((scope) => (
                          <Badge key={scope} variant="secondary" className="text-xs">
                            {scope}
                          </Badge>
                        ))
                      )}
                      {key.scopes.length > 3 && (
                        <Badge variant="outline" className="text-xs">
                          +{key.scopes.length - 3}
                        </Badge>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>{key.rateLimit}{t('apiKey.perMinute')}</TableCell>
                  <TableCell>
                    <Badge variant={key.isActive ? 'default' : 'secondary'}>
                      {key.isActive ? t('apiKey.active') : t('apiKey.inactive')}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    {key.lastUsedAt
                      ? formatDateTime(key.lastUsedAt)
                      : t('apiKey.neverUsed')}
                  </TableCell>
                  <TableCell>
                    {formatDateTime(key.createdAt)}
                  </TableCell>
                  <TableCell>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-destructive hover:text-destructive"
                      onClick={() => {
                        setSelectedKey(key)
                        setDeleteDialogOpen(true)
                      }}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* 使用说明 */}
      <div className="bg-muted/50 rounded-lg p-4">
        <h3 className="font-medium mb-2">{t('apiKey.usageTitle')}</h3>
        <div className="text-sm text-muted-foreground space-y-1">
          <p>1. {t('apiKey.usage1')} <code className="bg-muted px-1 rounded">X-API-Key: your-api-key</code></p>
          <p>2. {t('apiKey.usage2')}</p>
          <p>3. {t('apiKey.usage3')}</p>
          <p>4. {t('apiKey.usage4')}</p>
        </div>
      </div>

      {/* 删除确认对话框 */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('apiKey.deleteTitle')}</AlertDialogTitle>
            <AlertDialogDescription>
              {t('apiKey.deleteDescription', { name: selectedKey?.name || '' })}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{tCommon('cancel')}</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {tCommon('delete')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState, useEffect, Suspense, useMemo } from 'react'
import Link from 'next/link'
import { useRouter, useSearchParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { Plus, Layers, RefreshCw, Copy, MoreHorizontal, Eye, Pencil, Lock, Unlock, Trash2, Loader2, Printer, ExternalLink } from 'lucide-react'
import { ColumnDef, PaginationState, SortingState, RowSelectionState } from '@tanstack/react-table'
import { Button } from '@/components/ui/button'
import { Breadcrumb } from '@/components/ui/breadcrumb'
import { DataTable, DataTableColumnHeader } from '@/components/ui/data-table'
import { Badge } from '@/components/ui/badge'
import { Checkbox } from '@/components/ui/checkbox'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { BinLocationFilter } from '@/components/bin-locations/bin-location-filter'
import { BinLocationStatusBadge } from '@/components/bin-locations/bin-location-status-badge'
import { BinLocationLockBadge } from '@/components/bin-locations/bin-location-lock-badge'
import { usePrintStore } from '@/stores/print-store'
import { createBreadcrumbFactory } from '@/lib/navigation/breadcrumbs'

interface BinLocation {
  id: string
  locationCode: string
  aisle: string | null
  rack: string | null
  shelf: string | null
  bin: string | null
  locationType: string | null
  lockStatus: string
  isPickable: boolean
  isReceivable: boolean
  status: string
  createdAt: string
  zone: {
    id: string
    zoneCode: string
    zoneName: string | null
  }
  warehouse: {
    id: string
    warehouseCode: string
    warehouseName: string
  }
}

interface Zone {
  id: string
  zoneCode: string
  zoneName: string | null
  warehouseId: string
}

// MORE_CONTENT_PLACEHOLDER

const lockOptions = ['UNLOCKED', 'LOCKED'] as const
const statusOptions = ['ACTIVE', 'INACTIVE'] as const

function BinLocationsContent() {
  const t = useTranslations('binLocation')
  const tCommon = useTranslations('common')
  const tMenuGroup = useTranslations('menuGroup')
  const breadcrumb = createBreadcrumbFactory({
    parents: [{ label: tMenuGroup('warehouseInfrastructure') }],
    module: { label: t('title'), href: '/bin-locations' },
  })
  const router = useRouter()
  const searchParams = useSearchParams()

  const [binLocations, setBinLocations] = useState<BinLocation[]>([])
  const [zones, setZones] = useState<Zone[]>([])
  const [loading, setLoading] = useState(true)
  const [total, setTotal] = useState(0)
  const [loadingId, setLoadingId] = useState<string | null>(null)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [binToDelete, setBinToDelete] = useState<BinLocation | null>(null)
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({})
  const [printing, setPrinting] = useState(false)

  const { isConnected, connect } = usePrintStore()

  const page = parseInt(searchParams.get('page') || '1')
  const pageSize = parseInt(searchParams.get('pageSize') || '20', 10)
  const sortBy = searchParams.get('sortBy') || ''
  const sortOrder = searchParams.get('sortOrder') || ''

  const pagination: PaginationState = {
    pageIndex: page - 1,
    pageSize,
  }

  // 从URL参数恢复排序状态
  const sorting: SortingState = sortBy
    ? [{ id: sortBy, desc: sortOrder === 'desc' }]
    : []

  const fetchZones = async () => {
    try {
      const res = await fetch('/api/v1/zones?pageSize=500&status=ACTIVE')
      const data = await res.json()
      if (data.success) {
        setZones(data.data)
      }
    } catch (error) {
      console.error('Failed to fetch zones:', error)
    }
  }

  const fetchBinLocations = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams(searchParams.toString())
      params.set('pageSize', pageSize.toString())
      if (!params.has('page')) params.set('page', '1')

      const res = await fetch(`/api/v1/bin-locations?${params}`)
      const data = await res.json()
      if (data.success) {
        setBinLocations(data.data)
        setTotal(data.pagination.total)
      }
    } catch (error) {
      console.error('Failed to fetch bin locations:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchZones()
    // 尝试连接打印中间件
    connect()
  }, [])

  useEffect(() => {
    fetchBinLocations()
  }, [searchParams])

  const handlePaginationChange = (newPagination: PaginationState) => {
    const params = new URLSearchParams(searchParams.toString())
    params.set('page', (newPagination.pageIndex + 1).toString())
    params.set('pageSize', newPagination.pageSize.toString())
    router.push(`/bin-locations?${params.toString()}`)
  }

  const handleSortingChange = (newSorting: SortingState) => {
    const params = new URLSearchParams(searchParams.toString())
    params.set('page', '1') // 排序变化时重置到第一页
    if (newSorting.length > 0) {
      params.set('sortBy', newSorting[0].id)
      params.set('sortOrder', newSorting[0].desc ? 'desc' : 'asc')
    } else {
      params.delete('sortBy')
      params.delete('sortOrder')
    }
    router.push(`/bin-locations?${params.toString()}`)
  }

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text)
    toast.success(tCommon('copySuccess'))
  }

  const handleStatusChange = async (binId: string, newStatus: string) => {
    setLoadingId(binId)
    try {
      const response = await fetch(`/api/v1/bin-locations/${binId}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      const result = await response.json()
      if (result.success) {
        toast.success(t('statusUpdateSuccess'))
        fetchBinLocations()
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoadingId(null)
    }
  }

  const handleLockChange = async (binId: string, newLockStatus: string) => {
    setLoadingId(binId)
    try {
      const response = await fetch(`/api/v1/bin-locations/${binId}/lock`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ lockStatus: newLockStatus }),
      })
      const result = await response.json()
      if (result.success) {
        toast.success(t('lockUpdateSuccess'))
        fetchBinLocations()
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoadingId(null)
    }
  }

  const handleDelete = async () => {
    if (!binToDelete) return
    setLoadingId(binToDelete.id)
    try {
      const response = await fetch(`/api/v1/bin-locations/${binToDelete.id}`, {
        method: 'DELETE',
      })
      const result = await response.json()
      if (result.success) {
        toast.success(t('deleteSuccess'))
        fetchBinLocations()
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoadingId(null)
      setDeleteDialogOpen(false)
      setBinToDelete(null)
    }
  }

  // 获取选中的货位ID列表
  const selectedIds = useMemo(() => {
    return Object.keys(rowSelection).filter(key => rowSelection[key]).map(index => binLocations[parseInt(index)]?.id).filter(Boolean)
  }, [rowSelection, binLocations])

  // 浏览器打印（降级方案）
  const fallbackBrowserPrint = async (ids: string[]) => {
    const pdfUrl = `/api/v1/files/bin-location-label/batch?ids=${ids.join(',')}`
    const response = await fetch(pdfUrl)

    if (!response.ok) {
      throw new Error('生成标签失败')
    }

    const blob = await response.blob()
    const url = URL.createObjectURL(blob)

    const printWindow = window.open(url, '_blank')
    if (printWindow) {
      printWindow.onload = () => {
        printWindow.print()
      }
    }

    setTimeout(() => URL.revokeObjectURL(url), 60000)
  }

  // 批量打印
  const handleBatchPrint = async () => {
    if (selectedIds.length === 0) {
      toast.error(t('selectToPrint'))
      return
    }

    setPrinting(true)
    try {
      await fallbackBrowserPrint(selectedIds)
      toast.success(t('printSuccess'))
    } catch {
      toast.error(t('printError'))
    } finally {
      setPrinting(false)
    }
  }

  // 单个打印
  const handleSinglePrint = async (binId: string) => {
    try {
      await fallbackBrowserPrint([binId])
    } catch {
      toast.error(t('printError'))
    }
  }

  // 打开打印设置页面
  const openPrintSettings = () => {
    window.open('/settings/print', '_blank')
  }

// COLUMNS_PLACEHOLDER

  const columns: ColumnDef<BinLocation>[] = useMemo(
    () => [
      {
        id: 'select',
        header: ({ table }) => (
          <Checkbox
            checked={table.getIsAllPageRowsSelected()}
            onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
            aria-label="Select all"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(!!value)}
            aria-label="Select row"
          />
        ),
        size: 40,
        enableSorting: false,
        enableHiding: false,
      },
      {
        accessorKey: 'locationCode',
        header: ({ column }) => <DataTableColumnHeader column={column} title={t('code')} />,
        size: 150,
        cell: ({ row }) => {
          const bin = row.original
          return (
            <div className="flex items-center gap-1">
              <Link
                href={`/bin-locations/${bin.id}`}
                className="font-mono text-xs text-primary hover:underline"
              >
                {bin.locationCode}
              </Link>
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 shrink-0"
                onClick={() => handleCopy(bin.locationCode)}
              >
                <Copy className="h-3 w-3" />
              </Button>
            </div>
          )
        },
      },
      {
        accessorKey: 'warehouse',
        header: t('warehouse'),
        size: 100,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs">{row.original.warehouse?.warehouseCode || '-'}</span>,
      },
      {
        accessorKey: 'zone',
        header: t('zone'),
        size: 100,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs">{row.original.zone?.zoneCode || '-'}</span>,
      },
      {
        accessorKey: 'location',
        header: t('location'),
        size: 120,
        enableSorting: false,
        cell: ({ row }) => {
          const bin = row.original
          return (
            <span className="text-xs">
              {[bin.aisle, bin.rack, bin.shelf, bin.bin].filter(Boolean).join('-') || '-'}
            </span>
          )
        },
      },
      {
        accessorKey: 'locationType',
        header: t('type'),
        size: 80,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs">{row.original.locationType || '-'}</span>,
      },
      {
        accessorKey: 'flags',
        header: t('flags'),
        size: 80,
        enableSorting: false,
        cell: ({ row }) => {
          const bin = row.original
          return (
            <div className="flex gap-1">
              {bin.isPickable && <Badge variant="outline" className="text-xs px-1">P</Badge>}
              {bin.isReceivable && <Badge variant="outline" className="text-xs px-1">R</Badge>}
            </div>
          )
        },
      },
      {
        accessorKey: 'lockStatus',
        header: ({ column }) => <DataTableColumnHeader column={column} title={t('lock')} />,
        size: 80,
        cell: ({ row }) => <BinLocationLockBadge lockStatus={row.original.lockStatus} />,
      },
      {
        accessorKey: 'status',
        header: ({ column }) => <DataTableColumnHeader column={column} title={t('statusLabel')} />,
        size: 80,
        cell: ({ row }) => <BinLocationStatusBadge status={row.original.status} />,
      },
      {
        id: 'actions',
        header: () => <div className="text-center">{tCommon('actions')}</div>,
        size: 60,
        meta: { sticky: 'right' as const },
        cell: ({ row }) => {
          const bin = row.original
          return (
            <div className="text-center">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="icon" className="h-7 w-7" disabled={loadingId === bin.id}>
                    <MoreHorizontal className="h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuItem asChild>
                    <Link href={`/bin-locations/${bin.id}`} className="flex items-center">
                      <Eye className="mr-2 h-4 w-4" />
                      {tCommon('view')}
                    </Link>
                  </DropdownMenuItem>
                  <DropdownMenuItem asChild>
                    <Link href={`/bin-locations/${bin.id}/edit`} className="flex items-center">
                      <Pencil className="mr-2 h-4 w-4" />
                      {tCommon('edit')}
                    </Link>
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleSinglePrint(bin.id)}>
                    <Printer className="mr-2 h-4 w-4" />
                    {t('print')}
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem className="text-muted-foreground" disabled>
                    <Lock className="h-4 w-4 mr-2" />
                    {t('changeLock')}
                  </DropdownMenuItem>
                  {lockOptions.map((lock) => (
                    <DropdownMenuItem
                      key={lock}
                      onClick={() => handleLockChange(bin.id, lock)}
                      disabled={bin.lockStatus === lock}
                    >
                      {lock === 'UNLOCKED' ? <Unlock className="h-4 w-4 mr-2" /> : <Lock className="h-4 w-4 mr-2" />}
                      {t(`lockStatus.${lock}`)}
                    </DropdownMenuItem>
                  ))}
                  <DropdownMenuSeparator />
                  <DropdownMenuItem className="text-muted-foreground" disabled>
                    {t('changeStatus')}
                  </DropdownMenuItem>
                  {statusOptions.map((status) => (
                    <DropdownMenuItem
                      key={status}
                      onClick={() => handleStatusChange(bin.id, status)}
                      disabled={bin.status === status}
                    >
                      {t(`status.${status}`)}
                    </DropdownMenuItem>
                  ))}
                  <DropdownMenuSeparator />
                  <DropdownMenuItem
                    className="text-destructive"
                    onClick={() => { setBinToDelete(bin); setDeleteDialogOpen(true) }}
                  >
                    <Trash2 className="h-4 w-4 mr-2" />
                    {tCommon('delete')}
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          )
        },
      },
    ],
    [t, tCommon, loadingId]
  )

// RETURN_PLACEHOLDER

  return (
    <div className="flex flex-col h-full gap-2">
      <div className="flex items-center justify-between flex-shrink-0">
        <Breadcrumb items={breadcrumb.list()} />
        <div className="flex items-center gap-2">
          <Button variant="outline" size="icon" onClick={fetchBinLocations}>
            <RefreshCw className="h-4 w-4" />
          </Button>
          <Link href="/bin-locations/bulk-create">
            <Button variant="outline">
              <Layers className="h-4 w-4 mr-2" />
              {t('bulkCreate')}
            </Button>
          </Link>
          <Link href="/bin-locations/create">
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              {t('create')}
            </Button>
          </Link>
        </div>
      </div>

      <BinLocationFilter zones={zones} />

      {selectedIds.length > 0 && (
        <div className="flex items-center gap-4 p-3 bg-muted rounded-lg flex-shrink-0">
          <span className="text-sm">
            {t('selectedCount', { count: selectedIds.length })}
          </span>
          <Button
            size="sm"
            onClick={handleBatchPrint}
            disabled={printing}
          >
            {printing ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Printer className="h-4 w-4 mr-1" />}
            {t('batchPrint')}
          </Button>
          {!isConnected && (
            <Button
              size="sm"
              variant="outline"
              onClick={openPrintSettings}
            >
              <ExternalLink className="h-4 w-4 mr-1" />
              {t('printSettings')}
            </Button>
          )}
          <Button
            size="sm"
            variant="outline"
            onClick={() => setRowSelection({})}
          >
            {tCommon('cancel')}
          </Button>
        </div>
      )}

      <div className="flex-1 min-h-0">
        <DataTable
          tableId="bin-locations-list"
          columns={columns}
          data={binLocations}
          total={total}
          pagination={pagination}
          sorting={sorting}
          onPaginationChange={handlePaginationChange}
          onSortingChange={handleSortingChange}
          loading={loading}
          enableSorting={true}
          enableColumnVisibility={false}
          enableRowSelection={true}
          showSelectionCount={false}
          rowSelection={rowSelection}
          onRowSelectionChange={setRowSelection}
          maxHeight="100%"
        />
      </div>

      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('confirmDelete')}</AlertDialogTitle>
            <AlertDialogDescription>
              {t('confirmDeleteDesc', { name: binToDelete?.locationCode || '' })}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{tCommon('cancel')}</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>
              {tCommon('confirm')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

