            >
              {t('confirm')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useTranslations } from 'next-intl'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { Search, Plus, RefreshCw, Snowflake } from 'lucide-react'
import Link from 'next/link'
import { Breadcrumb } from '@/components/ui/breadcrumb'
import { formatDateTime } from '@/lib/utils/date-formatter'
import { createBreadcrumbFactory } from '@/lib/navigation/breadcrumbs'

interface Freeze {
  id: string
  freezeNumber: string
  freezeType: string
  status: string
  reason: string
  totalItems: number
  totalQuantity: number
  createdAt: string
  releasedAt: string | null
  warehouse: {
    code: string
    name: string
  }
  createdByUser: {
    name: string
  }
  releasedByUser: {
    name: string
  } | null
  _count: {
    lines: number
  }
}

const statusColors: Record<string, string> = {
  FROZEN: 'bg-blue-100 text-blue-800',
  RELEASED: 'bg-green-100 text-green-800',
}

const typeColors: Record<string, string> = {
  QC_HOLD: 'bg-yellow-100 text-yellow-800',
  DEFECTIVE_HOLD: 'bg-red-100 text-red-800',
  EXPIRY_HOLD: 'bg-orange-100 text-orange-800',
  RECALL_HOLD: 'bg-purple-100 text-purple-800',
  COUNT_HOLD: 'bg-gray-100 text-gray-800',
  MANUAL_HOLD: 'bg-blue-100 text-blue-800',
}

export default function FreezesPage() {
  const t = useTranslations('common')
  const tFrz = useTranslations('inventory.freeze')
  const tMenuGroup = useTranslations('menuGroup')
  const breadcrumb = createBreadcrumbFactory({
    parents: [{ label: tMenuGroup('inventory') }],
    module: { label: tFrz('title'), href: '/inventory/freezes' },
  })

  const [freezes, setFreezes] = useState<Freeze[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState<string>('all')
  const [freezeType, setFreezeType] = useState<string>('all')
  const [page, setPage] = useState(1)
  const [total, setTotal] = useState(0)
  const pageSize = 20

  useEffect(() => {
    fetchFreezes()
  }, [status, freezeType, page])

  const fetchFreezes = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString(),
      })
      if (search) params.append('search', search)
      if (status && status !== 'all') params.append('status', status)
      if (freezeType && freezeType !== 'all') params.append('freezeType', freezeType)

      const response = await fetch(`/api/v1/inventory/freezes?${params}`)
      const result = await response.json()

      if (result.data) {
        setFreezes(result.data)
        setTotal(result.pagination?.total || 0)
      }
    } catch (error) {
      console.error('Failed to fetch freezes:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = () => {
    setPage(1)
    fetchFreezes()
  }

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return '-'
    return formatDateTime(dateStr)
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <Breadcrumb items={breadcrumb.list()} />
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={fetchFreezes}>
            <RefreshCw className="mr-2 h-4 w-4" />
            {t('refresh')}
          </Button>
          <Link href="/inventory/freezes/new">
            <Button>
              <Plus className="mr-2 h-4 w-4" />
              {tFrz('create')}
            </Button>
          </Link>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex gap-4">
            <div className="flex-1">
              <Input
                placeholder={tFrz('searchPlaceholder')}
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
              />
            </div>
            <Select value={status} onValueChange={(v) => { setStatus(v); setPage(1) }}>
              <SelectTrigger className="w-[150px]">
                <SelectValue placeholder={tFrz('filterByStatus')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{tFrz('allStatus')}</SelectItem>
                <SelectItem value="FROZEN">{tFrz('statuses.FROZEN')}</SelectItem>
                <SelectItem value="RELEASED">{tFrz('statuses.RELEASED')}</SelectItem>
              </SelectContent>
            </Select>
            <Select value={freezeType} onValueChange={(v) => { setFreezeType(v); setPage(1) }}>
              <SelectTrigger className="w-[150px]">
                <SelectValue placeholder={tFrz('filterByType')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{tFrz('allTypes')}</SelectItem>
                <SelectItem value="QC_HOLD">{tFrz('types.QC_HOLD')}</SelectItem>
                <SelectItem value="DEFECTIVE_HOLD">{tFrz('types.DEFECTIVE_HOLD')}</SelectItem>
                <SelectItem value="EXPIRY_HOLD">{tFrz('types.EXPIRY_HOLD')}</SelectItem>
                <SelectItem value="RECALL_HOLD">{tFrz('types.RECALL_HOLD')}</SelectItem>
                <SelectItem value="COUNT_HOLD">{tFrz('types.COUNT_HOLD')}</SelectItem>
                <SelectItem value="MANUAL_HOLD">{tFrz('types.MANUAL_HOLD')}</SelectItem>
              </SelectContent>
            </Select>
            <Button onClick={handleSearch}>
              <Search className="mr-2 h-4 w-4" />
              {t('search')}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Freezes List */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Snowflake className="h-5 w-5" />
            {tFrz('list')}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{tFrz('freezeNumber')}</TableHead>
                <TableHead>{tFrz('type')}</TableHead>
                <TableHead>{tFrz('status')}</TableHead>
                <TableHead>{tFrz('warehouse')}</TableHead>
                <TableHead>{tFrz('quantity')}</TableHead>
                <TableHead>{tFrz('reason')}</TableHead>
                <TableHead>{tFrz('createdBy')}</TableHead>
                <TableHead>{tFrz('createdAt')}</TableHead>
                <TableHead>{t('actions')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={9} className="text-center py-8">
                    {t('loading')}
                  </TableCell>
                </TableRow>
              ) : freezes.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={9} className="text-center py-8">
                    {t('noData')}
                  </TableCell>
                </TableRow>
              ) : (
                freezes.map((item) => (
                  <TableRow key={item.id}>
                    <TableCell className="font-medium">{item.freezeNumber}</TableCell>
                    <TableCell>
                      <Badge className={typeColors[item.freezeType] || ''}>
                        {tFrz(`types.${item.freezeType}` as const)}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge className={statusColors[item.status] || ''}>
                        {tFrz(`statuses.${item.status}` as const)}
                      </Badge>
                    </TableCell>
                    <TableCell>{item.warehouse?.name}</TableCell>
                    <TableCell>{item.totalQuantity}</TableCell>
                    <TableCell className="max-w-[200px] truncate" title={item.reason}>
                      {item.reason}
                    </TableCell>
                    <TableCell>{item.createdByUser?.name}</TableCell>
                    <TableCell>{formatDate(item.createdAt) || '-'}</TableCell>
                    <TableCell>
                      <Link href={`/inventory/freezes/${item.id}`}>
                        <Button variant="ghost" size="sm">
                          {t('view')}
                        </Button>
                      </Link>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>

          {/* Pagination */}
          <div className="flex items-center justify-between mt-4">
            <div className="text-sm text-muted-foreground">
              {t('total', { count: total })}
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page <= 1}
                onClick={() => setPage(page - 1)}
              >
                {t('back')}
              </Button>
              <span className="text-sm">{t('page', { current: page, total: Math.ceil(total / pageSize) || 1 })}</span>
              <Button
                variant="outline"
                size="sm"
                disabled={page * pageSize >= total}
                onClick={() => setPage(page + 1)}
              >
                {t('confirm')}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import { useState, useEffect, use } from 'react'
import { useTranslations } from 'next-intl'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Send, Check, X, Play, ArrowLeftRight } from 'lucide-react'
import { toast } from 'sonner'
import { Breadcrumb } from '@/components/ui/breadcrumb'
import { formatDateTime } from '@/lib/utils/date-formatter'
import { createBreadcrumbFactory } from '@/lib/navigation/breadcrumbs'

interface TransferLine {
  id: string
  lineNumber: number
  skuId: string
  sku: { id: string; code: string; name: string }
  sourceLocationId: string
  sourceLocation: { id: string; code: string; name: string }
  targetLocationId: string
  targetLocation: { id: string; code: string; name: string }
  batchNumber: string | null
  quantity: number
  reason: string | null
  executedAt: string | null
}

interface Transfer {
  id: string
  transferNumber: string
  transferType: string
  status: string
  reason: string
  notes: string | null
  totalItems: number
  totalQuantity: number
  rejectReason: string | null
  createdAt: string
  submittedAt: string | null
  approvedAt: string | null
  executedAt: string | null
  warehouse: { id: string; name: string; code: string }
  createdByUser: { id: string; name: string } | null
  approvedByUser: { id: string; name: string } | null
  executedByUser: { id: string; name: string } | null
  lines: TransferLine[]
}

const statusColors: Record<string, string> = {
  DRAFT: 'bg-gray-100 text-gray-800',
  PENDING: 'bg-yellow-100 text-yellow-800',
  APPROVED: 'bg-blue-100 text-blue-800',
  REJECTED: 'bg-red-100 text-red-800',
  IN_TRANSIT: 'bg-purple-100 text-purple-800',
  COMPLETED: 'bg-green-100 text-green-800',
  CANCELLED: 'bg-gray-100 text-gray-800',
}

export default function TransferDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params)
  const t = useTranslations('common')
  const tTrf = useTranslations('inventory.transfer')
  const tMenuGroup = useTranslations('menuGroup')
  const breadcrumb = createBreadcrumbFactory({
    parents: [{ label: tMenuGroup('inventory') }],
    module: { label: tTrf('title'), href: '/inventory/transfers' },
  })

  const [transfer, setTransfer] = useState<Transfer | null>(null)
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [dialogOpen, setDialogOpen] = useState(false)
  const [dialogAction, setDialogAction] = useState<'submit' | 'approve' | 'reject' | 'execute'>('submit')
  const [rejectReason, setRejectReason] = useState('')

  useEffect(() => {
    fetchTransfer()
  }, [id])

  const fetchTransfer = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/v1/inventory/transfers/${id}`)
      const result = await response.json()
      if (result.data) {
        setTransfer(result.data)
      }
    } catch (error) {
      console.error('Failed to fetch transfer:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleAction = async () => {
    if (!transfer) return

    setActionLoading(true)
    try {
      const url = `/api/v1/inventory/transfers/${id}/${dialogAction}`
      let body: Record<string, unknown> = {}

      if (dialogAction === 'reject') {
        body = { reason: rejectReason }
      }

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })

      const result = await response.json()

      if (result.data) {
        toast.success(tTrf(`${dialogAction}Success`))
        fetchTransfer()
      } else {
        toast.error(result.error || '操作失败')
      }
    } catch (error) {
      console.error('Action failed:', error)
      toast.error('操作失败')
    } finally {
      setActionLoading(false)
      setDialogOpen(false)
      setRejectReason('')
    }
  }

  const openDialog = (action: 'submit' | 'approve' | 'reject' | 'execute') => {
    setDialogAction(action)
    setDialogOpen(true)
  }

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return '-'
    return formatDateTime(dateStr)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-muted-foreground">{t('loading')}</div>
      </div>
    )
  }

  if (!transfer) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-muted-foreground">转移单不存在</div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <Breadcrumb items={breadcrumb.current(tTrf('detail'))} />
        <div className="flex items-center gap-2">
          {transfer.status === 'DRAFT' && (
            <Button onClick={() => openDialog('submit')}>
              <Send className="mr-2 h-4 w-4" />
              {tTrf('submit')}
            </Button>
          )}
          {transfer.status === 'PENDING' && (
            <>
              <Button variant="outline" onClick={() => openDialog('reject')}>
                <X className="mr-2 h-4 w-4" />
                {tTrf('reject')}
              </Button>
              <Button onClick={() => openDialog('approve')}>
                <Check className="mr-2 h-4 w-4" />
                {tTrf('approve')}
              </Button>
            </>
          )}
          {transfer.status === 'APPROVED' && (
            <Button onClick={() => openDialog('execute')}>
              <Play className="mr-2 h-4 w-4" />
              {tTrf('execute')}
            </Button>
          )}
        </div>
      </div>

      {/* Basic Info */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ArrowLeftRight className="h-5 w-5" />
            基本信息
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-3 gap-4">
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('transferNumber')}</div>
              <div className="font-medium">{transfer.transferNumber}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('type')}</div>
              <Badge variant="outline">{tTrf(`types.${transfer.transferType}` as const)}</Badge>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('status')}</div>
              <Badge className={statusColors[transfer.status] || ''}>
                {tTrf(`statuses.${transfer.status}` as const)}
              </Badge>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('warehouse')}</div>
              <div className="font-medium">{transfer.warehouse?.name}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('totalQuantity')}</div>
              <div className="font-medium">{transfer.totalQuantity}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('reason')}</div>
              <div className="font-medium">{transfer.reason}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('createdBy')}</div>
              <div className="font-medium">{transfer.createdByUser?.name || '-'}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">{tTrf('createdAt')}</div>
              <div className="font-medium">{formatDate(transfer.createdAt) || '-'}</div>
            </div>
            {transfer.approvedByUser && (
              <div>
                <div className="text-sm text-muted-foreground">{tTrf('approvedBy')}</div>
                <div className="font-medium">{transfer.approvedByUser.name}</div>
              </div>
            )}
            {transfer.approvedAt && (
              <div>
                <div className="text-sm text-muted-foreground">{tTrf('approvedAt')}</div>
                <div className="font-medium">{formatDate(transfer.approvedAt) || '-'}</div>
              </div>
            )}
            {transfer.executedByUser && (
