        accessorKey: 'zone',
        header: tInv('zone'),
        size: 80,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs">{row.original.zone?.zoneName || row.original.zone?.zoneCode}</span>,
      },
      {
        accessorKey: 'location',
        header: tInv('location'),
        size: 100,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs font-mono">{row.original.location?.locationCode}</span>,
      },
      {
        accessorKey: 'batchNumber',
        header: tInv('batchNumber'),
        size: 100,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs">{row.original.batchNumber || '-'}</span>,
      },
      {
        accessorKey: 'asnNumber',
        header: tInv('asnNumber'),
        size: 180,
        enableSorting: false,
        cell: ({ row }) => {
          const asnNumber = row.original.asnNumber
          if (!asnNumber) return <span className="text-xs">-</span>
          return (
            <button
              onClick={() => handleAsnClick(asnNumber)}
              className="text-xs font-mono text-primary hover:underline block truncate text-left"
              title={asnNumber}
            >
              {asnNumber}
            </button>
          )
        },
      },
      {
        accessorKey: 'totalOnHand',
        header: ({ column }) => <DataTableColumnHeader column={column} title={tInv('onHand')} />,
        size: 80,
        cell: ({ row }) => <div className="text-xs font-bold">{getTotalQuantity(row.original)}</div>,
      },
      {
        accessorKey: 'quantityAvailable',
        header: ({ column }) => <DataTableColumnHeader column={column} title={tInv('available')} />,
        size: 80,
        cell: ({ row }) => <div className="text-xs text-green-600 font-medium">{row.original.quantityAvailable}</div>,
      },
      {
        accessorKey: 'quantityAllocated',
        header: ({ column }) => <DataTableColumnHeader column={column} title={tInv('allocated')} />,
        size: 80,
        cell: ({ row }) => <div className="text-xs text-blue-600">{row.original.quantityAllocated}</div>,
      },
      {
        accessorKey: 'quantityFrozen',
        header: ({ column }) => <DataTableColumnHeader column={column} title={tInv('frozen') || '冻结'} />,
        size: 70,
        cell: ({ row }) => <div className="text-xs text-orange-600">{row.original.quantityFrozen}</div>,
      },
      {
        accessorKey: 'quantityDefective',
        header: ({ column }) => <DataTableColumnHeader column={column} title={tInv('defective') || '不良品'} />,
        size: 70,
        cell: ({ row }) => <div className="text-xs text-red-600">{row.original.quantityDefective}</div>,
      },
      {
        accessorKey: 'expiryDate',
        header: tInv('expiryDate'),
        size: 100,
        enableSorting: false,
        cell: ({ row }) => <span className="text-xs">{formatDate(row.original.expiryDate) || '-'}</span>,
      },
      {
        accessorKey: 'lockStatus',
        header: tInv('lockStatus'),
