      <InventoryWmFilter />

      {/* Inventory List */}
      <div className="flex-1 min-h-0">
        <DataTable
          tableId="inventory-wm"
          columns={columns}
          data={inventories}
          total={total}
          pagination={pagination}
          onPaginationChange={handlePaginationChange}
          loading={loading}
          enableSorting={true}
          enableColumnVisibility={false}
          maxHeight="100%"
        />
      </div>

      {/* 库存调整对话框 */}
      <InventoryAdjustmentDialog
