                  <TableHead>{t('batchNumber')}</TableHead>
                  <TableHead>{t('expiryDate')}</TableHead>
                  <TableHead>{t('locationCode')}</TableHead>
                  <TableHead className="text-right">{t('expectedQty')}</TableHead>
