/**
 * PUT /api/v1/outbound-orders/by-number/[externalNumber]
 * 通过外部单号更新订单（外部API专用）
 *
 * 请求body:
 * - clientCode: 客户编码（如果API Key未绑定客户则必填）
 * - ...updateFields: 更新字段
 */
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ externalNumber: string }> }
) {
  const authResult = await authenticate(request)
  if (!authResult.success) {
      return NextResponse.json(
        { success: false, message: authResult.error || '未授权访问' },
        { status: 401 }
      )
    }

    const authContext = authResult.context!

  // 此接口仅供外部API调用
  if (authContext.type !== 'apiKey') {
    return NextResponse.json(
      { success: false, message: '此接口仅供外部API调用' },
      { status: 403 }
    )
  }

  if (!hasApiScope(authContext, 'order:write')) {
    return NextResponse.json(
      { success: false, message: '权限不足' },
      { status: 403 }
    )
  }

  return withUnifiedAuditContext(request, authContext, async () => {
    try {
      const { externalNumber } = await params
      const body = await request.json()

      // 验证请求数据
      const parseResult = externalUpdateOrderSchema.safeParse(body)
      if (!parseResult.success) {
        return NextResponse.json(
          { success: false, message: '参数错误', errors: parseResult.error.errors },
          { status: 400 }
        )
      }

      const { clientCode, ...updateData } = parseResult.data

      // 确定客户ID
      let clientId = authContext.clientId
      if (!clientId) {
        if (!clientCode) {
          return NextResponse.json(
            { success: false, message: '客户编码(clientCode)不能为空' },
            { status: 400 }
          )
        }
        // 通过clientCode查找客户
        const client = await prisma.client.findFirst({
          where: {
            tenantId: authContext.tenantId,
            clientCode,
          },
        })
        if (!client) {
          return NextResponse.json(
            { success: false, message: '客户不存在' },
            { status: 404 }
          )
        }
        clientId = client.id
      }

      // 查找订单（通过referenceNumber）
      const existingOrder = await prisma.outboundOrder.findFirst({
        where: {
          tenantId: authContext.tenantId,
          clientId,
          referenceNumber: externalNumber,
        },
        select: {
          id: true,
          status: true,
          outbound_address_id: true,
        },
      })

      if (!existingOrder) {
        return NextResponse.json(
          { success: false, message: '订单不存在' },
          { status: 404 }
        )
      }

      // 检查状态是否允许更新
      if (!['PENDING', 'ALLOCATED'].includes(existingOrder.status)) {
        return NextResponse.json(
          { success: false, message: `订单状态为${existingOrder.status}，不允许更新` },
          { status: 400 }
        )
      }

      const { consignee: consigneeData, shipping: shippingData, ...orderUpdateData } = updateData

      // 更新订单（如果有地址更新，同时更新地址）
      const updatedOrder = await prisma.$transaction(async (tx) => {
        // 如果有收货人信息更新且订单有关联地址
        if (consigneeData && existingOrder.outbound_address_id) {
          await tx.orderAddress.update({
            where: { id: existingOrder.outbound_address_id },
            data: {
              shippingName: consigneeData.name,
              shippingPhone: consigneeData.phone,
              shippingEmail: consigneeData.email,
              shippingCompany: consigneeData.company,
              shippingLine1: consigneeData.address?.line1,
              shippingLine2: consigneeData.address?.line2,
              shippingCity: consigneeData.address?.city,
              shippingProvince: consigneeData.address?.province,
              shippingPostalCode: consigneeData.address?.postalCode,
              shippingCountry: consigneeData.address?.country,
            },
          })
        }

        // 准备订单更新数据
        const orderData: any = {
          ...orderUpdateData,
          updatedAt: new Date(),
          updatedBy: authContext.userId,
        }

        // 处理运单号
        if (shippingData?.trackingNumber !== undefined) {
          orderData.trackingNumber = shippingData.trackingNumber
        }

        // 处理配送方式
        if (shippingData?.method !== undefined) {
          orderData.shippingMethod = shippingData.method
        }

        // 更新订单基本信息
        await tx.outboundOrder.update({
          where: { id: existingOrder.id },
          data: orderData,
        })

        // 处理发货面单
        if (shippingData?.shippingLabel) {
          let shippingLabelUrl: string | null = null
          let shippingLabelType: string | null = null

          const label = shippingData.shippingLabel

          if (label.base64) {
            // Base64格式：转换为文件
            try {
              const result = await shippingLabelStorage.saveBase64Image(
                authContext.tenantId,
                existingOrder.id,
                label.base64
              )
              shippingLabelUrl = result.url
              shippingLabelType = result.type
            } catch (error) {
              console.error('保存面单Base64失败:', error)
              // 不阻塞订单更新
            }
          } else if (label.url) {
            // URL格式：验证并直接保存
            if (shippingLabelStorage.validateUrl(label.url)) {
              shippingLabelUrl = label.url
              shippingLabelType = 'URL'
            } else {
              console.error('无效的面单URL格式:', label.url)
            }
          }

          // 更新扩展表
          if (shippingLabelUrl) {
            await tx.outboundOrderExtension.upsert({
              where: { orderId: existingOrder.id },
              create: {
                tenantId: authContext.tenantId,
                orderId: existingOrder.id,
                shippingLabelUrl,
                shippingLabelType,
              },
              update: {
                shippingLabelUrl,
                shippingLabelType,
              },
            })
          }
        }

        return tx.outboundOrder.findUnique({
          where: { id: existingOrder.id },
          select: {
            orderNumber: true,
            referenceNumber: true,
            orderType: true,
            orderSource: true,
            status: true,
            outbound_order_address: {
              select: {
                shippingName: true,
                shippingPhone: true,
                shippingEmail: true,
                shippingLine1: true,
                shippingCity: true,
                shippingProvince: true,
                shippingCountry: true,
                shippingPostalCode: true,
              },
            },
            shippingMethod: true,
            trackingNumber: true,
            notes: true,
            updatedAt: true,
            client: {
              select: { clientCode: true, clientName: true },
            },
            warehouse: {
              select: { warehouseCode: true, warehouseName: true },
            },
            extension: {
              select: {
                shippingLabelUrl: true,
                shippingLabelType: true,
              },
            },
          },
        })
      })

      return NextResponse.json({
        success: true,
        message: '订单更新成功',
        data: updatedOrder,
      })
    } catch (error) {
      console.error('更新订单失败:', error)
      return NextResponse.json(
        { success: false, message: '更新订单失败' },
        { status: 500 }
      )
    }
  })
}

/**
 * DELETE /api/v1/outbound-orders/by-number/[externalNumber]
 * 通过外部单号删除订单（外部API专用）
 *
 * 请求body:
 * - clientCode: 客户编码（如果API Key未绑定客户则必填）
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ externalNumber: string }> }
) {
  const authResult = await authenticate(request)
  if (!authResult.success) {
      return NextResponse.json(
        { success: false, message: authResult.error || '未授权访问' },
        { status: 401 }
      )
    }

    const authContext = authResult.context!

  // 此接口仅供外部API调用
  if (authContext.type !== 'apiKey') {
    return NextResponse.json(
      { success: false, message: '此接口仅供外部API调用' },
      { status: 403 }
    )
  }

  if (!hasApiScope(authContext, 'order:delete')) {
    return NextResponse.json(
      { success: false, message: '权限不足' },
      { status: 403 }
    )
  }

  return withUnifiedAuditContext(request, authContext, async () => {
    try {
      const { externalNumber } = await params

      // 解析请求body
      let body = {}
      try {
        body = await request.json()
      } catch {
        // DELETE请求可能没有body
      }

      const parseResult = externalDeleteOrderSchema.safeParse(body)
      if (!parseResult.success) {
        return NextResponse.json(
          { success: false, message: '参数错误', errors: parseResult.error.errors },
          { status: 400 }
        )
      }

      const { clientCode } = parseResult.data

      // 确定客户ID
      let clientId = authContext.clientId
      if (!clientId) {
        if (!clientCode) {
          return NextResponse.json(
            { success: false, message: '客户编码(clientCode)不能为空' },
            { status: 400 }
          )
        }
        // 通过clientCode查找客户
        const client = await prisma.client.findFirst({
          where: {
            tenantId: authContext.tenantId,
            clientCode,
          },
        })
        if (!client) {
          return NextResponse.json(
            { success: false, message: '客户不存在' },
            { status: 404 }
          )
        }
        clientId = client.id
      }

      // 查找订单（通过referenceNumber）
      const existingOrder = await prisma.outboundOrder.findFirst({
        where: {
          tenantId: authContext.tenantId,
          clientId,
          referenceNumber: externalNumber,
        },
      })

      if (!existingOrder) {
        return NextResponse.json(
          { success: false, message: '订单不存在' },
          { status: 404 }
        )
      }

      // 检查状态是否允许删除
      if (existingOrder.status !== 'PENDING') {
        return NextResponse.json(
          { success: false, message: `订单状态为${existingOrder.status}，只有待处理状态的订单可以删除` },
          { status: 400 }
        )
      }

      // 删除订单（级联删除明细）
      await prisma.outboundOrder.delete({
        where: { id: existingOrder.id },
      })

      return NextResponse.json({
        success: true,
        message: '订单删除成功',
      })
    } catch (error) {
      console.error('删除订单失败:', error)
      return NextResponse.json(
        { success: false, message: '删除订单失败' },
        { status: 500 }
      )
    }
  })
}

'use client'

import { useState, useEffect } from 'react'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { Warehouse, Star } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Badge } from '@/components/ui/badge'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { DropdownMenuItem } from '@/components/ui/dropdown-menu'

interface WarehouseItem {
  id: string
  warehouseCode: string
  warehouseName: string
  warehouseType: string
  city: string | null
  status: string
}

interface BoundWarehouse {
  id: string
  warehouseId: string
  isDefault: boolean
}

interface BindWarehouseDialogProps {
  clientId: string
  clientName: string
  onSuccess?: () => void
}

export function BindWarehouseDialog({
  clientId,
  clientName,
  onSuccess,
}: BindWarehouseDialogProps) {
  const t = useTranslations('client')
  const tCommon = useTranslations('common')

  const [open, setOpen] = useState(false)
  const [warehouses, setWarehouses] = useState<WarehouseItem[]>([])
  const [boundWarehouseIds, setBoundWarehouseIds] = useState<Set<string>>(new Set())
  const [selectedWarehouses, setSelectedWarehouses] = useState<string[]>([])
  const [defaultWarehouse, setDefaultWarehouse] = useState<string>('')
  const [loading, setLoading] = useState(false)
  const [fetching, setFetching] = useState(false)

  // 加载数据
  useEffect(() => {
    if (open) {
      fetchData()
    } else {
      // 重置状态
      setSelectedWarehouses([])
      setDefaultWarehouse('')
    }
  }, [open])

  const fetchData = async () => {
    setFetching(true)
    try {
      const [warehousesRes, boundRes] = await Promise.all([
        fetch('/api/v1/warehouses?pageSize=100&status=ACTIVE'),
        fetch(`/api/v1/clients/${clientId}/warehouses`),
      ])

      const warehousesData = await warehousesRes.json()
      const boundData = await boundRes.json()

      if (warehousesData.success) {
        setWarehouses(warehousesData.data)
      }

      if (boundData.success) {
        const boundIds = new Set<string>(
          boundData.data.map((item: BoundWarehouse) => item.warehouseId)
        )
        setBoundWarehouseIds(boundIds)
      }
    } catch (error) {
      console.error('Failed to fetch data:', error)
      toast.error(t('fetchFailed'))
    } finally {
      setFetching(false)
    }
  }

  const handleCheckboxChange = (warehouseId: string, checked: boolean) => {
    if (checked) {
      setSelectedWarehouses([...selectedWarehouses, warehouseId])
      // 如果是第一个选中的，自动设为默认
      if (selectedWarehouses.length === 0) {
        setDefaultWarehouse(warehouseId)
      }
    } else {
      setSelectedWarehouses(selectedWarehouses.filter((id) => id !== warehouseId))
      // 如果取消的是默认仓库，清除默认标记
      if (defaultWarehouse === warehouseId) {
        setDefaultWarehouse('')
      }
    }
  }

  const handleSubmit = async () => {
    if (selectedWarehouses.length === 0) {
      toast.error(t('selectWarehouses'))
      return
    }

    setLoading(true)
    try {
      let successCount = 0
      for (const warehouseId of selectedWarehouses) {
        const res = await fetch(`/api/v1/clients/${clientId}/warehouses`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            warehouseId,
            isDefault: warehouseId === defaultWarehouse,
          }),
        })

        const data = await res.json()
        if (data.success) {
          successCount++
        }
      }

      if (successCount > 0) {
        toast.success(t('bindSuccess'))
        setOpen(false)
        onSuccess?.()
      }
    } catch (error) {
      console.error('Failed to bind warehouses:', error)
      toast.error(t('bindFailed'))
    } finally {
      setLoading(false)
    }
  }

  const availableWarehouses = warehouses.filter(
    (w) => !boundWarehouseIds.has(w.id)
  )

  return (
    <>
      <DropdownMenuItem
        onSelect={(e) => {
          e.preventDefault()
          setOpen(true)
        }}
      >
        <Warehouse className="mr-2 h-4 w-4" />
        {t('bindWarehouse')}
      </DropdownMenuItem>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {t('bindWarehouse')} - {clientName}
            </DialogTitle>
          </DialogHeader>

          {fetching ? (
            <div className="flex items-center justify-center py-8">
              <div className="text-sm text-muted-foreground">{tCommon('loading')}</div>
            </div>
          ) : (
            <div className="space-y-4">
              {warehouses.length === 0 ? (
                <div className="text-center py-8 text-sm text-muted-foreground">
                  {t('noWarehousesAvailable')}
                </div>
              ) : (
                <>
                  <div className="text-sm text-muted-foreground">
                    {availableWarehouses.length > 0
                      ? t('selectWarehouses')
                      : t('allWarehousesBound')}
                  </div>
                  <div className="space-y-2">
                    {warehouses.map((warehouse) => {
                      const isBound = boundWarehouseIds.has(warehouse.id)
                      const isSelected = selectedWarehouses.includes(warehouse.id)
                      const isDefault = defaultWarehouse === warehouse.id

                      return (
                        <div
                          key={warehouse.id}
                          className="flex items-center gap-3 p-3 border rounded-lg hover:bg-accent/50 transition-colors"
                        >
                          <Checkbox
                            checked={isSelected}
                            disabled={isBound}
                            onCheckedChange={(checked) =>
                              handleCheckboxChange(warehouse.id, checked as boolean)
                            }
                          />
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="font-medium">{warehouse.warehouseName}</span>
                              <span className="text-xs text-muted-foreground">
                                ({warehouse.warehouseCode})
                              </span>
                              {isBound && (
                                <Badge variant="secondary" className="text-xs">
                                  {t('alreadyBound')}
                                </Badge>
                              )}
                            </div>
                            <div className="text-xs text-muted-foreground mt-1">
                              {warehouse.warehouseType} {warehouse.city && `· ${warehouse.city}`}
                            </div>
                          </div>
                          {isSelected && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-8 w-8 p-0"
                              onClick={() => setDefaultWarehouse(warehouse.id)}
                              title={t('setAsDefault')}
                            >
                              <Star
                                className={`h-4 w-4 ${
                                  isDefault ? 'fill-yellow-400 text-yellow-400' : 'text-gray-400'
                                }`}
                              />
                            </Button>
                          )}
                        </div>
                      )
                    })}
                  </div>
                </>
              )}
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)} disabled={loading}>
              {tCommon('cancel')}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={selectedWarehouses.length === 0 || loading || fetching}
            >
              {loading ? tCommon('submitting') : tCommon('confirm')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useEffect } from 'react'
