interface EditClientDialogProps {
  clientId: string
  trigger?: React.ReactNode
}

export function EditClientDialog({ clientId, trigger }: EditClientDialogProps) {
  const router = useRouter()
  const t = useTranslations('client')
  const tCommon = useTranslations('common')

  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [fetching, setFetching] = useState(false)
  const [formData, setFormData] = useState<ClientFormData>({
    clientCode: '',
    clientName: '',
    shortName: '',
    clientType: 'STANDARD',
    contactPerson: '',
    contactPhone: '',
    contactEmail: '',
    address: '',
    city: '',
    province: '',
    country: 'CN',
    postalCode: '',
    taxNumber: '',
    bankName: '',
    bankAccount: '',
    creditLimit: '',
    paymentTerms: '30',
    notes: '',
  })

  useEffect(() => {
    if (open) {
      fetchClient()
    }
  }, [open])

  const fetchClient = async () => {
    setFetching(true)
    try {
      const response = await fetch(`/api/v1/clients/${clientId}`)
      const result = await response.json()

      if (result.success) {
        const client = result.data
        setFormData({
          clientCode: client.clientCode,
          clientName: client.clientName,
          shortName: client.shortName || '',
          clientType: client.clientType,
          contactPerson: client.contactPerson || '',
          contactPhone: client.contactPhone || '',
          contactEmail: client.contactEmail || '',
          address: client.address || '',
          city: client.city || '',
          province: client.province || '',
          country: client.country || 'CN',
          postalCode: client.postalCode || '',
          taxNumber: client.taxNumber || '',
          bankName: client.bankName || '',
          bankAccount: client.bankAccount || '',
          creditLimit: client.creditLimit?.toString() || '',
          paymentTerms: client.paymentTerms?.toString() || '30',
          notes: client.notes || '',
        })
      } else {
        toast.error(result.message || tCommon('error'))
        setOpen(false)
      }
    } catch {
      toast.error(tCommon('error'))
      setOpen(false)
    } finally {
      setFetching(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)

    try {
      const response = await fetch(`/api/v1/clients/${clientId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...formData,
          creditLimit: formData.creditLimit ? parseFloat(formData.creditLimit) : null,
          paymentTerms: formData.paymentTerms ? parseInt(formData.paymentTerms) : 30,
        }),
      })

      const result = await response.json()

      if (result.success) {
        toast.success(t('updateSuccess'))
        router.refresh()
        // 延迟关闭对话框，确保刷新完成
        setTimeout(() => setOpen(false), 100)
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoading(false)
    }
  }

  const handleOpenChange = (newOpen: boolean) => {
    setOpen(newOpen)
  }

  return (
