'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { Eye, Pencil, MoreHorizontal, Power, PowerOff, Trash2, Printer } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { ContainerStatusBadge } from './container-status-badge'
import { ContainerTypeBadge } from './container-type-badge'
import { BatchStatusDialog } from './batch-status-dialog'
import { formatDateTime } from '@/lib/utils/date-formatter'

interface Container {
  id: string
  containerCode: string
  containerType: string
  containerTypeLabel: string
  usage: string
  usageLabel: string
  enabledStatus: string
  enabledStatusLabel: string
  workStatus: string
  workStatusLabel: string
  lastOccupiedTime?: Date | string | null
  weightCapacityKg?: number | null
  lengthCm?: number | null
  widthCm?: number | null
  heightCm?: number | null
  warehouse?: {
    id: string
    warehouseCode: string
    warehouseName: string
  }
  createdAt: Date | string
}

interface ContainerTableProps {
  containers: Container[]
  onRefresh?: () => void
}

export function ContainerTable({ containers, onRefresh }: ContainerTableProps) {
  const router = useRouter()
  const t = useTranslations('containers')
  const tCommon = useTranslations('common')

  const [loadingId, setLoadingId] = useState<string | null>(null)
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
  const [batchDialogOpen, setBatchDialogOpen] = useState(false)
  const [batchAction, setBatchAction] = useState<'ENABLED' | 'DISABLED'>('ENABLED')

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedIds(new Set(containers.map((c) => c.id)))
    } else {
      setSelectedIds(new Set())
    }
  }

  const handleSelectContainer = (id: string, checked: boolean) => {
    const newSelected = new Set(selectedIds)
    if (checked) {
      newSelected.add(id)
    } else {
      newSelected.delete(id)
    }
    setSelectedIds(newSelected)
  }

  const handleBatchSuccess = () => {
    setSelectedIds(new Set())
    onRefresh?.()
    router.refresh()
  }

  // 浏览器打印（降级方案）
  const fallbackBrowserPrint = async (ids: string[]) => {
    const pdfUrl = `/api/v1/files/container-label/batch?ids=${ids.join(',')}`
    const response = await fetch(pdfUrl)

    if (!response.ok) {
      throw new Error('生成标签失败')
    }

    const blob = await response.blob()
    const url = URL.createObjectURL(blob)

    const printWindow = window.open(url, '_blank')
    if (printWindow) {
      printWindow.onload = () => {
        printWindow.print()
      }
    }

    setTimeout(() => URL.revokeObjectURL(url), 60000)
  }

  const handleBatchPrint = async () => {
    const ids = Array.from(selectedIds)
    try {
      await fallbackBrowserPrint(ids)
    } catch {
      toast.error(t('printError'))
    }
  }

  const handleSinglePrint = async (containerId: string) => {
    try {
      await fallbackBrowserPrint([containerId])
    } catch {
      toast.error(t('printError'))
    }
  }

  const handleStatusChange = async (id: string, enabledStatus: 'ENABLED' | 'DISABLED') => {
    setLoadingId(id)
    try {
      const response = await fetch(`/api/v1/containers/${id}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabledStatus }),
      })

      const result = await response.json()

      if (result.success) {
        toast.success(result.message)
        onRefresh?.()
        router.refresh()
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoadingId(null)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm(t('confirmDelete'))) return

    setLoadingId(id)
    try {
      const response = await fetch(`/api/v1/containers/${id}`, {
        method: 'DELETE',
      })

      const result = await response.json()

      if (result.success) {
        toast.success(t('deleteSuccess'))
        onRefresh?.()
        router.refresh()
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoadingId(null)
    }
  }

  const formatDate = (dateValue: Date | string | null | undefined) => {
    if (!dateValue) return '-'
    const date = typeof dateValue === 'string' ? new Date(dateValue) : dateValue
    return formatDateTime(date)
  }

  const formatDimensions = (container: Container) => {
    if (container.lengthCm && container.widthCm && container.heightCm) {
      return `${container.lengthCm} × ${container.widthCm} × ${container.heightCm}`
    }
    return '-'
  }

  return (
    <div className="space-y-4">
      {selectedIds.size > 0 && (
        <div className="flex items-center gap-4 p-3 bg-muted rounded-lg">
          <span className="text-sm">
            {t('selectedCount', { count: selectedIds.size })}
          </span>
          <Button
            size="sm"
            onClick={() => {
              setBatchAction('ENABLED')
              setBatchDialogOpen(true)
            }}
          >
            <Power className="h-4 w-4 mr-1" />
            {t('batchEnable')}
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => {
              setBatchAction('DISABLED')
              setBatchDialogOpen(true)
            }}
          >
            <PowerOff className="h-4 w-4 mr-1" />
            {t('batchDisable')}
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={handleBatchPrint}
          >
            <Printer className="h-4 w-4 mr-1" />
            {t('batchPrint')}
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setSelectedIds(new Set())}
          >
            {tCommon('cancel')}
          </Button>
        </div>
      )}

      <div className="rounded-md border">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-12">
                <Checkbox
                  checked={containers.length > 0 && selectedIds.size === containers.length}
                  onCheckedChange={handleSelectAll}
                />
              </TableHead>
              <TableHead>{t('containerCode')}</TableHead>
              <TableHead>{t('containerType')}</TableHead>
              <TableHead>{t('usage')}</TableHead>
              <TableHead>{t('enabledStatus')}</TableHead>
              <TableHead>{t('warehouse')}</TableHead>
              <TableHead>{t('weightCapacityKg')}</TableHead>
              <TableHead>{t('lastOccupiedTime')}</TableHead>
              <TableHead className="text-right">{tCommon('actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {containers.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} className="text-center py-8 text-muted-foreground">
                  {tCommon('noData')}
                </TableCell>
              </TableRow>
            ) : (
              containers.map((container) => (
                <TableRow key={container.id}>
                  <TableCell>
                    <Checkbox
                      checked={selectedIds.has(container.id)}
                      onCheckedChange={(checked) =>
                        handleSelectContainer(container.id, checked as boolean)
                      }
                    />
                  </TableCell>
                  <TableCell className="font-medium">{container.containerCode}</TableCell>
                  <TableCell>
                    <ContainerTypeBadge type={container.containerType} />
                  </TableCell>
                  <TableCell>{container.usageLabel}</TableCell>
                  <TableCell>
                    <ContainerStatusBadge
                      enabledStatus={container.enabledStatus}
                      workStatus={container.workStatus}
                    />
                  </TableCell>
                  <TableCell>{container.warehouse?.warehouseName || '-'}</TableCell>
                  <TableCell>
                    {container.weightCapacityKg ? `${container.weightCapacityKg} kg` : '-'}
                  </TableCell>
                  <TableCell>{formatDate(container.lastOccupiedTime) || '-'}</TableCell>
                  <TableCell className="text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="sm"
                          disabled={loadingId === container.id}
                        >
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem asChild>
                          <Link href={`/containers/${container.id}`}>
                            <Eye className="h-4 w-4 mr-2" />
                            {tCommon('view')}
                          </Link>
                        </DropdownMenuItem>
                        <DropdownMenuItem asChild>
                          <Link href={`/containers/${container.id}/edit`}>
                            <Pencil className="h-4 w-4 mr-2" />
                            {tCommon('edit')}
                          </Link>
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleSinglePrint(container.id)}>
                          <Printer className="h-4 w-4 mr-2" />
                          {t('print')}
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        {container.enabledStatus === 'ENABLED' ? (
                          <DropdownMenuItem
                            onClick={() => handleStatusChange(container.id, 'DISABLED')}
                            disabled={container.workStatus === 'OCCUPIED'}
                          >
                            <PowerOff className="h-4 w-4 mr-2" />
                            {t('enabledStatuses.DISABLED')}
                          </DropdownMenuItem>
                        ) : (
                          <DropdownMenuItem
                            onClick={() => handleStatusChange(container.id, 'ENABLED')}
                          >
                            <Power className="h-4 w-4 mr-2" />
                            {t('enabledStatuses.ENABLED')}
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          className="text-destructive"
                          onClick={() => handleDelete(container.id)}
                          disabled={
                            container.enabledStatus !== 'DISABLED' ||
                            container.workStatus !== 'IDLE'
                          }
                        >
                          <Trash2 className="h-4 w-4 mr-2" />
                          {tCommon('delete')}
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <BatchStatusDialog
        open={batchDialogOpen}
        onOpenChange={setBatchDialogOpen}
        selectedContainerIds={Array.from(selectedIds)}
        targetStatus={batchAction}
        onSuccess={handleBatchSuccess}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useTranslations } from 'next-intl'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Textarea } from '@/components/ui/textarea'
import { Loader2 } from 'lucide-react'
import { toast } from 'sonner'

interface InventoryItem {
  id: string
  skuCode: string
  skuId: string
  batchNumber: string | null
  quantityAvailable: number
  warehouseId: string
  warehouse: {
    id: string
    warehouseCode: string
    warehouseName: string
  }
  location: {
    id: string
    locationCode: string
  }
  client?: {
    id: string
    clientCode: string
    clientName: string
  }
}

interface InventoryAdjustmentDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  inventoryItem: InventoryItem | null
  onSuccess?: () => void
}

// 表单验证schema
const adjustmentFormSchema = z.object({
  adjustmentType: z.enum(['INCREASE', 'DECREASE']),
  adjustmentQuantity: z.coerce.number().int().positive('调整数量必须为正整数'),
  adjustmentReason: z.enum(['SURPLUS', 'SHORTAGE', 'DAMAGE', 'OTHER']),
  notes: z.string().max(500).optional(),
})

type AdjustmentFormData = z.infer<typeof adjustmentFormSchema>

export function InventoryAdjustmentDialog({
  open,
  onOpenChange,
  inventoryItem,
  onSuccess,
}: InventoryAdjustmentDialogProps) {
  const t = useTranslations('common')
  const tAdj = useTranslations('inventory.adjustment')
  const [submitting, setSubmitting] = useState(false)

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    reset,
    formState: { errors },
  } = useForm<AdjustmentFormData>({
    resolver: zodResolver(adjustmentFormSchema),
    defaultValues: {
      adjustmentType: 'INCREASE',
      adjustmentQuantity: 1,
      adjustmentReason: 'SURPLUS',
      notes: '',
    },
  })

  const adjustmentType = watch('adjustmentType')
  const adjustmentQuantity = watch('adjustmentQuantity')

  // 计算调整后数量
  const quantityAfter = inventoryItem
    ? adjustmentType === 'INCREASE'
      ? inventoryItem.quantityAvailable + (adjustmentQuantity || 0)
      : inventoryItem.quantityAvailable - (adjustmentQuantity || 0)
    : 0

  // 重置表单
  useEffect(() => {
    if (open) {
      reset({
        adjustmentType: 'INCREASE',
        adjustmentQuantity: 1,
        adjustmentReason: 'SURPLUS',
        notes: '',
      })
    }
  }, [open, reset])

  // 调整原因映射
  const reasonMapping: Record<string, string> = {
    SURPLUS: '盘盈',
    SHORTAGE: '盘亏',
    DAMAGE: '损坏',
    OTHER: '其他',
  }

  // 调整类型映射到后端类型
  const typeMapping: Record<string, string> = {
    SURPLUS: 'INCREASE',
    SHORTAGE: 'DECREASE',
    DAMAGE: 'DAMAGE',
    OTHER: 'OTHER',
  }

  const onSubmit = async (data: AdjustmentFormData) => {
    if (!inventoryItem) return

    // 验证减少数量不能超过当前库存
    if (data.adjustmentType === 'DECREASE' && data.adjustmentQuantity > inventoryItem.quantityAvailable) {
      toast.error(tAdj('createFailed'), {
        description: '调整数量不能超过当前可用库存',
      })
      return
    }

    setSubmitting(true)

    try {
      // 计算调整数量（增加为正，减少为负）
      const adjustQuantity = data.adjustmentType === 'INCREASE'
        ? data.adjustmentQuantity
        : -data.adjustmentQuantity

      // 调用API创建调整单
      const response = await fetch('/api/v1/inventory/adjustments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          warehouseId: inventoryItem.warehouseId,
          adjustmentType: typeMapping[data.adjustmentReason],
          reason: reasonMapping[data.adjustmentReason],
          notes: data.notes || '',
          lines: [
            {
              skuId: inventoryItem.skuId,
              locationId: inventoryItem.location.id,
              batchNumber: inventoryItem.batchNumber || undefined,
              adjustQuantity,
              reason: reasonMapping[data.adjustmentReason],
            },
          ],
        }),
      })

      const result = await response.json()

      if (result.success) {
        toast.success(tAdj('createSuccess'), {
          description: `调整单号: ${result.data.adjustmentNumber}`,
        })
        onOpenChange(false)
        onSuccess?.()
      } else {
        toast.error(tAdj('createFailed'), {
          description: result.message || '创建调整单失败',
        })
      }
    } catch (error) {
      console.error('创建调整单失败:', error)
      toast.error(tAdj('createFailed'), {
        description: '网络错误，请稍后重试',
      })
    } finally {
      setSubmitting(false)
    }
  }

  if (!inventoryItem) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>{tAdj('adjustmentDialog')}</DialogTitle>
          <DialogDescription>
            {tAdj('adjustmentInfo')}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          {/* 库存信息展示 */}
          <div className="grid grid-cols-2 gap-4 p-4 bg-muted rounded-lg">
            <div>
              <Label className="text-muted-foreground">SKU</Label>
              <div className="font-medium">{inventoryItem.skuCode}</div>
            </div>
            <div>
              <Label className="text-muted-foreground">客户</Label>
              <div className="font-medium">{inventoryItem.client?.clientName || '-'}</div>
            </div>
            <div>
              <Label className="text-muted-foreground">库位</Label>
              <div className="font-medium">{inventoryItem.location.locationCode}</div>
            </div>
            <div>
              <Label className="text-muted-foreground">批次号</Label>
              <div className="font-medium">{inventoryItem.batchNumber || '-'}</div>
            </div>
            <div>
              <Label className="text-muted-foreground">{tAdj('quantityBefore')}</Label>
              <div className="font-medium text-lg">{inventoryItem.quantityAvailable}</div>
            </div>
            <div>
              <Label className="text-muted-foreground">{tAdj('quantityAfter')}</Label>
              <div className={`font-medium text-lg ${quantityAfter < 0 ? 'text-red-600' : 'text-green-600'}`}>
                {quantityAfter}
              </div>
            </div>
          </div>

          {/* 调整类型 */}
          <div className="space-y-2">
            <Label htmlFor="adjustmentType">{tAdj('adjustmentType')}</Label>
            <Select
              value={adjustmentType}
              onValueChange={(value) => setValue('adjustmentType', value as 'INCREASE' | 'DECREASE')}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="INCREASE">{tAdj('adjustmentTypes.INCREASE')}</SelectItem>
                <SelectItem value="DECREASE">{tAdj('adjustmentTypes.DECREASE')}</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* 调整数量 */}
          <div className="space-y-2">
            <Label htmlFor="adjustmentQuantity">{tAdj('adjustmentQuantity')}</Label>
            <Input
              id="adjustmentQuantity"
              type="number"
              min="1"
              {...register('adjustmentQuantity')}
              className={errors.adjustmentQuantity ? 'border-red-500' : ''}
            />
            {errors.adjustmentQuantity && (
              <p className="text-sm text-red-500">{errors.adjustmentQuantity.message}</p>
            )}
          </div>

          {/* 调整原因 */}
          <div className="space-y-2">
            <Label htmlFor="adjustmentReason">{tAdj('adjustmentReason')}</Label>
            <Select
              value={watch('adjustmentReason')}
              onValueChange={(value) => setValue('adjustmentReason', value as any)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="SURPLUS">{tAdj('adjustmentReasons.SURPLUS')}</SelectItem>
                <SelectItem value="SHORTAGE">{tAdj('adjustmentReasons.SHORTAGE')}</SelectItem>
                <SelectItem value="DAMAGE">{tAdj('adjustmentReasons.DAMAGE')}</SelectItem>
                <SelectItem value="OTHER">{tAdj('adjustmentReasons.OTHER')}</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* 备注 */}
          <div className="space-y-2">
            <Label htmlFor="notes">{tAdj('notes')}</Label>
            <Textarea
              id="notes"
              {...register('notes')}
              placeholder="可选"
              rows={3}
            />
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={submitting}
            >
              {t('cancel')}
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {t('confirm')}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useTranslations } from 'next-intl'
import { useForm, Controller } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { Textarea } from '@/components/ui/textarea'
import { Loader2, Check, ChevronsUpDown } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

interface InventoryBucketItem {
  id: string
  skuId: string
  skuCode: string
  skuName?: string
  batchNumber: string | null
  lpn: string
  expiryDate: string | null
  productionDate?: string | null
  bucketType: string
  quantity: number
  warehouseId: string
  warehouse: {
    id: string
    warehouseCode: string
    warehouseName: string
  }
  location: {
    id: string
    locationCode: string
  }
  client?: {
    id: string
    clientCode: string
    clientName: string
  }
}

interface Location {
  id: string
  locationCode: string
  locationName?: string
}

interface InventoryLocationAdjustmentDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  inventoryItem: InventoryBucketItem | null
  onSuccess?: () => void
}

// 表单验证schema
const adjustmentFormSchema = z.object({
  adjustmentQuantity: z.coerce.number().int().positive(),
  toLocationId: z.string().min(1),
  reason: z.string().min(1).max(500),
})

type AdjustmentFormData = z.infer<typeof adjustmentFormSchema>

export function InventoryLocationAdjustmentDialog({
  open,
  onOpenChange,
  inventoryItem,
  onSuccess,
}: InventoryLocationAdjustmentDialogProps) {
  const t = useTranslations('common')
  const tAdj = useTranslations('inventory.adjustment')
  const [submitting, setSubmitting] = useState(false)
  const [locations, setLocations] = useState<Location[]>([])
  const [loadingLocations, setLoadingLocations] = useState(false)
  const [locationOpen, setLocationOpen] = useState(false)
  const [locationSearch, setLocationSearch] = useState('')

  const {
    register,
    handleSubmit,
    watch,
    reset,
    control,
    formState: { errors },
  } = useForm<AdjustmentFormData>({
    resolver: zodResolver(adjustmentFormSchema),
    defaultValues: {
      adjustmentQuantity: 1,
      toLocationId: '',
      reason: '',
    },
  })

  const toLocationId = watch('toLocationId')

  // 获取库位列表
  useEffect(() => {
    if (open && inventoryItem) {
      fetchLocations()
    }
  }, [open, inventoryItem])

  const fetchLocations = async () => {
    if (!inventoryItem) return

    setLoadingLocations(true)
    try {
      const response = await fetch(`/api/v1/bin-locations?warehouseId=${inventoryItem.warehouseId}&pageSize=1000`)
      const result = await response.json()
      if (result.success) {
        setLocations(result.data)
      }
    } catch (error) {
      console.error('获取库位列表失败:', error)
    } finally {
      setLoadingLocations(false)
    }
  }

  // 重置表单
  useEffect(() => {
    if (open) {
      reset({
        adjustmentQuantity: 1,
        toLocationId: '',
        reason: '',
      })
      setLocationSearch('')
    }
  }, [open, reset])

  const onSubmit = async (data: AdjustmentFormData) => {
    if (!inventoryItem) return

    // 验证调整数量不能超过当前库存
    if (data.adjustmentQuantity > inventoryItem.quantity) {
      toast.error(tAdj('createFailed'), {
        description: tAdj('quantityExceedsStock'),
      })
      return
    }

    // 验证调整后库位不能与调整前库位相同
    if (data.toLocationId === inventoryItem.location.id) {
      toast.error(tAdj('createFailed'), {
        description: tAdj('locationCannotBeSame'),
      })
      return
    }

    setSubmitting(true)

    try {
      const toLocation = locations.find(loc => loc.id === data.toLocationId)

      // 调用API创建调整单
      const response = await fetch('/api/v1/inventory/adjustments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          warehouseId: inventoryItem.warehouseId,
          adjustmentType: 'LOCATION_ADJUST',
          reason: data.reason,
          notes: data.reason,
          lines: [
            {
              skuId: inventoryItem.skuId,
              fromLocationId: inventoryItem.location.id,
              fromLocationCode: inventoryItem.location.locationCode,
              toLocationId: data.toLocationId,
              toLocationCode: toLocation?.locationCode || '',
              batchNumber: inventoryItem.batchNumber || undefined,
              lpn: inventoryItem.lpn || undefined,
              expiryDate: inventoryItem.expiryDate || undefined,
              productionDate: inventoryItem.productionDate || undefined,
              bucketType: inventoryItem.bucketType,
              adjustQuantity: data.adjustmentQuantity,
              reason: data.reason,
            },
          ],
        }),
      })

      const result = await response.json()

      if (result.success) {
        // 立即执行调整单
        const executeResponse = await fetch(`/api/v1/inventory/adjustments/${result.data.id}/execute`, {
          method: 'POST',
        })

        const executeResult = await executeResponse.json()

        if (executeResult.success) {
          toast.success(tAdj('createSuccess'), {
            description: `${tAdj('adjustmentNumberLabel')}${result.data.adjustmentNumber}`,
          })
          onOpenChange(false)
          onSuccess?.()
        } else {
          toast.error(tAdj('createFailed'), {
            description: executeResult.message || tAdj('executeFailed'),
          })
        }
      } else {
        toast.error(tAdj('createFailed'), {
          description: result.message || tAdj('createFailedMessage'),
        })
      }
    } catch (error) {
      console.error('创建调整单失败:', error)
      toast.error(tAdj('createFailed'), {
        description: tAdj('networkError'),
      })
    } finally {
      setSubmitting(false)
    }
  }

  if (!inventoryItem) return null

  const selectedLocation = locations.find(loc => loc.id === toLocationId)

  // 过滤库位列表（支持模糊搜索）
  const filteredLocations = locations.filter(loc =>
    loc.locationCode.toLowerCase().includes(locationSearch.toLowerCase())
  )

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>{tAdj('locationAdjust')}</DialogTitle>
          <DialogDescription>
            {tAdj('adjustmentInfo')}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          {/* 库存信息展示 */}
          <div className="space-y-3">
            <div className="grid grid-cols-3 gap-x-4 gap-y-2 p-3 bg-muted/50 rounded-lg border text-sm">
              <div>
                <Label className="text-xs text-muted-foreground">SKU</Label>
                <div className="font-medium mt-0.5">{inventoryItem.skuCode}</div>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">{t('client')}</Label>
                <div className="font-medium mt-0.5">{inventoryItem.client?.clientName || '-'}</div>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">{tAdj('batchNumber')}</Label>
                <div className="font-medium mt-0.5">{inventoryItem.batchNumber || '-'}</div>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">{tAdj('bucketType')}</Label>
                <div className="font-medium mt-0.5">{tAdj(`bucketTypes.${inventoryItem.bucketType}`)}</div>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">{tAdj('currentQuantity')}</Label>
                <div className="font-medium mt-0.5">{inventoryItem.quantity}</div>
              </div>
            </div>

            {/* 库位对比 */}
            <div className="p-3 bg-amber-50 dark:bg-amber-950/20 rounded-lg border border-amber-200 dark:border-amber-900">
              <div className="flex items-center justify-between text-sm">
                <div>
                  <Label className="text-xs text-amber-700 dark:text-amber-400">{tAdj('locationBefore')}</Label>
                  <div className="font-bold text-base mt-1 text-amber-900 dark:text-amber-300">{inventoryItem.location.locationCode}</div>
                </div>
                <div className="text-amber-500 text-xl px-3">→</div>
                <div>
                  <Label className="text-xs text-amber-700 dark:text-amber-400">{tAdj('locationAfter')}</Label>
                  <div className="font-bold text-base mt-1 text-amber-900 dark:text-amber-300">
                    {selectedLocation ? selectedLocation.locationCode : tAdj('pleaseSelect')}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* 调整数量 */}
          <div className="space-y-2">
            <Label htmlFor="adjustmentQuantity">{tAdj('adjustmentQuantity')}</Label>
            <Input
              id="adjustmentQuantity"
              type="number"
              min="1"
              max={inventoryItem.quantity}
              {...register('adjustmentQuantity')}
              className={errors.adjustmentQuantity ? 'border-red-500' : ''}
            />
            {errors.adjustmentQuantity && (
              <p className="text-sm text-red-500">{errors.adjustmentQuantity.message}</p>
            )}
          </div>

          {/* 调整后库位 */}
          <div className="space-y-2">
            <Label htmlFor="toLocationId">{tAdj('locationAfter')}</Label>
            <Controller
              name="toLocationId"
              control={control}
              render={({ field }) => (
                <Popover open={locationOpen} onOpenChange={setLocationOpen}>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      role="combobox"
                      aria-expanded={locationOpen}
                      className={cn(
                        'w-full justify-between',
                        errors.toLocationId && 'border-red-500'
                      )}
                    >
                      {selectedLocation
                        ? selectedLocation.locationCode
                        : tAdj('selectLocation')}
                      <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-full p-0">
                    <Command shouldFilter={false}>
                      <CommandInput
                        placeholder={tAdj('searchLocation')}
                        value={locationSearch}
                        onValueChange={setLocationSearch}
                      />
                      <CommandEmpty>{tAdj('noLocationFound')}</CommandEmpty>
                      <CommandGroup className="max-h-64 overflow-auto">
                        {filteredLocations.map((location) => (
                          <CommandItem
                            key={location.id}
                            value={location.locationCode}
                            onSelect={() => {
                              field.onChange(location.id)
                              setLocationOpen(false)
                              setLocationSearch('')
                            }}
                          >
                            <Check
                              className={cn(
                                'mr-2 h-4 w-4',
                                field.value === location.id ? 'opacity-100' : 'opacity-0'
                              )}
                            />
                            {location.locationCode}
                          </CommandItem>
                        ))}
                      </CommandGroup>
                    </Command>
                  </PopoverContent>
                </Popover>
              )}
            />
            {errors.toLocationId && (
              <p className="text-sm text-red-500">{errors.toLocationId.message}</p>
            )}
          </div>

          {/* 调整原因 */}
          <div className="space-y-2">
            <Label htmlFor="reason">{tAdj('adjustmentReason')}</Label>
            <Textarea
              id="reason"
              {...register('reason')}
              placeholder={tAdj('reasonPlaceholder')}
              rows={3}
              className={errors.reason ? 'border-red-500' : ''}
            />
            {errors.reason && (
              <p className="text-sm text-red-500">{errors.reason.message}</p>
            )}
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={submitting}
            >
              {t('cancel')}
            </Button>
            <Button type="submit" disabled={submitting || loadingLocations}>
              {submitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {t('confirm')}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

