interface InventoryBucketItem {
  id: string
  skuId: string
  skuCode: string
  skuName?: string
  batchNumber: string | null
  lpn: string
  expiryDate: string | null
  productionDate?: string | null
  bucketType: string
  quantity: number
  warehouseId: string
  warehouse: {
