        <div className="col-span-2">
          <p className="text-sm text-muted-foreground">地址行1</p>
          <p className="font-medium">{address.shippingLine1 || '-'}</p>
        </div>
        <div className="col-span-2">
          <p className="text-sm text-muted-foreground">地址行2</p>
