  PackingModule,
  PackingModuleContext,
  SkuScanResult,
  CloseBoxResult,
  ModuleContentProps,
  ModuleScanInfoProps,
} from './types'
import { PickOrderHeaderCard } from '../pick-order-header-card'
import { PickOrderLinesTable } from '../pick-order-lines-table'

// 拣货单模式状态
export interface PickOrderModuleState {
  pendingCloseOrder: { orderId: string; orderNumber: string } | null
  serialNumberDialog: {
    open: boolean
    skuCode: string
    skuName: string | null
    barcode: string
    requiredQuantity: number
  } | null
}

// 获取订单类型显示文本
const getOrderTypeText = (type: string) => {
  switch (type) {
    case 'SINGLE_SKU_SINGLE':
      return '单品单件(同款)'
    case 'MULTI_SKU_SINGLE':
      return '单品单件(不同款)'
    case 'SINGLE_SKU_MULTI':
      return '单品多件'
    case 'MULTI_SKU_MULTI':
      return '多品多件'
    default:
      return type
  }
}

// SKU 扫描处理
async function onSkuScanned(
  barcode: string,
  context: PackingModuleContext,
  moduleState: PickOrderModuleState,
  setModuleState: (state: PickOrderModuleState) => void,
  updateLinePackedQty: (lineId: string, packedQty: number) => void,
  updatePickOrderTotals: (packedQty: number) => void,
  serialNumbers: string[] = []
): Promise<SkuScanResult> {
  // 检查是否有未关箱的订单
  if (moduleState.pendingCloseOrder) {
    return {
      success: false,
      message: `订单 ${moduleState.pendingCloseOrder.orderNumber} 未关箱，请先完成关箱操作`,
    }
  }

  const response = await fetch(`/api/v1/packing/${context.pickOrderId}/scan-sku`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      barcode,
      quantity: 1,
      serialNumbers,
    }),
  })

  if (!response.ok) {
    const error = await response.json()

    // 检查是否是序列号错误
    if (error.message && error.message.includes('需要扫描')) {
      // 提取需要的序列号数量
      const match = error.message.match(/需要扫描 (\d+) 个序列号/)
      const requiredQuantity = match ? parseInt(match[1]) : 1

      // 触发序列号扫描对话框
      return {
        success: false,
        message: error.message,
        requireSerialNumbers: true,
        requiredQuantity,
      }
    }

    return {
      success: false,
      message: error.message || 'SKU不在此拣货单中',
    }
  }

  const data = await response.json()
  const result = data.data

  // 更新本地状态
  updateLinePackedQty(result.lineId, result.packedQty)
  updatePickOrderTotals(1)

  // 如果订单打包完成，设置待关箱订单
  if (result.isOrderComplete) {
    setModuleState({
      ...moduleState,
      pendingCloseOrder: {
        orderId: result.orderId,
        orderNumber: result.orderNumber,
      },
      serialNumberDialog: null, // 确保清除序列号对话框状态
    })
    context.triggerFocusMaterial()
    return {
      success: true,
      message: `已打包 ${result.skuCode}`,
      isOrderComplete: true,
      orderId: result.orderId,
      orderNumber: result.orderNumber,
    }
  }

  // 订单未完成，继续扫描下一个SKU
  context.triggerFocusSku()

  return {
    success: true,
    message: `已打包 ${result.skuCode}`,
  }
}

// 关箱处理
async function onCloseBox(
  context: PackingModuleContext,
  moduleState: PickOrderModuleState,
  setModuleState: (state: PickOrderModuleState) => void
): Promise<CloseBoxResult> {
  if (!moduleState.pendingCloseOrder) {
    return { success: false, message: '没有待关箱的订单' }
  }

  // 验证包材
  if (context.packagingMaterials.length === 0) {
    return { success: false, message: '请选择包材' }
  }

  const response = await fetch(`/api/v1/packing/${context.pickOrderId}/complete-order`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      orderId: moduleState.pendingCloseOrder.orderId,
      packagingMaterials: context.packagingMaterials.map((m) => ({
        materialId: m.materialId,
        quantity: m.quantity,
      })),
    }),
  })

  if (!response.ok) {
    const error = await response.json()
    return { success: false, message: error.message || '关箱失败' }
  }

  const data = await response.json()
  const orderNumber = moduleState.pendingCloseOrder.orderNumber
  const isPickOrderComplete = data.data?.isPickOrderComplete

  // 清除待关箱状态
  setModuleState({ ...moduleState, pendingCloseOrder: null })
  context.clearPackagingMaterials()

  toast.success(`订单 ${orderNumber} 关箱完成`)

  // 如果拣货单全部完成，返回标志让页面清除状态
  if (isPickOrderComplete) {
    toast.info('拣货单已全部打包完成')
    return {
      success: true,
      labelData: data.data?.labelData,
      shouldClearPickOrder: true, // 清除拣货单，回到初始页面
    }
  }

  // 关箱成功后聚焦到SKU输入框
  context.triggerFocusSku()

  return {
    success: true,
    labelData: data.data?.labelData,
    shouldReload: true, // 拣货单模式需要重新加载数据
  }
}

// 扫描信息区域渲染
function PickOrderScanInfo({ moduleState }: { moduleState: PickOrderModuleState; orderSummary: { orderType: string; channel: string | null; skuCode: string; totalQty: number; unpackedQty: number } | null }) {
  return null // 订单汇总信息在 packing-scan-panel 中渲染
}

// 内容区域渲染
function PickOrderContent() {
  return (
    <div className="lg:col-span-2 space-y-4">
      <PickOrderHeaderCard />
      <PickOrderLinesTable />
    </div>
  )
}

// 创建拣货单模块实例
export function createPickOrderModule(): PackingModule & {
  getInitialState: () => PickOrderModuleState
  createHandlers: (
    updateLinePackedQty: (lineId: string, packedQty: number) => void,
    updatePickOrderTotals: (packedQty: number) => void
  ) => {
    onSkuScanned: (barcode: string, context: PackingModuleContext, moduleState: PickOrderModuleState, setModuleState: (state: PickOrderModuleState) => void, serialNumbers?: string[]) => Promise<SkuScanResult>
    onCloseBox: (context: PackingModuleContext, moduleState: PickOrderModuleState, setModuleState: (state: PickOrderModuleState) => void) => Promise<CloseBoxResult>
  }
} {
  return {
    type: 'PICK_ORDER',
    displayName: '拣货单模式',

    getInitialState: () => ({
      pendingCloseOrder: null,
      serialNumberDialog: null,
    }),

    createHandlers: (updateLinePackedQty, updatePickOrderTotals) => ({
      onSkuScanned: (barcode, context, moduleState, setModuleState, serialNumbers = []) =>
        onSkuScanned(barcode, context, moduleState, setModuleState, updateLinePackedQty, updatePickOrderTotals, serialNumbers),
      onCloseBox: (context, moduleState, setModuleState) =>
        onCloseBox(context, moduleState, setModuleState),
    }),

    // 基础接口实现（实际使用 createHandlers）
    onSkuScanned: async () => ({ success: false, message: '请使用 createHandlers' }),
    onCloseBox: async () => ({ success: false, message: '请使用 createHandlers' }),

    renderContent: () => <PickOrderContent />,
    renderScanInfo: ({ moduleState }: ModuleScanInfoProps<PickOrderModuleState>) => (
      <PickOrderScanInfo moduleState={moduleState} orderSummary={null} />
    ),
  }
}

export const pickOrderModule = createPickOrderModule()

'use client'

import { useState, useRef, useCallback, useEffect } from 'react'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { Loader2, ChevronDown, Trash2 } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
} from '@/components/ui/select'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { usePackingStore } from '@/stores/packing-store'
import type { OrderModuleState } from './modules'

interface OrderPackingScanPanelProps {
  onOrderLoaded: (orderNumber: string) => Promise<void>
  onSkuScanned: (barcode: string) => Promise<void>
  onCloseBox: () => Promise<void>
  moduleState: OrderModuleState | null
  isSubmitting: boolean
  initialOrderNumber?: string
  cellCode?: string | null
}

export function OrderPackingScanPanel({
  onOrderLoaded,
  onSkuScanned,
  onCloseBox,
  moduleState,
  isSubmitting,
  initialOrderNumber,
  cellCode,
}: OrderPackingScanPanelProps) {
  const {
    currentPickOrder,
    packagingMaterials,
    materialOptions,
    isLoading,
    shouldFocusSku,
    shouldFocusMaterial,
    shouldFocusTaskNumber,
    setIsLoading,
    clearFocusSku,
    clearFocusMaterial,
    clearFocusTaskNumber,
    addPackagingMaterial,
    removePackagingMaterial,
    updatePackagingMaterialQty,
    loadMaterialOptions,
  } = usePackingStore()

  const [orderInput, setOrderInput] = useState(initialOrderNumber || '')
  const [skuInput, setSkuInput] = useState('')
  const [materialInput, setMaterialInput] = useState('')
  const [selectedMaterialId, setSelectedMaterialId] = useState<string>('')

  const orderInputRef = useRef<HTMLInputElement>(null)
  const skuInputRef = useRef<HTMLInputElement>(null)
  const materialInputRef = useRef<HTMLInputElement>(null)

  // 当 moduleState 变化时，同步订单号到输入框
  useEffect(() => {
    if (moduleState?.orderNumber && !moduleState.isComplete) {
      setOrderInput(moduleState.orderNumber)
    }
  }, [moduleState?.orderNumber, moduleState?.isComplete])

  // 监听聚焦
  useEffect(() => {
    if (shouldFocusSku) {
      setTimeout(() => skuInputRef.current?.focus(), 100)
      clearFocusSku()
    }
  }, [shouldFocusSku, clearFocusSku])

  useEffect(() => {
    if (shouldFocusMaterial) {
      setTimeout(() => materialInputRef.current?.focus(), 100)
      clearFocusMaterial()
    }
  }, [shouldFocusMaterial, clearFocusMaterial])

  useEffect(() => {
    if (shouldFocusTaskNumber) {
      setOrderInput('')
      setTimeout(() => orderInputRef.current?.focus(), 100)
      clearFocusTaskNumber()
    }
  }, [shouldFocusTaskNumber, clearFocusTaskNumber])

  // 加载包材列表 - 只在有订单时加载（使用 store 统一管理）
  useEffect(() => {
    if (currentPickOrder) {
      loadMaterialOptions()
    }
  }, [currentPickOrder, loadMaterialOptions])

  // 模块状态
  const isComplete = moduleState?.isComplete
  const hasPendingClose = moduleState?.pendingCloseOrder
  // 已加载订单且未完成时锁定单号输入框
  const isOrderLocked = currentPickOrder && !isComplete

  // 扫描订单号
  const handleOrderSubmit = useCallback(async () => {
    if (!orderInput.trim()) return
    setIsLoading(true)
    try {
      await onOrderLoaded(orderInput.trim())
      // 成功后不清除，保持显示当前订单号
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '加载订单失败'
      toast.error(errorMessage)
      setOrderInput('')
      setTimeout(() => orderInputRef.current?.focus(), 50)
    } finally {
      setIsLoading(false)
    }
  }, [orderInput, onOrderLoaded, setIsLoading])

  // 关箱条码（支持多种格式）
  const CLOSE_BOX_CODES = ['CLOSEBOX', 'GB', '关箱', 'CLOSE']

  // 扫描 SKU
  const handleSkuSubmit = useCallback(async () => {
    if (!skuInput.trim() || !currentPickOrder) return

    setIsLoading(true)
    try {
      await onSkuScanned(skuInput.trim())
      setSkuInput('')
      setTimeout(() => skuInputRef.current?.focus(), 50)
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '扫描SKU失败'
      toast.error(errorMessage)
      setTimeout(() => skuInputRef.current?.select(), 50)
    } finally {
      setIsLoading(false)
    }
  }, [skuInput, currentPickOrder, onSkuScanned, setIsLoading])

  // 添加包材（支持关箱条码）
  const handleMaterialScan = async () => {
    if (!materialInput.trim()) return
    const code = materialInput.trim()
    const upperCode = code.toUpperCase()

    // 检查是否是关箱条码
    if (CLOSE_BOX_CODES.includes(upperCode) || CLOSE_BOX_CODES.includes(code)) {
      if (hasPendingClose) {
        setMaterialInput('')
        await onCloseBox()
        // 关箱成功后清除订单号输入框并聚焦
        setOrderInput('')
        setTimeout(() => orderInputRef.current?.focus(), 100)
        return
      } else {
        toast.error('当前没有待关箱的订单')
        setMaterialInput('')
        setTimeout(() => materialInputRef.current?.focus(), 50)
        return
      }
    }

    const material = materialOptions.find(m => m.materialCode === code)
    if (!material) {
      toast.error('包材不存在')
      return
    }
    if (!packagingMaterials.some(m => m.materialId === material.id)) {
      addPackagingMaterial({
        materialId: material.id,
        materialCode: material.materialCode,
        materialName: material.materialName,
        quantity: 1,
      })
    }
    setMaterialInput('')
    // 保持聚焦在耗材输入框
    setTimeout(() => materialInputRef.current?.focus(), 50)
  }

  // 关箱
  const handleCloseBox = async () => {
    await onCloseBox()
    // 关箱成功后清除订单号输入框并聚焦
    setOrderInput('')
    setTimeout(() => orderInputRef.current?.focus(), 100)
  }

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">打包操作</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* 单号输入 */}
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <Label>单号</Label>
            {cellCode && (
              <span className="text-xs text-blue-600 bg-blue-50 border border-blue-200 rounded px-1.5 py-0.5">
                格口 {cellCode}
              </span>
            )}
          </div>
          <div className="flex gap-2">
            <Input
              ref={orderInputRef}
              value={orderInput}
              onChange={(e) => setOrderInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !isOrderLocked && handleOrderSubmit()}
              placeholder="扫描或输入订单号"
              disabled={isLoading || !!isOrderLocked}
              autoFocus={!currentPickOrder}
            />
          </div>
        </div>

        {/* SKU输入 */}
        {currentPickOrder && !isComplete && (
          <div className="space-y-2">
            <Label>SKU</Label>
            <div className="flex gap-2">
              <Input
                ref={skuInputRef}
                value={skuInput}
                onChange={(e) => setSkuInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSkuSubmit()}
                placeholder="扫描或输入SKU条码"
                disabled={isLoading}
              />
            </div>
          </div>
        )}

        {/* 耗材输入 */}
        {currentPickOrder && !isComplete && (
          <div className="space-y-2">
            <Label>耗材 {hasPendingClose && <span className="text-xs text-orange-600">(扫描 GB 关箱)</span>}</Label>
            <div className="flex gap-2">
              <Input
                ref={materialInputRef}
                value={materialInput}
                onChange={(e) => setMaterialInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleMaterialScan()}
                placeholder={hasPendingClose ? "扫描 GB/CLOSE 关箱" : "扫描或输入包材编码"}
                className="flex-1"
              />
              <Select value={selectedMaterialId} onValueChange={(value) => {
                const material = materialOptions.find(m => m.id === value)
                if (material && !packagingMaterials.some(m => m.materialId === value)) {
                  addPackagingMaterial({
                    materialId: material.id,
                    materialCode: material.materialCode,
                    materialName: material.materialName,
                    quantity: 1,
                  })
                }
                setSelectedMaterialId('')
                // 保持聚焦在耗材输入框
                setTimeout(() => materialInputRef.current?.focus(), 50)
              }}>
                <SelectTrigger className="w-10 px-2">
                  <ChevronDown className="h-4 w-4" />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    <SelectLabel className="text-muted-foreground">选择包材</SelectLabel>
                    {materialOptions.map((material) => (
                      <SelectItem key={material.id} value={material.id}>
                        {material.materialCode} - {material.materialName}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            </div>
          </div>
        )}

        {/* 已选包材列表 */}
        {packagingMaterials.length > 0 && (
          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>包材</TableHead>
                  <TableHead className="w-20">数量</TableHead>
                  <TableHead className="w-10"></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {packagingMaterials.map((material) => (
                  <TableRow key={material.materialId}>
                    <TableCell className="text-xs">{material.materialCode}</TableCell>
                    <TableCell>
                      <Input
                        type="number"
                        min="1"
                        value={material.quantity}
                        onChange={(e) => updatePackagingMaterialQty(material.materialId, parseInt(e.target.value) || 1)}
                        className="w-16 h-8"
                      />
                    </TableCell>
                    <TableCell>
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8"
                        onClick={() => removePackagingMaterial(material.materialId)}
                      >
                        <Trash2 className="h-4 w-4 text-destructive" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* 关箱按钮 */}
        {currentPickOrder && !isComplete && hasPendingClose && (
          <div className="space-y-2">
            <div className="p-3 bg-orange-50 border border-orange-200 rounded-lg">
              <div className="flex items-center gap-2 text-orange-700 text-sm font-medium">
                <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
                订单 {moduleState?.pendingCloseOrder?.orderNumber} 已打包完成
              </div>
              <div className="mt-1 text-xs text-orange-600">
                请扫描包材后点击关箱按钮，或在耗材框中扫描 GB 关箱
              </div>
            </div>
            <Button
              className="w-full bg-orange-600 hover:bg-orange-700 text-white"
              onClick={handleCloseBox}
              disabled={isSubmitting || packagingMaterials.length === 0}
              size="lg"
            >
              {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              关箱
            </Button>
          </div>
        )}

        {/* 无待关箱订单时的关箱按钮（禁用状态） */}
        {currentPickOrder && !isComplete && !hasPendingClose && (
          <Button
            className="w-full"
            onClick={handleCloseBox}
            disabled={true}
          >
            关箱
          </Button>
        )}

        {/* 完成状态 - 显示完成信息和继续按钮 */}
        {isComplete && moduleState && (
          <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
            <div className="flex items-center gap-2 text-green-700 font-medium">
              <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
              关箱完成
            </div>
            <div className="mt-2 text-sm text-green-600">
              订单 {moduleState.orderNumber} 已完成打包
            </div>
            <Button
              className="w-full mt-3"
              onClick={() => {
                setOrderInput('')
                setTimeout(() => orderInputRef.current?.focus(), 50)
              }}
            >
              继续扫描下一个
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { Trash2, Loader2, ChevronDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
} from '@/components/ui/select'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { usePackingStore } from '@/stores/packing-store'

interface PackingMaterialPanelProps {
  onCloseBox: () => void
  isSubmitting: boolean
  pendingOrderNumber?: string
}

export function PackingMaterialPanel({
  onCloseBox,
  isSubmitting,
  pendingOrderNumber,
}: PackingMaterialPanelProps) {
  const [selectedMaterialId, setSelectedMaterialId] = useState<string>('')
  const [materialInput, setMaterialInput] = useState('')
  const materialInputRef = useRef<HTMLInputElement>(null)
  const hasFocusedOnPendingRef = useRef(false)

  const {
    currentPickOrder,
    packagingMaterials,
    materialOptions,
    shouldFocusMaterial,
    addPackagingMaterial,
    removePackagingMaterial,
    updatePackagingMaterialQty,
    clearFocusMaterial,
    loadMaterialOptions,
  } = usePackingStore()

  // 监听聚焦包材输入框的触发
  useEffect(() => {
    if (shouldFocusMaterial) {
      setTimeout(() => materialInputRef.current?.focus(), 100)
      clearFocusMaterial()
    }
  }, [shouldFocusMaterial, clearFocusMaterial])

  // 当有待关箱订单时，聚焦到包材输入框（只聚焦一次）
  useEffect(() => {
    if (pendingOrderNumber && !hasFocusedOnPendingRef.current) {
      hasFocusedOnPendingRef.current = true
      setTimeout(() => materialInputRef.current?.focus(), 100)
    }
    // 当 pendingOrderNumber 变为空时，重置标记
    if (!pendingOrderNumber) {
      hasFocusedOnPendingRef.current = false
    }
  }, [pendingOrderNumber])

  // 加载包材列表（使用 store 统一管理）
  useEffect(() => {
    if (currentPickOrder) {
      loadMaterialOptions()
    }
  }, [currentPickOrder, loadMaterialOptions])

  // 添加包材（通过选择）
  const handleAddMaterial = () => {
    if (!selectedMaterialId) return

    const material = materialOptions.find(m => m.id === selectedMaterialId)
    if (!material) return

    // 检查是否已添加
    if (packagingMaterials.some(m => m.materialId === selectedMaterialId)) {
      return
    }

    addPackagingMaterial({
      materialId: material.id,
      materialCode: material.materialCode,
      materialName: material.materialName,
      quantity: 1,
    })
    setSelectedMaterialId('')
  }

  // 添加包材（通过扫描输入）
  const handleMaterialScan = () => {
    if (!materialInput.trim()) return

    const code = materialInput.trim()
    const material = materialOptions.find(m => m.materialCode === code)
    if (!material) return

    // 检查是否已添加
    if (packagingMaterials.some(m => m.materialId === material.id)) {
      setMaterialInput('')
      return
    }

    addPackagingMaterial({
      materialId: material.id,
      materialCode: material.materialCode,
      materialName: material.materialName,
      quantity: 1,
    })
    setMaterialInput('')
  }

  if (!currentPickOrder) {
    return null
  }

  return (
    <div className="space-y-4 pt-4">
      {/* 包材选择 */}
      <div className="space-y-2">
        <Label>包材</Label>
        <div className="flex gap-2">
          <Input
            ref={materialInputRef}
            value={materialInput}
            onChange={(e) => setMaterialInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleMaterialScan()}
            placeholder="扫描或输入包材编码"
            className="flex-1"
          />
          <Select value={selectedMaterialId} onValueChange={(value) => {
            setSelectedMaterialId(value)
            // 选择后直接添加
            const material = materialOptions.find(m => m.id === value)
            if (material && !packagingMaterials.some(m => m.materialId === value)) {
              addPackagingMaterial({
                materialId: material.id,
                materialCode: material.materialCode,
                materialName: material.materialName,
                quantity: 1,
              })
            }
            setSelectedMaterialId('')
          }}>
            <SelectTrigger className="w-10 px-2">
              <ChevronDown className="h-4 w-4" />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                <SelectLabel className="text-muted-foreground">请选择包材</SelectLabel>
                {materialOptions.map((material) => (
                  <SelectItem key={material.id} value={material.id}>
                    {material.materialCode} - {material.materialName}
                  </SelectItem>
                ))}
              </SelectGroup>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* 已选包材列表 */}
      {packagingMaterials.length > 0 && (
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>包材编码</TableHead>
                <TableHead>包材名称</TableHead>
                <TableHead className="w-32">数量</TableHead>
                <TableHead className="w-16"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {packagingMaterials.map((material) => (
                <TableRow key={material.materialId}>
                  <TableCell className="font-mono">{material.materialCode}</TableCell>
                  <TableCell>{material.materialName}</TableCell>
                  <TableCell>
                    <Input
                      type="number"
                      min="1"
                      value={material.quantity}
                      onChange={(e) =>
                        updatePackagingMaterialQty(material.materialId, parseInt(e.target.value) || 1)
                      }
                      className="w-20"
                    />
                  </TableCell>
                  <TableCell>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      onClick={() => removePackagingMaterial(material.materialId)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      {/* 关箱按钮 */}
      {pendingOrderNumber && (
        <div className="space-y-2">
          <p className="text-sm text-orange-600 font-medium">请关箱</p>
          <Button
            className="w-full"
            onClick={onCloseBox}
            disabled={isSubmitting}
          >
            {isSubmitting ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : null}
            确认关箱
          </Button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { OrderPackingScanPanel } from '@/components/packing/order-packing-scan-panel'
import { PickOrderPackingScanPanel } from '@/components/packing/pick-order-packing-scan-panel'
import { ShipmentLabelPrint, type LabelData } from '@/components/packing/shipment-label-print'
import { SerialScanDialog } from '@/components/receiving/serial-scan-dialog'
import { SerialNumberScanDialog } from '@/components/packing/serial-number-scan-dialog'
import { Breadcrumb } from '@/components/ui/breadcrumb'
import {
  usePackingStore,
  type PickOrderInfo,
  type PickOrderLineInfo,
  type OrderSummary,
} from '@/stores/packing-store'
import {
  type ScanType,
  type PackingModuleContext,
  createPickOrderModule,
  createOrderModule,
  type PickOrderModuleState,
  type OrderModuleState,
} from '@/components/packing/modules'

// 联合模块状态类型
type ModuleState = PickOrderModuleState | OrderModuleState | null

export function PackingPage() {
  const t = useTranslations('packing')
  const tMenuGroup = useTranslations('menuGroup')

  // 模块相关状态
  const [scanType, setScanType] = useState<ScanType | null>(null)
  const [moduleState, setModuleState] = useState<ModuleState>(null)
  const [isSubmitting, setIsSubmittingLocal] = useState(false)
  const [labelData, setLabelData] = useState<LabelData | null>(null)
  const [cellCode, setCellCode] = useState<string | null>(null)

  const {
    currentPickOrder,
    currentItem,
    quantity,
    serialNumbers,
    showSerialDialog,
    packagingMaterials,
    orderSummary,
    setPickOrder,
    setIsSubmitting,
    setShowSerialDialog,
    setSerialNumbers,
    clearPickOrder,
    updateLinePackedQty,
    updatePickOrderTotals,
    clearPackagingMaterials,
    triggerFocusSku,
    triggerFocusMaterial,
    triggerFocusTaskNumber,
  } = usePackingStore()

  // 创建模块实例
  const pickOrderModule = createPickOrderModule()
  const orderModule = createOrderModule()

  // 页面加载时清空数据
  useEffect(() => {
    clearPickOrder()
    setScanType(null)
    setModuleState(null)
    setCellCode(null)
  }, [clearPickOrder])

  // 构建模块上下文
  const buildModuleContext = useCallback((): PackingModuleContext | null => {
    if (!currentPickOrder) return null
    return {
      pickOrderId: currentPickOrder.id,
      taskNumber: currentPickOrder.taskNumber,
      warehouseId: currentPickOrder.warehouseId,
      warehouseName: currentPickOrder.warehouseName,
      orderBusinessType: currentPickOrder.orderBusinessType,
      packagingMaterials,
      isLoading: false,
      isSubmitting: isSubmitting,
      setIsLoading: () => {},
      setIsSubmitting,
      triggerFocusSku,
      triggerFocusMaterial,
      clearPackagingMaterials,
    }
  }, [currentPickOrder, packagingMaterials, isSubmitting, setIsSubmitting, triggerFocusSku, triggerFocusMaterial, clearPackagingMaterials])

  // 加载拣货单/订单
  const handlePickOrderLoaded = useCallback(async (taskNumber: string) => {
    const params = new URLSearchParams({ taskNumber })
    if (currentPickOrder?.warehouseId) {
      params.set('warehouseId', currentPickOrder.warehouseId)
    }
    const response = await fetch(`/api/v1/packing/lookup?${params}`)
    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || t('messages.pickOrderNotFound'))
    }
    const data = await response.json()
    const { scanType: apiScanType, cellCode: apiCellCode, pickOrder, orderInfo, lines, summary, pendingCloseOrder } = data.data

    // 设置扫描类型
    setScanType(apiScanType as ScanType)
    setCellCode(apiCellCode || null)

    // 根据扫描类型初始化对应模块
    if (apiScanType === 'ORDER' && orderInfo) {
      // 订单模式
      const pickOrderBasic: PickOrderInfo = {
        id: pickOrder.id,
        taskNumber: pickOrder.taskNumber,
        status: pickOrder.status,
        orderBusinessType: pickOrder.orderBusinessType,
        totalLines: 0,
        totalQty: 0,
        totalOrders: 1,
        pickedQty: 0,
        packedQty: 0,
        warehouseId: pickOrder.warehouseId,
        warehouseName: pickOrder.warehouseName,
      }
      setPickOrder(pickOrderBasic, [], null)

      // 初始化订单模块状态
      const initialState = orderModule.getInitialState({
        orderId: orderInfo.orderId,
        orderNumber: orderInfo.orderNumber,
        totalExpected: orderInfo.totalExpected,
        totalPacked: orderInfo.totalPacked,
        isComplete: orderInfo.isComplete,
        lines: orderInfo.lines,
      })
      // 如果有待关箱订单，设置到状态中
      if (pendingCloseOrder) {
        initialState.pendingCloseOrder = pendingCloseOrder
      }
      setModuleState(initialState)

      // 自动开始打包
      if (pickOrder.status !== 'PACKING') {
        await fetch(`/api/v1/packing/${pickOrder.id}/start`, { method: 'POST' })
      }

      if (pendingCloseOrder) {
        toast.info(`订单 ${pendingCloseOrder.orderNumber} 已打包完成，请关箱`)
        triggerFocusMaterial()
      } else {
        triggerFocusSku()
      }
    } else {
      // 拣货单模式
      const pickOrderInfo: PickOrderInfo = {
        id: pickOrder.id,
        taskNumber: pickOrder.taskNumber,
        status: pickOrder.status,
        orderBusinessType: pickOrder.orderBusinessType,
        totalLines: pickOrder.totalLines,
        totalQty: pickOrder.totalQty,
        totalOrders: pickOrder.totalOrders,
        pickedQty: pickOrder.pickedQty,
        packedQty: pickOrder.packedQty,
        warehouseId: pickOrder.warehouseId,
        warehouseName: pickOrder.warehouseName,
      }

      const lineInfos: PickOrderLineInfo[] = lines.map((line: Record<string, unknown>) => ({
        id: line.id as string,
        lineNumber: line.lineNumber as number,
        skuId: line.skuId as string,
        skuCode: line.skuCode as string,
        skuName: line.skuName as string | null,
        barcode: line.barcode as string | null,
        expectedQty: line.expectedQty as number,
        pickedQty: line.pickedQty as number,
        packedQty: line.packedQty as number,
        status: line.status as string,
        orderId: line.orderId as string,
        orderNumber: line.orderNumber as string,
        orderType: line.orderType as string,
        channel: line.channel as string | null,
        batchNumber: line.batchNumber as string | null,
        expiryDate: line.expiryDate as string | null,
        isSerialManaged: line.isSerialManaged as boolean,
        isBatchManaged: line.isBatchManaged as boolean,
        isExpiryManaged: line.isExpiryManaged as boolean,
      }))

      const summaryInfo: OrderSummary = {
        orderType: summary.orderType,
        channel: summary.channel,
        skuCode: summary.skuCode,
        totalQty: summary.totalQty,
        unpackedQty: summary.unpackedQty,
      }

      setPickOrder(pickOrderInfo, lineInfos, summaryInfo)

      // 初始化拣货单模块状态
      const initialState = pickOrderModule.getInitialState()
      if (pendingCloseOrder) {
        initialState.pendingCloseOrder = pendingCloseOrder
        toast.info(`订单 ${pendingCloseOrder.orderNumber} 已打包完成，请关箱`)
      }
      setModuleState(initialState)

      // 自动开始打包
      if (pickOrder.status !== 'PACKING') {
        await fetch(`/api/v1/packing/${pickOrder.id}/start`, { method: 'POST' })
      }

      if (!pendingCloseOrder) {
        triggerFocusSku()
      } else {
        triggerFocusMaterial()
      }
    }
  }, [t, setPickOrder, triggerFocusSku, pickOrderModule, orderModule, currentPickOrder, setScanType, setCellCode, triggerFocusMaterial])

  // 扫描 SKU - 委托给对应模块处理
  const handleSkuScanned = useCallback(async (barcode: string, serialNumbers: string[] = []) => {
    if (!currentPickOrder || !scanType || !moduleState) return

    const context = buildModuleContext()
    if (!context) return

    let result
    if (scanType === 'ORDER') {
      const handlers = orderModule.createHandlers()
      result = await handlers.onSkuScanned(
        barcode,
        context,
        moduleState as OrderModuleState,
        (state) => setModuleState(state),
        serialNumbers
      )
    } else {
      const handlers = pickOrderModule.createHandlers(updateLinePackedQty, updatePickOrderTotals)
      result = await handlers.onSkuScanned(
        barcode,
        context,
        moduleState as PickOrderModuleState,
        (state) => setModuleState(state),
        serialNumbers
      )
    }

    // 检查是否需要序列号
    if (!result.success && result.requireSerialNumbers) {
      // 打开序列号扫描对话框
      setModuleState({
        ...moduleState,
        serialNumberDialog: {
          open: true,
          skuCode: barcode,
          skuName: null, // 可以从API返回中获取
          barcode,
          requiredQuantity: result.requiredQuantity || 1,
        },
      } as ModuleState)
      return
    }

    if (!result.success) {
      throw new Error(result.message)
    }

    if (result.message) {
      toast.success(result.message)
    }

    if (result.isOrderComplete) {
      toast.info(`订单 ${result.orderNumber} 已打包完成，请关箱`)
    }
  }, [currentPickOrder, scanType, moduleState, buildModuleContext, orderModule, pickOrderModule, updateLinePackedQty, updatePickOrderTotals])

  // 关箱 - 委托给对应模块处理
  const handleCloseBox = useCallback(async () => {
    if (!currentPickOrder || !scanType || !moduleState) return

    const context = buildModuleContext()
    if (!context) return

    setIsSubmittingLocal(true)
    setIsSubmitting(true)

    try {
      let result
      if (scanType === 'ORDER') {
        const handlers = orderModule.createHandlers()
        result = await handlers.onCloseBox(
          context,
          moduleState as OrderModuleState,
          (state) => setModuleState(state)
        )
      } else {
        const handlers = pickOrderModule.createHandlers(updateLinePackedQty, updatePickOrderTotals)
        result = await handlers.onCloseBox(
          context,
          moduleState as PickOrderModuleState,
          (state) => setModuleState(state)
        )
      }

      if (!result.success) {
        toast.error(result.message)
        return
      }

      // 设置标签数据
      if (result.labelData) {
        console.log('Setting labelData for print:', result.labelData)
        setLabelData(result.labelData as LabelData)
      } else {
        console.log('No labelData in result:', result)
      }

      // 拣货单全部完成，清除状态回到初始页面
      if (result.shouldClearPickOrder) {
        clearPickOrder()
        setScanType(null)
        setModuleState(null)
        setCellCode(null)
        triggerFocusTaskNumber()
        return
      }

      // 拣货单模式需要重新加载
      if (result.shouldReload) {
        await handlePickOrderLoaded(currentPickOrder.taskNumber)
      } else if (result.completedOrder) {
        // 订单模式完成后保留订单信息显示，等待扫描下一单
        // 不调用 clearPickOrder()，保持右侧订单明细可见
        setModuleState({
          ...(moduleState as OrderModuleState),
          isComplete: true,
          pendingCloseOrder: null,
        })
      }
    } finally {
      setIsSubmittingLocal(false)
      setIsSubmitting(false)
    }
  }, [currentPickOrder, scanType, moduleState, buildModuleContext, orderModule, pickOrderModule, updateLinePackedQty, updatePickOrderTotals, setIsSubmitting, handlePickOrderLoaded])

  // 序列号扫描完成
  const handleSerialScanConfirm = useCallback((scannedSerials: string[]) => {
    setSerialNumbers(scannedSerials)
    setShowSerialDialog(false)
  }, [setSerialNumbers, setShowSerialDialog])

  // 渲染模块内容区域
  const renderModuleContent = () => {
    if (!currentPickOrder || !scanType || !moduleState) return null

    if (scanType === 'ORDER') {
      return orderModule.renderContent({
        context: buildModuleContext()!,
        moduleState: moduleState as OrderModuleState,
        setModuleState: (state: OrderModuleState) => setModuleState(state),
      })
    }

    return pickOrderModule.renderContent({
      context: buildModuleContext()!,
      moduleState: moduleState as PickOrderModuleState,
      setModuleState: (state: PickOrderModuleState) => setModuleState(state),
    })
  }

  return (
    <div className="space-y-4">
      <Breadcrumb
        items={[
          { label: tMenuGroup('outbound'), href: '/orders' },
          { label: t('title') },
        ]}
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* 左侧扫描区 - 根据模式显示不同面板 */}
        <div className="lg:col-span-1 space-y-4">
          {scanType === 'ORDER' ? (
            <OrderPackingScanPanel
              onOrderLoaded={handlePickOrderLoaded}
              onSkuScanned={handleSkuScanned}
              onCloseBox={handleCloseBox}
              moduleState={moduleState as OrderModuleState | null}
              isSubmitting={isSubmitting}
              initialOrderNumber={(moduleState as OrderModuleState | null)?.orderNumber}
              cellCode={cellCode}
            />
          ) : (
            <PickOrderPackingScanPanel
              onPickOrderLoaded={handlePickOrderLoaded}
              onSkuScanned={handleSkuScanned}
              onCloseBox={handleCloseBox}
              moduleState={moduleState as PickOrderModuleState | null}
              isSubmitting={isSubmitting}
            />
          )}
        </div>

        {/* 右侧详情区 */}
        {renderModuleContent()}
      </div>

      {/* 序列号扫描弹窗 - 打包专用 */}
      {moduleState && 'serialNumberDialog' in moduleState && moduleState.serialNumberDialog?.open && (
        <SerialNumberScanDialog
          open={moduleState.serialNumberDialog.open}
          onOpenChange={(open) => {
            if (!open) {
              // 对话框关闭时，清除状态并聚焦到 SKU 输入框
              // 使用函数式更新，确保基于最新状态修改
              setModuleState((prevState) => ({
                ...prevState,
                serialNumberDialog: null,
              } as ModuleState))
              // 聚焦到 SKU 输入框，让用户可以重新扫描
              triggerFocusSku()
            }
          }}
          skuCode={moduleState.serialNumberDialog.skuCode}
          skuName={moduleState.serialNumberDialog.skuName}
          requiredQuantity={moduleState.serialNumberDialog.requiredQuantity}
          onConfirm={async (serialNumbers) => {
            const barcode = moduleState.serialNumberDialog!.barcode
            const requiredQuantity = moduleState.serialNumberDialog!.requiredQuantity

            // 重新调用扫描，这次带上序列号
            try {
              await handleSkuScanned(barcode, serialNumbers)
              // 扫描成功后，关闭对话框，聚焦逻辑已在模块内部处理
              // 使用函数式更新，确保基于最新状态修改，避免覆盖 pendingCloseOrder
              setModuleState((prevState) => ({
                ...prevState,
                serialNumberDialog: null,
              } as ModuleState))
            } catch (error) {
              // 显示错误消息
              const errorMessage = error instanceof Error ? error.message : '序列号扫描失败'
              toast.error(errorMessage)

              // 保持对话框打开，让用户可以重新扫描
              // 不关闭对话框，用户可以修改序列号后重试
              console.error('序列号扫描失败:', error)
            }
          }}
        />
      )}

      {/* 序列号扫描弹窗 - 收货复用 */}
      {currentItem && currentItem.sku.isSerialManaged && (
        <SerialScanDialog
          open={showSerialDialog}
          skuCode={currentItem.sku.skuCode}
          skuName={currentItem.sku.skuName || ''}
          requiredCount={quantity}
          initialSerialNumbers={serialNumbers}
          onConfirm={handleSerialScanConfirm}
          onCancel={() => setShowSerialDialog(false)}
        />
      )}

      {/* 发货标签打印 */}
      <ShipmentLabelPrint
        labelData={labelData}
        onPrintComplete={() => setLabelData(null)}
      />
    </div>
  )
}

'use client'

import { useState, useRef, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { X } from 'lucide-react'

interface SerialNumberScanDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  skuCode: string
  skuName: string | null
  requiredQuantity: number
  onConfirm: (serialNumbers: string[]) => void | Promise<void>
}

export function SerialNumberScanDialog({
  open,
  onOpenChange,
  skuCode,
  skuName,
  requiredQuantity,
  onConfirm,
}: SerialNumberScanDialogProps) {
  const [serialNumbers, setSerialNumbers] = useState<string[]>([])
  const [currentInput, setCurrentInput] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  // 重置状态
  useEffect(() => {
    if (open) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSerialNumbers([])
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setCurrentInput('')
      // 延迟聚焦，确保对话框已完全打开
      setTimeout(() => {
        inputRef.current?.focus()
      }, 100)
    }
  }, [open])

  // 添加序列号
  const handleAddSerialNumber = () => {
    const trimmed = currentInput.trim()
    if (!trimmed) return

    // 检查是否重复
    if (serialNumbers.includes(trimmed)) {
      alert('该序列号已扫描')
      setCurrentInput('')
      return
    }

    // 检查是否超过需要数量
    if (serialNumbers.length >= requiredQuantity) {
      alert(`只需要扫描 ${requiredQuantity} 个序列号`)
      return
    }

    setSerialNumbers([...serialNumbers, trimmed])
    setCurrentInput('')

    // 如果已收集足够数量，自动提交
    if (serialNumbers.length + 1 === requiredQuantity) {
      setTimeout(async () => {
        await onConfirm([...serialNumbers, trimmed])
        // 不在这里关闭对话框，由父组件根据验证结果决定是否关闭
      }, 300)
    }
  }

  // 移除序列号
  const handleRemoveSerialNumber = (index: number) => {
    setSerialNumbers(serialNumbers.filter((_, i) => i !== index))
  }

  // 处理键盘事件
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      handleAddSerialNumber()
    }
  }

  // 手动确认
  const handleConfirm = async () => {
    if (serialNumbers.length !== requiredQuantity) {
      alert(`需要扫描 ${requiredQuantity} 个序列号，当前已扫描 ${serialNumbers.length} 个`)
      return
    }
    await onConfirm(serialNumbers)
    // 不在这里关闭对话框，由父组件根据结果决定是否关闭
  }

  // 清空所有序列号
  const handleClearAll = () => {
    setSerialNumbers([])
    setCurrentInput('')
    setTimeout(() => inputRef.current?.focus(), 50)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>扫描序列号</DialogTitle>
          <DialogDescription asChild>
            <div>
              {skuName && <div className="font-medium text-foreground">{skuName}</div>}
              <div className="text-sm">SKU: {skuCode}</div>
              <div className="text-sm mt-1">
                需要扫描 <span className="font-bold text-primary">{requiredQuantity}</span> 个序列号
              </div>
            </div>
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* 输入框 */}
          <div className="flex gap-2">
            <Input
              ref={inputRef}
              value={currentInput}
              onChange={(e) => setCurrentInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="扫描或输入序列号"
              className="flex-1"
            />
            <Button onClick={handleAddSerialNumber} type="button">
              添加
            </Button>
          </div>

          {/* 已扫描的序列号列表 */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <div className="text-sm font-medium">
                已扫描: {serialNumbers.length} / {requiredQuantity}
              </div>
              {serialNumbers.length > 0 && (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={handleClearAll}
                  className="h-7 text-xs"
                >
                  清空全部
                </Button>
              )}
            </div>
            <div className="flex flex-wrap gap-2 min-h-[60px] p-3 border rounded-md bg-muted/30">
              {serialNumbers.length === 0 ? (
                <div className="text-sm text-muted-foreground">暂无序列号</div>
              ) : (
                serialNumbers.map((sn, index) => (
                  <Badge key={index} variant="secondary" className="gap-1 pr-1">
                    {sn}
                    <button
                      onClick={() => handleRemoveSerialNumber(index)}
                      className="ml-1 hover:bg-destructive/20 rounded-sm p-0.5"
                      type="button"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </Badge>
                ))
              )}
            </div>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} type="button">
            取消
          </Button>
          <Button
            onClick={handleConfirm}
            disabled={serialNumbers.length !== requiredQuantity}
            type="button"
          >
            确认 ({serialNumbers.length}/{requiredQuantity})
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

