'use client'

import { useState, useMemo } from 'react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { PendingLine } from './pending-lines-table'
import { PendingContainer } from './pending-containers-table'

interface CreatePutawayOrderDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  selectedLines: PendingLine[]
  selectedContainerItems: PendingContainer[]
  onSuccess: () => void
}

export function CreatePutawayOrderDialog({
  open,
  onOpenChange,
  selectedLines,
  selectedContainerItems,
  onSuccess,
}: CreatePutawayOrderDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false)

  const isLineMode = selectedLines.length > 0
  const isContainerMode = selectedContainerItems.length > 0

  // 容器模式下的汇总计算
  const containerSummary = useMemo(() => {
    if (!isContainerMode) return null

    const containerIds = new Set(selectedContainerItems.map((c) => c.containerId))
    const skuCodes = new Set(selectedContainerItems.map((c) => c.skuCode))
    const totalQty = selectedContainerItems.reduce((sum, c) => sum + c.quantity, 0)
    const goodQty = selectedContainerItems
      .filter((c) => c.qualityType === 'GOOD')
      .reduce((sum, c) => sum + c.quantity, 0)
    const damagedQty = selectedContainerItems
      .filter((c) => c.qualityType !== 'GOOD')
      .reduce((sum, c) => sum + c.quantity, 0)

    return {
      containerCount: containerIds.size,
      skuCount: skuCodes.size,
      totalQty,
      goodQty,
      damagedQty,
    }
  }, [isContainerMode, selectedContainerItems])

  const handleSubmit = async () => {
    setIsSubmitting(true)
    try {
      const body: Record<string, unknown> = {
        putawayMode: 'TASK_MODE', // 固定使用任务模式
        separateByQuality: true, // 按质量类型分组
      }

      if (isLineMode) {
        body.asnLineIds = selectedLines.map((line) => line.id)
      } else if (isContainerMode) {
        // 获取唯一的容器ID
        const containerIds = [...new Set(selectedContainerItems.map((c) => c.containerId))]
        body.containerIds = containerIds
      }

      const response = await fetch('/api/v1/putaway/orders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })

      const result = await response.json()

      if (result.success) {
        toast.success(result.message || '上架单创建成功')
        onSuccess()
        onOpenChange(false)
      } else {
        toast.error(result.message || '创建失败')
      }
    } catch {
      toast.error('创建上架单失败')
    } finally {
      setIsSubmitting(false)
    }
  }

  // 计算汇总信息
  const totalQty = isLineMode
    ? selectedLines.reduce((sum, line) => sum + line.pendingQty, 0)
    : 0 // 容器模式下不显示总数量，因为数据结构已改变

  const totalGoodQty = isLineMode
    ? selectedLines.reduce((sum, line) => sum + (line.pendingGoodQty ?? line.pendingQty), 0)
    : 0

  const totalDamagedQty = isLineMode
    ? selectedLines.reduce((sum, line) => sum + (line.pendingDamagedQty ?? 0), 0)
    : 0

  const skuCount = isLineMode
    ? new Set(selectedLines.map((line) => line.skuCode)).size
    : 0 // 容器模式下不显示SKU数量

  // 计算将创建的上架单数量（按 ASN 分组，良品和不良品合并到同一上架单）
  const estimatedOrderCount = isLineMode
    ? (() => {
        const groups = new Set<string>()
        for (const line of selectedLines) {
          const hasPending =
            (line.pendingGoodQty ?? line.pendingQty) > 0 ||
            (line.pendingDamagedQty ?? 0) > 0
          if (hasPending) groups.add(line.asn.id)
        }
        return groups.size
      })()
    : containerSummary?.containerCount ?? 0

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[550px] max-h-[80vh] flex flex-col">
        <DialogHeader className="flex-shrink-0 pb-2">
          <DialogTitle>创建上架单</DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto space-y-2">
          {/* 汇总信息 - 紧凑单行显示 */}
          <div className="rounded-lg border p-2 text-xs">
            {isLineMode && !isContainerMode && (
              <div className="flex flex-wrap gap-x-4 gap-y-1">
                <span><span className="text-muted-foreground">行数:</span> <span className="font-medium">{selectedLines.length}</span></span>
                <span><span className="text-muted-foreground">SKU:</span> <span className="font-medium">{skuCount}种</span></span>
                <span><span className="text-muted-foreground">总数:</span> <span className="font-medium text-primary">{totalQty}</span></span>
                <span><span className="text-muted-foreground">良品:</span> <span className="font-medium text-green-600">{totalGoodQty}</span></span>
                <span><span className="text-muted-foreground">不良:</span> <span className="font-medium text-red-600">{totalDamagedQty}</span></span>
              </div>
            )}
            {isContainerMode && containerSummary && (
              <div className="flex flex-wrap gap-x-4 gap-y-1">
                <span><span className="text-muted-foreground">容器:</span> <span className="font-medium">{containerSummary.containerCount}个</span></span>
                <span><span className="text-muted-foreground">SKU:</span> <span className="font-medium">{containerSummary.skuCount}种</span></span>
                <span><span className="text-muted-foreground">总数:</span> <span className="font-medium text-primary">{containerSummary.totalQty}</span></span>
                <span><span className="text-muted-foreground">良品:</span> <span className="font-medium text-green-600">{containerSummary.goodQty}</span></span>
                <span><span className="text-muted-foreground">不良:</span> <span className="font-medium text-red-600">{containerSummary.damagedQty}</span></span>
              </div>
            )}
          </div>

          {/* 明细列表 - 更大空间 */}
          {isLineMode && !isContainerMode && selectedLines.length > 0 && (
            <div className="rounded-lg border p-2 space-y-1">
              <h4 className="font-medium text-xs text-muted-foreground">选中明细 ({selectedLines.length})</h4>
              <div className="max-h-[280px] overflow-y-auto space-y-0.5 text-xs">
                {selectedLines.map((line) => (
                  <div key={line.id} className="flex justify-between py-0.5 hover:bg-muted/50 px-1 rounded">
                    <span className="text-muted-foreground truncate mr-2">
                      {line.asn.asnNumber} - {line.skuCode}
                    </span>
                    <span className="font-medium whitespace-nowrap">
                      <span className="text-green-600">{line.pendingGoodQty ?? line.pendingQty}</span>
                      {(line.pendingDamagedQty ?? 0) > 0 && (
                        <span className="text-red-600 ml-1">+{line.pendingDamagedQty}</span>
                      )}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {isContainerMode && selectedContainerItems.length > 0 && (
            <div className="rounded-lg border p-2 space-y-1">
              <h4 className="font-medium text-xs text-muted-foreground">选中明细 ({selectedContainerItems.length})</h4>
              <div className="max-h-[280px] overflow-y-auto space-y-0.5 text-xs">
                {selectedContainerItems.map((item) => (
                  <div key={item.id} className="flex justify-between items-center py-0.5 hover:bg-muted/50 px-1 rounded">
                    <span className="text-muted-foreground truncate mr-2">
                      {item.containerCode} - {item.skuCode}
                    </span>
                    <span className="flex items-center gap-1">
                      <span className="font-medium">{item.quantity}</span>
                      {item.qualityType === 'GOOD' ? (
                        <Badge variant="default" className="text-[10px] px-1 py-0 h-4">良品</Badge>
                      ) : (
                        <Badge variant="destructive" className="text-[10px] px-1 py-0 h-4">破损</Badge>
                      )}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <DialogFooter className="flex-shrink-0 pt-2">
          <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>
            取消
          </Button>
          <Button size="sm" onClick={handleSubmit} disabled={isSubmitting}>
            {isSubmitting ? '创建中...' : '确认创建'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { Package, Box, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { PendingLinesFilter } from './pending-lines-filter'
import { PendingLinesTable, PendingLine } from './pending-lines-table'
import { PendingContainersFilter } from './pending-containers-filter'
import { PendingContainersTable, PendingContainer } from './pending-containers-table'
import { CreatePutawayOrderDialog } from './create-putaway-order-dialog'

export function CreatePutawayPage() {
  const t = useTranslations('putaway')
  const tCommon = useTranslations('common')
  const [activeTab, setActiveTab] = useState('sku')

  // SKU 收货 Tab 状态
  const [lines, setLines] = useState<PendingLine[]>([])
  const [linesLoading, setLinesLoading] = useState(false)
  const [lineFilters, setLineFilters] = useState({
    search: '',
    asnNumber: '',
    warehouseId: '',
  })
  const [linesPagination, setLinesPagination] = useState({
    page: 1,
    pageSize: 20,
    total: 0,
    totalPages: 0,
  })
  const [selectedLines, setSelectedLines] = useState<PendingLine[]>([])

  // 容器收货 Tab 状态
  const [containers, setContainers] = useState<PendingContainer[]>([])
  const [containersLoading, setContainersLoading] = useState(false)
  const [containerFilters, setContainerFilters] = useState({
    search: '',
    asnNumber: '',
    warehouseId: '',
  })
  const [containersPagination, setContainersPagination] = useState({
    page: 1,
    pageSize: 20,
    total: 0,
    totalPages: 0,
  })
  const [selectedContainerItems, setSelectedContainerItems] = useState<PendingContainer[]>([])

  // 创建上架单对话框
  const [dialogOpen, setDialogOpen] = useState(false)

  // 获取待上架 ASN Line
  const fetchLines = useCallback(async () => {
    setLinesLoading(true)
    try {
      const params = new URLSearchParams({
        page: linesPagination.page.toString(),
        pageSize: linesPagination.pageSize.toString(),
        receivingMethod: 'SKU',
      })
      if (lineFilters.search) params.set('search', lineFilters.search)
      if (lineFilters.asnNumber) params.set('asnNumber', lineFilters.asnNumber)
      if (lineFilters.warehouseId) params.set('warehouseId', lineFilters.warehouseId)

      const response = await fetch(`/api/v1/putaway/pending-lines?${params}`)
      const result = await response.json()

      if (result.success) {
        setLines(result.data)
        setLinesPagination((prev) => ({
          ...prev,
          total: result.pagination.total,
          totalPages: result.pagination.totalPages,
        }))
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(t('fetchPendingLinesFailed'))
    } finally {
      setLinesLoading(false)
    }
  }, [lineFilters, linesPagination.page, linesPagination.pageSize])

  // 获取待上架容器
  const fetchContainers = useCallback(async () => {
    setContainersLoading(true)
    try {
      const params = new URLSearchParams({
        page: containersPagination.page.toString(),
        pageSize: containersPagination.pageSize.toString(),
        receivingMethod: 'CONTAINER',
      })
      if (containerFilters.search) params.set('search', containerFilters.search)
      if (containerFilters.asnNumber) params.set('asnNumber', containerFilters.asnNumber)
      if (containerFilters.warehouseId) params.set('warehouseId', containerFilters.warehouseId)

      const response = await fetch(`/api/v1/putaway/pending-containers?${params}`)
      const result = await response.json()

      if (result.success) {
        setContainers(result.data)
        setContainersPagination((prev) => ({
          ...prev,
          total: result.pagination.total,
          totalPages: result.pagination.totalPages,
        }))
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(t('fetchPendingContainersFailed'))
    } finally {
      setContainersLoading(false)
    }
  }, [containerFilters, containersPagination.page, containersPagination.pageSize])

  // 初始加载和筛选变化时重新获取数据
  useEffect(() => {
    if (activeTab === 'sku') {
      fetchLines()
    }
  }, [activeTab, fetchLines])

  useEffect(() => {
    if (activeTab === 'container') {
      fetchContainers()
    }
  }, [activeTab, fetchContainers])

  // 处理筛选变化
  const handleLineFilterChange = (key: string, value: string) => {
    setLineFilters((prev) => ({ ...prev, [key]: value }))
    setLinesPagination((prev) => ({ ...prev, page: 1 }))
  }

  const handleContainerFilterChange = (key: string, value: string) => {
    setContainerFilters((prev) => ({ ...prev, [key]: value }))
    setContainersPagination((prev) => ({ ...prev, page: 1 }))
  }

  // 重置筛选
  const resetLineFilters = () => {
    setLineFilters({ search: '', asnNumber: '', warehouseId: '' })
    setLinesPagination((prev) => ({ ...prev, page: 1 }))
  }

  const resetContainerFilters = () => {
    setContainerFilters({ search: '', asnNumber: '', warehouseId: '' })
    setContainersPagination((prev) => ({ ...prev, page: 1 }))
  }

  // 创建上架单
  const handleCreateOrder = () => {
    if (activeTab === 'sku' && selectedLines.length === 0) {
      toast.error(t('selectAtLeastOneLine'))
      return
    }
    if (activeTab === 'container' && selectedContainerItems.length === 0) {
      toast.error(t('selectAtLeastOneContainer'))
      return
    }
    setDialogOpen(true)
  }

  // 创建成功后刷新数据
  const handleCreateSuccess = useCallback(() => {
    setSelectedLines([])
    setSelectedContainerItems([])
    if (activeTab === 'sku') {
      fetchLines()
    } else if (activeTab === 'container') {
      fetchContainers()
    }
  }, [activeTab, fetchLines, fetchContainers])

  return (
    <div className="flex flex-col h-full gap-2">
      <Tabs value={activeTab} onValueChange={setActiveTab} className="flex flex-col flex-1 min-h-0">
        <TabsList className="w-full justify-start">
          <TabsTrigger value="sku" className="flex items-center gap-2">
            <Package className="h-4 w-4" />
            {t('skuReceiving')}
            {selectedLines.length > 0 && (
              <span className="ml-1 px-1.5 py-0.5 text-xs bg-primary text-primary-foreground rounded-full">
                {selectedLines.length}
              </span>
            )}
          </TabsTrigger>
            <TabsTrigger value="container" className="flex items-center gap-2">
            <Box className="h-4 w-4" />
            {t('containerReceiving')}
            {selectedContainerItems.length > 0 && (
              <span className="ml-1 px-1.5 py-0.5 text-xs bg-primary text-primary-foreground rounded-full">
                {selectedContainerItems.length}
              </span>
            )}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="sku" className="flex flex-col flex-1 min-h-0 gap-2 mt-2">
          <PendingLinesFilter
            key={`sku-${lineFilters.search}-${lineFilters.asnNumber}-${lineFilters.warehouseId}`}
            filters={lineFilters}
            onFilterChange={handleLineFilterChange}
            onReset={resetLineFilters}
          />
          <div className="flex items-center gap-4 rounded-lg bg-muted p-3 flex-shrink-0">
            <span className="text-sm text-muted-foreground">
              {tCommon('selectedCount', { count: selectedLines.length })}
            </span>
            <Button size="sm" onClick={handleCreateOrder} disabled={selectedLines.length === 0}>
              <Package className="h-3.5 w-3.5 mr-1" />
              {t('createPutawayOrder')}
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => setSelectedLines([])}
              disabled={selectedLines.length === 0}
            >
              <X className="h-3.5 w-3.5 mr-1" />
              {tCommon('cancel')}
            </Button>
          </div>
          <div className="flex-1 min-h-0">
            <PendingLinesTable
              lines={lines}
              selectedLines={selectedLines}
              onSelectionChange={setSelectedLines}
              isLoading={linesLoading}
            />
          </div>
        </TabsContent>

        <TabsContent value="container" className="flex flex-col flex-1 min-h-0 gap-2 mt-2">
          <PendingContainersFilter
            key={`container-${containerFilters.search}-${containerFilters.asnNumber}-${containerFilters.warehouseId}`}
            filters={containerFilters}
            onFilterChange={handleContainerFilterChange}
            onReset={resetContainerFilters}
          />
          <div className="flex items-center gap-4 rounded-lg bg-muted p-3 flex-shrink-0">
            <span className="text-sm text-muted-foreground">
              {tCommon('selectedCount', { count: selectedContainerItems.length })}
            </span>
            <Button size="sm" onClick={handleCreateOrder} disabled={selectedContainerItems.length === 0}>
              <Package className="h-3.5 w-3.5 mr-1" />
              {t('createPutawayOrder')}
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => setSelectedContainerItems([])}
              disabled={selectedContainerItems.length === 0}
            >
              <X className="h-3.5 w-3.5 mr-1" />
              {tCommon('cancel')}
            </Button>
          </div>
          <div className="flex-1 min-h-0">
            <PendingContainersTable
              containers={containers}
              selectedContainers={selectedContainerItems}
              onSelectionChange={setSelectedContainerItems}
              isLoading={containersLoading}
            />
          </div>
        </TabsContent>
      </Tabs>

      <CreatePutawayOrderDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        selectedLines={selectedLines}
        selectedContainerItems={selectedContainerItems}
        onSuccess={handleCreateSuccess}
      />
    </div>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { ContainerScanPanel } from '@/components/receiving/container-scan-panel'
import { AsnHeaderCard, AsnLinesTable } from '@/components/receiving'
import { FirstReceivingDialog } from '@/components/sku/first-receiving-dialog'
import { SerialScanDialog } from '@/components/receiving/serial-scan-dialog'
import { Breadcrumb } from '@/components/ui/breadcrumb'
import {
  useReceivingStore,
  type AsnInfo,
  type AsnLineInfo,
  type SkuInfo,
  type ContainerInfo,
} from '@/stores/receiving-store'

export function ContainerReceivingPage() {
  const t = useTranslations('receiving')
  const tMenuGroup = useTranslations('menuGroup')
  const searchParams = useSearchParams()
  const initialAsnNumber = searchParams.get('asn')
  const [showSerialScanDialog, setShowSerialScanDialog] = useState(false)
  const {
    currentAsn,
    asnLines,
    currentItem,
    quantity,
    qualityStatus,
    batchNumber,
    expiryDate,
    serialNumbers,
    showFirstReceivingDialog,
    currentContainer,
    setAsn,
    setCurrentItem,
    setIsSubmitting,
    setShowFirstReceivingDialog,
    setReceivingBusinessMode,
    setCurrentContainer,
    setContainerItems,
    setBatchNumber,
    setExpiryDate,
    setSerialNumbers,
    clearAsn,
    resetCurrentItem,
    updateAsnLine,
    updateAsnTotals,
    updateAsnStatus,
  } = useReceivingStore()

  // 设置收货模式为容器
  useEffect(() => {
    setReceivingBusinessMode('container')
  }, [setReceivingBusinessMode])

  // 加载 ASN
  const handleAsnLoaded = useCallback(async (asnNumber: string) => {
    const response = await fetch(`/api/v1/asn/lookup?asnNumber=${encodeURIComponent(asnNumber)}&receivingMode=CONTAINER`)
    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || t('asn.notFound'))
    }
    const data = await response.json()
    const asn = data.data

    const asnInfo: AsnInfo = {
      id: asn.id,
      asnNumber: asn.asnNumber,
      externalNumber: asn.externalNumber,
      status: asn.status,
      clientName: asn.client?.clientName || null,
      warehouseName: asn.warehouse?.warehouseName || null,
      warehouseId: asn.warehouseId,
      createdAt: asn.createdAt,
      totalExpectedQty: asn.totalExpectedQty,
      totalReceivedQty: asn.totalReceivedQty,
      totalExpectedLines: asn.totalExpectedLines,
      totalReceivedLines: asn.totalReceivedLines,
    }

    const lines: AsnLineInfo[] = asn.asnLines?.map((line: Record<string, unknown>) => ({
      id: line.id as string,
      lineNumber: line.lineNumber as number,
      skuId: line.skuId as string,
      skuCode: line.skuCode as string,
      skuName: line.skuName as string,
      barcode: (line.sku as Record<string, unknown>)?.barcode as string | null,
      expectedQty: line.expectedQty as number,
      receivedQty: line.receivedQty as number,
      receivedGoodQty: line.receivedGoodQty as number,
      receivedDamagedQty: line.receivedDamagedQty as number,
      status: line.status as string,
      batchNumber: line.batchNumber as string | null,
      expiryDate: line.expiryDate as string | null,
    })) || []

    setAsn(asnInfo, lines)
  }, [t, setAsn])

  // 刷新容器内物品
  const refreshContainerItems = useCallback(async (containerId: string) => {
    try {
      const response = await fetch(`/api/v1/containers/${containerId}/items`)
      if (response.ok) {
        const data = await response.json()
        setContainerItems(data.data?.items || [], data.data?.summary || null)
      }
    } catch {
      // 忽略错误
    }
  }, [setContainerItems])

  // 扫描容器
  const handleContainerScanned = useCallback(async (containerCode: string) => {
    if (!currentAsn) return

    const response = await fetch(
      `/api/v1/containers/lookup?containerCode=${encodeURIComponent(containerCode)}&warehouseId=${currentAsn.warehouseId}`
    )

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || t('container.notFound'))
    }

    const data = await response.json()
    const container = data.data

    // 校验容器
    if (container.warehouseId !== currentAsn.warehouseId) {
      throw new Error(t('container.wrongWarehouse'))
    }
    if (container.purpose !== 'INBOUND') {
      throw new Error(t('container.wrongPurpose'))
    }
    // 校验容器是否已关箱
    if (container.status === 'CLOSED' || container.closedAt) {
      throw new Error(t('container.alreadyClosed'))
    }
    if (container.status !== 'IDLE' && container.status !== 'OCCUPIED') {
      throw new Error(t('container.wrongStatus'))
    }
    if (!container.isEnabled) {
      throw new Error(t('container.disabled'))
    }
    // 校验容器是否已被其他ASN占用
    if (container.currentAsnId && container.currentAsnId !== currentAsn.id) {
      // 检查容器是否真的有物品
      const itemsResponse = await fetch(`/api/v1/containers/${container.id}/items`)
      if (itemsResponse.ok) {
        const itemsData = await itemsResponse.json()
        const hasItems = itemsData.data && itemsData.data.length > 0

        if (hasItems) {
          // 容器内有物品，确实被占用
          throw new Error(t('container.occupiedByOtherAsn'))
        }

        // 容器已清空，自动清理状态（调用后端 API）
        await fetch(`/api/v1/containers/${container.id}/reset`, {
          method: 'POST'
        })
      }
    }

    const containerInfo: ContainerInfo = {
      id: container.id,
      containerCode: container.containerCode,
      containerType: container.containerType,
      usage: container.purpose,
      workStatus: container.status,
      enabledStatus: container.isEnabled ? 'ENABLED' : 'DISABLED',
      warehouseId: container.warehouseId,
    }

    setCurrentContainer(containerInfo)

    // 加载容器内物品
    await refreshContainerItems(container.id)
  }, [currentAsn, t, setCurrentContainer, refreshContainerItems])

  // 扫描 SKU
  const handleSkuScanned = useCallback(async (barcode: string) => {
    if (!currentAsn) return

    const response = await fetch(
      `/api/v1/asn/${currentAsn.id}/receiving/lookup-sku?barcode=${encodeURIComponent(barcode)}`
    )

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || t('messages.skuNotInAsn'))
    }

    const data = await response.json()
    const { asnLine, sku } = data.data

    const maxQty = asnLine.expectedQty - asnLine.receivedQty
    if (maxQty <= 0) {
      throw new Error(t('messages.skuCompleted'))
    }

    const skuInfo: SkuInfo = {
      id: sku.id,
      skuCode: sku.skuCode,
      skuName: sku.skuName,
      barcode: sku.barcode,
      isFirstReceiving: sku.isFirstReceiving,
      isBatchManaged: sku.isBatchManaged,
      isSerialManaged: sku.isSerialManaged,
      isExpiryManaged: sku.isExpiryManaged,
      lengthCm: sku.lengthCm,
      widthCm: sku.widthCm,
      heightCm: sku.heightCm,
      weightKg: sku.weightKg,
    }

    setCurrentItem({
      asnLineId: asnLine.id,
      sku: skuInfo,
      maxQty,
    })

    // 自动填充 ASN line 中的批次号和过期日期
    if (asnLine.batchNumber) {
      setBatchNumber(asnLine.batchNumber)
    }
    if (asnLine.expiryDate) {
      setExpiryDate(new Date(asnLine.expiryDate))
    }

    if (sku.isFirstReceiving) {
      setShowFirstReceivingDialog(true)
    }
  }, [currentAsn, t, setCurrentItem, setShowFirstReceivingDialog, setBatchNumber, setExpiryDate])

  // 保存收货
  const handleSave = useCallback(async (overrideSerialNumbers?: string[]) => {
    if (!currentAsn || !currentItem || !currentContainer || quantity <= 0) return

    if (currentItem.sku.isBatchManaged && !batchNumber?.trim()) {
      toast.error(t('messages.batchNumberRequired'))
      return
    }

    if (currentItem.sku.isExpiryManaged && !expiryDate) {
      toast.error(t('messages.expiryDateRequired'))
      return
    }

    // 使用传入的序列号或 store 中的序列号
    const finalSerialNumbers = overrideSerialNumbers ?? serialNumbers

    // 验证序列号数量 - 如果不足，弹出序列号扫描对话框
    if (currentItem.sku.isSerialManaged && finalSerialNumbers.length !== quantity) {
      setShowSerialScanDialog(true)
      return
    }

    setIsSubmitting(true)
    try {
      const response = await fetch(`/api/v1/asn/${currentAsn.id}/receiving/sku`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          asnLineId: currentItem.asnLineId,
          receivedQty: quantity,
          qualityStatus,
          batchNumber,
          expiryDate: expiryDate?.toISOString(),
          serialNumbers: currentItem.sku.isSerialManaged ? finalSerialNumbers : [],
          containerId: currentContainer.id,
          containerCode: currentContainer.containerCode,
          containerType: 'INTERNAL_MANAGED',
          receivingMode: 'CONTAINER',
        }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || '收货失败')
      }

      const data = await response.json()

      updateAsnLine(currentItem.asnLineId, {
        receivedQty: data.data.asnLine.receivedQty,
        receivedGoodQty: data.data.asnLine.receivedGoodQty,
        receivedDamagedQty: data.data.asnLine.receivedDamagedQty,
        status: data.data.asnLine.status,
      })

      const receivedLines = asnLines.filter(line => {
        if (line.id === currentItem.asnLineId) {
          return data.data.asnLine.receivedQty > 0
        }
        return line.receivedQty > 0
      }).length

      updateAsnTotals(quantity, receivedLines)

      // 刷新容器内物品
      await refreshContainerItems(currentContainer.id)

      toast.success(t('messages.receiveSuccess'))
      resetCurrentItem()
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '收货失败'
      toast.error(errorMessage)
    } finally {
      setIsSubmitting(false)
    }
  }, [
    currentAsn,
    currentItem,
    currentContainer,
    quantity,
    qualityStatus,
    batchNumber,
    expiryDate,
    serialNumbers,
    asnLines,
    t,
    setIsSubmitting,
    updateAsnLine,
    updateAsnTotals,
    resetCurrentItem,
    refreshContainerItems,
  ])

  // 关箱
  const handleCloseContainer = useCallback(async (): Promise<boolean> => {
    if (!currentContainer) return false

    setIsSubmitting(true)
    try {
      const response = await fetch(`/api/v1/containers/${currentContainer.id}/close`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || '关箱失败')
      }

      const data = await response.json()

      // 如果 ASN 收货完成，清空 ASN 并提示
      if (data.data?.asnUpdated) {
        toast.success(t('messages.completeSuccess'))
        clearAsn()
        return true // ASN 已完成并被清空
      } else {
        toast.success(t('container.closeSuccess'))
        // 只清空容器相关状态
        setCurrentContainer(null)
        setContainerItems([], null)
        resetCurrentItem()
        return false // ASN 未完成
      }
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '关箱失败'
      toast.error(errorMessage)
      return false
    } finally {
      setIsSubmitting(false)
    }
  }, [currentContainer, t, setIsSubmitting, setCurrentContainer, setContainerItems, resetCurrentItem, clearAsn])

  // 重新装箱
  const handleRepackContainer = useCallback(async () => {
    if (!currentContainer || !currentAsn) return

    setIsSubmitting(true)
    try {
      const response = await fetch(`/api/v1/containers/${currentContainer.id}/repack`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ asnId: currentAsn.id }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || '重新装箱失败')
      }

      // 重新加载 ASN 以获取最新的收货数量
      await handleAsnLoaded(currentAsn.asnNumber)

      // 清空容器内物品
      setContainerItems([], null)
      resetCurrentItem()

      toast.success(t('container.repackSuccess'))
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '重新装箱失败'
      toast.error(errorMessage)
    } finally {
      setIsSubmitting(false)
    }
  }, [currentContainer, currentAsn, t, setIsSubmitting, setContainerItems, resetCurrentItem, handleAsnLoaded])

  // 完成收货
  const handleComplete = useCallback(async () => {
    if (!currentAsn) return

    setIsSubmitting(true)
    try {
      const response = await fetch(`/api/v1/asn/${currentAsn.id}/receiving/complete`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || '完成收货失败')
      }

      toast.success(t('messages.completeSuccess'))
      clearAsn()
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '完成收货失败'
      toast.error(errorMessage)
    } finally {
      setIsSubmitting(false)
    }
  }, [currentAsn, t, setIsSubmitting, clearAsn])

  // 首次收货物理属性录入完成
  const handleFirstReceivingComplete = useCallback(() => {
    setShowFirstReceivingDialog(false)
    if (currentItem) {
      setCurrentItem({
        ...currentItem,
        sku: {
          ...currentItem.sku,
          isFirstReceiving: false,
        },
      })
    }
  }, [currentItem, setShowFirstReceivingDialog, setCurrentItem])

  // 序列号扫描完成
  const handleSerialScanConfirm = useCallback((scannedSerials: string[]) => {
    setSerialNumbers(scannedSerials)
    setShowSerialScanDialog(false)
    // 序列号已完整，直接传递序列号触发保存（避免状态更新延迟问题）
    handleSave(scannedSerials)
  }, [setSerialNumbers, handleSave])

  return (
    <div className="space-y-4">
      <Breadcrumb
        items={[
          { label: tMenuGroup('inbound'), href: '/asn' },
          { label: t('title'), href: '/receiving' },
          { label: t('landing.containerMode.title') },
        ]}
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* 左侧扫描区 */}
        <div className="lg:col-span-1">
          <ContainerScanPanel
            onAsnLoaded={handleAsnLoaded}
            onSkuScanned={handleSkuScanned}
            onSave={handleSave}
            onContainerScanned={handleContainerScanned}
            onCloseContainer={handleCloseContainer}
            onRepackContainer={handleRepackContainer}
            onOpenSerialDialog={() => setShowSerialScanDialog(true)}
            initialAsnNumber={initialAsnNumber}
          />
        </div>

        {/* 右侧详情区 */}
        <div className="lg:col-span-2 space-y-4">
          <AsnHeaderCard />
          <AsnLinesTable />
        </div>
      </div>

      {/* 首次收货物理属性录入弹窗 */}
      {currentItem && (
        <FirstReceivingDialog
          open={showFirstReceivingDialog}
          sku={{
            id: currentItem.sku.id,
            skuCode: currentItem.sku.skuCode,
            skuName: currentItem.sku.skuName,
            barcode: currentItem.sku.barcode || null,
            length: currentItem.sku.lengthCm,
            width: currentItem.sku.widthCm,
            height: currentItem.sku.heightCm,
            weight: currentItem.sku.weightKg,
          }}
          onSuccess={handleFirstReceivingComplete}
          onCancel={() => setShowFirstReceivingDialog(false)}
        />
      )}

      {/* 序列号扫描弹窗 */}
      {currentItem && currentItem.sku.isSerialManaged && (
        <SerialScanDialog
          open={showSerialScanDialog}
          skuCode={currentItem.sku.skuCode}
          skuName={currentItem.sku.skuName}
          requiredCount={quantity}
          initialSerialNumbers={serialNumbers}
          onConfirm={handleSerialScanConfirm}
          onCancel={() => setShowSerialScanDialog(false)}
        />
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { SkuScanPanel } from '@/components/receiving/sku-scan-panel'
import { AsnHeaderCard, AsnLinesTable } from '@/components/receiving'
import { SerialScanDialog } from '@/components/receiving/serial-scan-dialog'
import { FirstReceivingDialog } from '@/components/sku/first-receiving-dialog'
import { Breadcrumb } from '@/components/ui/breadcrumb'
import {
  useReceivingStore,
  type AsnInfo,
  type AsnLineInfo,
  type SkuInfo,
} from '@/stores/receiving-store'

export function SkuReceivingPage() {
  const t = useTranslations('receiving')
  const tMenuGroup = useTranslations('menuGroup')
  const searchParams = useSearchParams()
  const initialAsnNumber = searchParams.get('asn')
  const [showSerialScanDialog, setShowSerialScanDialog] = useState(false)
  const {
    currentAsn,
    asnLines,
    currentItem,
    availableBatchLines,
    quantity,
    qualityStatus,
    batchNumber,
    expiryDate,
    serialNumbers,
    showFirstReceivingDialog,
    setAsn,
    setCurrentItem,
    setAvailableBatchLines,
    setIsSubmitting,
    setShowFirstReceivingDialog,
    setReceivingBusinessMode,
    setBatchNumber,
    setExpiryDate,
    setSerialNumbers,
    clearAsn,
    resetCurrentItem,
    updateAsnLine,
    updateAsnTotals,
    updateAsnStatus,
  } = useReceivingStore()

  // 设置收货模式为 SKU
  useEffect(() => {
    setReceivingBusinessMode('sku')
  }, [setReceivingBusinessMode])

  // 加载 ASN
  const handleAsnLoaded = useCallback(async (asnNumber: string) => {
    const response = await fetch(`/api/v1/asn/lookup?asnNumber=${encodeURIComponent(asnNumber)}&receivingMode=SKU`)
    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || t('asn.notFound'))
    }
    const data = await response.json()
    const asn = data.data

    // 转换为 store 格式
    const asnInfo: AsnInfo = {
      id: asn.id,
      asnNumber: asn.asnNumber,
      externalNumber: asn.externalNumber,
      status: asn.status,
      clientName: asn.client?.clientName || null,
      warehouseName: asn.warehouse?.warehouseName || null,
      warehouseId: asn.warehouseId,
      createdAt: asn.createdAt,
      totalExpectedQty: asn.totalExpectedQty,
      totalReceivedQty: asn.totalReceivedQty,
      totalExpectedLines: asn.totalExpectedLines,
      totalReceivedLines: asn.totalReceivedLines,
    }

    const lines: AsnLineInfo[] = asn.asnLines?.map((line: Record<string, unknown>) => ({
      id: line.id as string,
      lineNumber: line.lineNumber as number,
      skuId: line.skuId as string,
      skuCode: line.skuCode as string,
      skuName: line.skuName as string,
      barcode: (line.sku as Record<string, unknown>)?.barcode as string | null,
      expectedQty: line.expectedQty as number,
      receivedQty: line.receivedQty as number,
      receivedGoodQty: line.receivedGoodQty as number,
      receivedDamagedQty: line.receivedDamagedQty as number,
      status: line.status as string,
      batchNumber: line.batchNumber as string | null,
      expiryDate: line.expiryDate as string | null,
    })) || []

    setAsn(asnInfo, lines)
  }, [t, setAsn])

  // 扫描 SKU
  const handleSkuScanned = useCallback(async (barcode: string) => {
    if (!currentAsn) return

    // 查找 ASN 中匹配的行项目
    const response = await fetch(
      `/api/v1/asn/${currentAsn.id}/receiving/lookup-sku?barcode=${encodeURIComponent(barcode)}`
    )

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || t('messages.skuNotInAsn'))
    }

    const data = await response.json()
    const { asnLine, sku, availableBatchLines: batchLines } = data.data

    // 检查是否已全部收货
    const maxQty = asnLine.expectedQty - asnLine.receivedQty
    if (maxQty <= 0) {
      throw new Error(t('messages.skuCompleted'))
    }

    const skuInfo: SkuInfo = {
      id: sku.id,
      skuCode: sku.skuCode,
      skuName: sku.skuName,
      barcode: sku.barcode,
      isFirstReceiving: sku.isFirstReceiving,
      isBatchManaged: sku.isBatchManaged,
      isSerialManaged: sku.isSerialManaged,
      isExpiryManaged: sku.isExpiryManaged,
      lengthCm: sku.lengthCm,
      widthCm: sku.widthCm,
      heightCm: sku.heightCm,
      weightKg: sku.weightKg,
    }

    setCurrentItem({
      asnLineId: asnLine.id,
      sku: skuInfo,
      maxQty,
    })

    // 设置可用批次行
    setAvailableBatchLines(batchLines || [])

    // 自动填充 ASN line 中的批次号和过期日期
    if (asnLine.batchNumber) {
      setBatchNumber(asnLine.batchNumber)
    }
    if (asnLine.expiryDate) {
      setExpiryDate(new Date(asnLine.expiryDate))
    }

    // 检查是否需要首次收货录入物理属性
    if (sku.isFirstReceiving) {
      setShowFirstReceivingDialog(true)
    }
  }, [currentAsn, t, setCurrentItem, setAvailableBatchLines, setShowFirstReceivingDialog, setBatchNumber, setExpiryDate])

  // 保存收货
  const handleSave = useCallback(async (overrideSerialNumbers?: string[]) => {
    if (!currentAsn || !currentItem || quantity <= 0) return

    // 验证批次号
    if (currentItem.sku.isBatchManaged && !batchNumber?.trim()) {
      toast.error(t('messages.batchNumberRequired'))
      return
    }

    // 验证过期时间
    if (currentItem.sku.isExpiryManaged && !expiryDate) {
      toast.error(t('messages.expiryDateRequired'))
      return
    }

    // 使用传入的序列号或 store 中的序列号
    const finalSerialNumbers = overrideSerialNumbers ?? serialNumbers

    // 验证序列号数量 - 如果不足，弹出序列号扫描对话框
    if (currentItem.sku.isSerialManaged && finalSerialNumbers.length !== quantity) {
      setShowSerialScanDialog(true)
      return
    }

    setIsSubmitting(true)
    try {
      const response = await fetch(`/api/v1/asn/${currentAsn.id}/receiving/sku`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          asnLineId: currentItem.asnLineId,
          receivedQty: quantity,
          qualityStatus,
          batchNumber,
          expiryDate: expiryDate?.toISOString(),
          serialNumbers: currentItem.sku.isSerialManaged ? finalSerialNumbers : [],
          containerId: null,
          containerCode: null,
          containerType: null,
          receivingMode: 'SKU',
        }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || '收货失败')
      }

      const data = await response.json()

      // 更新本地状态
      updateAsnLine(currentItem.asnLineId, {
        receivedQty: data.data.asnLine.receivedQty,
        receivedGoodQty: data.data.asnLine.receivedGoodQty,
        receivedDamagedQty: data.data.asnLine.receivedDamagedQty,
        status: data.data.asnLine.status,
      })

      // 计算已收货行数
      const receivedLines = asnLines.filter(line => {
        if (line.id === currentItem.asnLineId) {
          return data.data.asnLine.receivedQty > 0
        }
        return line.receivedQty > 0
      }).length

      updateAsnTotals(quantity, receivedLines)

      // 更新 ASN 状态
      if (data.data.newStatus) {
        updateAsnStatus(data.data.newStatus)

        // 如果收货完成，清空 ASN 让用户可以扫描下一个
        if (data.data.newStatus === 'RECEIVED') {
          toast.success(t('messages.asnCompleted'))
          clearAsn()
          return
        }
      }

      toast.success(t('messages.receiveSuccess'))
      resetCurrentItem()
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '收货失败'
      toast.error(errorMessage)
    } finally {
      setIsSubmitting(false)
    }
  }, [
    currentAsn,
    currentItem,
    quantity,
    qualityStatus,
    batchNumber,
    expiryDate,
    serialNumbers,
    asnLines,
    t,
    setIsSubmitting,
    updateAsnLine,
    updateAsnTotals,
    updateAsnStatus,
    resetCurrentItem,
    clearAsn,
  ])

  // 继续扫描
  const handleContinue = useCallback(() => {
    resetCurrentItem()
  }, [resetCurrentItem])

  // 完成收货
  const handleComplete = useCallback(async () => {
    if (!currentAsn) return

    setIsSubmitting(true)
    try {
      const response = await fetch(`/api/v1/asn/${currentAsn.id}/receiving/complete`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || '完成收货失败')
      }

      toast.success(t('messages.completeSuccess'))
      clearAsn()
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : '完成收货失败'
      toast.error(errorMessage)
    } finally {
      setIsSubmitting(false)
    }
  }, [currentAsn, t, setIsSubmitting, clearAsn])

  // 首次收货物理属性录入完成
  const handleFirstReceivingComplete = useCallback(() => {
    setShowFirstReceivingDialog(false)
    if (currentItem) {
      // 保存当前的批次号和过期日期，因为 setCurrentItem 会重置它们
      const savedBatchNumber = batchNumber
      const savedExpiryDate = expiryDate

      setCurrentItem({
        ...currentItem,
        sku: {
          ...currentItem.sku,
          isFirstReceiving: false,
        },
      })

      // 恢复批次号和过期日期
      if (savedBatchNumber) {
        setBatchNumber(savedBatchNumber)
      }
      if (savedExpiryDate) {
        setExpiryDate(savedExpiryDate)
      }
    }
  }, [currentItem, batchNumber, expiryDate, setShowFirstReceivingDialog, setCurrentItem, setBatchNumber, setExpiryDate])

  // 序列号扫描完成
  const handleSerialScanConfirm = useCallback((scannedSerials: string[]) => {
    setSerialNumbers(scannedSerials)
    setShowSerialScanDialog(false)
    // 序列号已完整，直接传递序列号触发保存（避免状态更新延迟问题）
    handleSave(scannedSerials)
  }, [setSerialNumbers, handleSave])

  return (
    <div className="space-y-4">
      <Breadcrumb
        items={[
          { label: tMenuGroup('inbound'), href: '/asn' },
          { label: t('title'), href: '/receiving' },
          { label: t('landing.skuMode.title') },
        ]}
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* 左侧扫描区 */}
        <div className="lg:col-span-1">
          <SkuScanPanel
            onAsnLoaded={handleAsnLoaded}
            onSkuScanned={handleSkuScanned}
            onSave={handleSave}
            onContinue={handleContinue}
            onOpenSerialDialog={() => setShowSerialScanDialog(true)}
            initialAsnNumber={initialAsnNumber}
          />
        </div>

        {/* 右侧详情区 */}
        <div className="lg:col-span-2 space-y-4">
          <AsnHeaderCard />
          <AsnLinesTable />
        </div>
      </div>

      {/* 首次收货物理属性录入弹窗 */}
      {currentItem && (
        <FirstReceivingDialog
          open={showFirstReceivingDialog}
          sku={{
            id: currentItem.sku.id,
            skuCode: currentItem.sku.skuCode,
            skuName: currentItem.sku.skuName,
            barcode: currentItem.sku.barcode || null,
            length: currentItem.sku.lengthCm,
            width: currentItem.sku.widthCm,
            height: currentItem.sku.heightCm,
            weight: currentItem.sku.weightKg,
          }}
          onSuccess={handleFirstReceivingComplete}
          onCancel={() => setShowFirstReceivingDialog(false)}
        />
      )}

      {/* 序列号扫描弹窗 */}
      {currentItem && currentItem.sku.isSerialManaged && (
        <SerialScanDialog
          open={showSerialScanDialog}
          skuCode={currentItem.sku.skuCode}
          skuName={currentItem.sku.skuName}
          requiredCount={quantity}
          initialSerialNumbers={serialNumbers}
          onConfirm={handleSerialScanConfirm}
          onCancel={() => setShowSerialScanDialog(false)}
        />
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useTranslations } from 'next-intl'
import { WarehouseSelect } from '@/components/warehouses/warehouse-select'
import { EntitySelect, ListFilterCard } from '@/components/list-filters'
import { formatCodeNameLabel } from '@/lib/filters/readable-filter-value'

interface DimensionOption {
  id: string
  name: string
  code?: string
}

interface MultiDimensionFilterProps {
  warehouseId?: string
  clientId?: string
  zoneId?: string
  onWarehouseChange?: (value: string) => void
  onClientChange?: (value: string) => void
  onZoneChange?: (value: string) => void
  showWarehouse?: boolean
  showClient?: boolean
  showZone?: boolean
}

export function MultiDimensionFilter({
  warehouseId = '',
  clientId = '',
  zoneId = '',
  onWarehouseChange,
  onClientChange,
  onZoneChange,
  showWarehouse = true,
  showClient = false,
  showZone = false,
}: MultiDimensionFilterProps) {
  const tCommon = useTranslations('common')
  const [clients, setClients] = useState<DimensionOption[]>([])
  const [zones, setZones] = useState<DimensionOption[]>([])
  const zoneOptions = warehouseId ? zones : []

  useEffect(() => {
    if (!showClient) return

    fetch('/api/v1/clients?pageSize=100')
      .then((res) => res.json())
      .then((result) => {
        if (result.success) {
          setClients(result.data.map((client: any) => ({
            id: client.id,
            name: client.clientName,
            code: client.clientCode,
          })))
        }
      })
  }, [showClient])

  useEffect(() => {
    if (!showZone) return

    if (!warehouseId) return

    fetch(`/api/v1/zones?warehouseId=${warehouseId}&pageSize=100&status=ACTIVE`)
      .then((res) => res.json())
      .then((result) => {
        if (result.success) {
          setZones(result.data.map((zone: any) => ({
            id: zone.id,
            name: zone.zoneName,
            code: zone.zoneCode,
          })))
        } else {
          setZones([])
        }
      })
      .catch(() => setZones([]))
  }, [showZone, warehouseId])

  return (
    <ListFilterCard mode="compact" className="p-3">
      <div className="flex flex-wrap items-center gap-3">
        {showWarehouse && onWarehouseChange && (
          <WarehouseSelect
            value={warehouseId}
            onValueChange={onWarehouseChange}
            showAll
            className="h-8 w-[180px]"
          />
        )}

        {showClient && onClientChange && (
          <EntitySelect
            value={clientId}
            onValueChange={onClientChange}
            showAll
            placeholder={tCommon('allClients')}
            allLabel={tCommon('allClients')}
            searchPlaceholder={tCommon('search')}
            emptyText={tCommon('noResults')}
            className="w-[180px]"
            options={clients.map((client) => ({
              value: client.id,
              label: formatCodeNameLabel(client.code, client.name),
              keywords: [client.code || '', client.name],
            }))}
          />
        )}

        {showZone && onZoneChange && (
          <EntitySelect
            value={zoneId}
            onValueChange={onZoneChange}
            showAll
            disabled={!warehouseId}
            placeholder={tCommon('allZones')}
            allLabel={tCommon('allZones')}
            searchPlaceholder={tCommon('search')}
            emptyText={tCommon('noResults')}
            className="w-[180px]"
            options={zoneOptions.map((zone) => ({
              value: zone.id,
              label: formatCodeNameLabel(zone.code, zone.name),
              keywords: [zone.code || '', zone.name],
            }))}
          />
        )}
      </div>
    </ListFilterCard>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { toast } from 'sonner'
import { RefreshCw, Play, Pause, Clock, Plus } from 'lucide-react'
import { useTranslations } from 'next-intl'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { Switch } from '@/components/ui/switch'
import { formatDateTime } from '@/lib/utils/date-formatter'

interface ScheduledTask {
  id: string
  taskCode: string
  taskName: string
  description: string | null
  cronExpression: string
  handler: string
  isActive: boolean
  lastRunAt: string | null
  nextRunAt: string | null
  lastRunStatus: string | null
  lastRunDuration: number | null
  runCount: number
  failCount: number
  createdAt: string
}

interface Handler {
  name: string
  description: string
}

const TASK_TYPES = [
  { value: 'INVENTORY_ALERT', label: 'scheduledTask.taskTypes.INVENTORY_ALERT' },
  { value: 'DATA_SYNC', label: 'scheduledTask.taskTypes.DATA_SYNC' },
  { value: 'REPORT_GENERATE', label: 'scheduledTask.taskTypes.REPORT_GENERATE' },
  { value: 'DATA_CLEANUP', label: 'scheduledTask.taskTypes.DATA_CLEANUP' },
  { value: 'CUSTOM', label: 'scheduledTask.taskTypes.CUSTOM' },
]

export function ScheduledTasksPage() {
  const t = useTranslations('scheduledTask')
  const tCommon = useTranslations('common')
  const [tasks, setTasks] = useState<ScheduledTask[]>([])
  const [handlers, setHandlers] = useState<Handler[]>([])
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const [createDialogOpen, setCreateDialogOpen] = useState(false)
  const [creating, setCreating] = useState(false)
  const [formData, setFormData] = useState({
    taskCode: '',
    taskName: '',
    description: '',
    cronExpression: '0 0 * * *',
    handler: '',
    isActive: true,
  })

  const fetchTasks = useCallback(async () => {
    try {
      const res = await fetch('/api/v1/scheduled-tasks')
      const data = await res.json()
      if (data.success) {
        setTasks(data.data)
      } else {
        toast.error(data.message || t('fetchFailed'))
      }
    } catch {
      toast.error(t('fetchFailed'))
    } finally {
      setLoading(false)
    }
  }, [t])

  const fetchHandlers = useCallback(async () => {
    try {
      const res = await fetch('/api/v1/scheduled-tasks/handlers')
      const data = await res.json()
      if (data.success) {
        setHandlers(data.data)
      }
    } catch {
      // ignore
    }
  }, [])

  useEffect(() => {
    fetchTasks()
    fetchHandlers()
  }, [fetchTasks, fetchHandlers])

  const handleToggle = async (task: ScheduledTask) => {
    setActionLoading(task.id)
    try {
      const res = await fetch(`/api/v1/scheduled-tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: !task.isActive }),
      })
      const data = await res.json()
      if (data.success) {
        toast.success(task.isActive ? t('disableSuccess') : t('enableSuccess'))
        fetchTasks()
      } else {
        toast.error(data.message || t('operationFailed'))
      }
    } catch {
      toast.error(t('operationFailed'))
    } finally {
      setActionLoading(null)
    }
  }

  const handleTrigger = async (task: ScheduledTask) => {
    setActionLoading(task.id)
    try {
      const res = await fetch(`/api/v1/scheduled-tasks/${task.id}/trigger`, {
        method: 'POST',
      })
      const data = await res.json()
      if (data.success) {
        toast.success(t('triggerSuccess'))
        fetchTasks()
      } else {
        toast.error(data.message || t('triggerFailed'))
      }
    } catch {
      toast.error(t('triggerFailed'))
    } finally {
      setActionLoading(null)
    }
  }

  const handleCreate = async () => {
    if (!formData.taskCode || !formData.taskName || !formData.handler) {
      toast.error(t('requiredFields'))
      return
    }

    setCreating(true)
    try {
      const res = await fetch('/api/v1/scheduled-tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      })
      const data = await res.json()
      if (data.success) {
        toast.success(t('createSuccess'))
        setCreateDialogOpen(false)
        setFormData({
          taskCode: '',
          taskName: '',
          description: '',
          cronExpression: '0 0 * * *',
          handler: '',
          isActive: true,
        })
        fetchTasks()
      } else {
        toast.error(data.message || t('createFailed'))
      }
    } catch {
      toast.error(t('createFailed'))
    } finally {
      setCreating(false)
    }
  }

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return '-'
    return formatDateTime(dateStr)
  }

  const getStatusBadge = (status: string | null) => {
    if (!status) return <Badge variant="secondary">{t('status.NOT_EXECUTED')}</Badge>
    switch (status) {
      case 'SUCCESS':
        return <Badge variant="default" className="bg-green-500">{t('status.SUCCESS')}</Badge>
      case 'FAILED':
        return <Badge variant="destructive">{t('status.FAILED')}</Badge>
      case 'RUNNING':
        return <Badge variant="default" className="bg-blue-500">{t('status.RUNNING')}</Badge>
      default:
        return <Badge variant="secondary">{status}</Badge>
    }
  }

  if (loading) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold">{t('title')}</h1>
        </div>
        <div className="border rounded-lg">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t('taskName')}</TableHead>
                <TableHead>{t('cronExpression')}</TableHead>
                <TableHead>{t('isActive')}</TableHead>
                <TableHead>{t('lastRunAt')}</TableHead>
                <TableHead>{t('nextRunAt')}</TableHead>
                <TableHead>{t('executionStats')}</TableHead>
                <TableHead>{tCommon('actions')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {Array.from({ length: 3 }).map((_, i) => (
                <TableRow key={i}>
                  {Array.from({ length: 7 }).map((_, j) => (
                    <TableCell key={j}>
                      <Skeleton className="h-4 w-full" />
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">{t('title')}</h1>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => fetchTasks()}>
            <RefreshCw className="h-4 w-4 mr-2" />
            {tCommon('refresh')}
          </Button>
          <Button size="sm" onClick={() => setCreateDialogOpen(true)}>
            <Plus className="h-4 w-4 mr-2" />
            {t('create')}
          </Button>
        </div>
      </div>

      <div className="border rounded-lg">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{t('taskName')}</TableHead>
              <TableHead>{t('cronExpression')}</TableHead>
              <TableHead>{t('isActive')}</TableHead>
              <TableHead>{t('lastRunAt')}</TableHead>
              <TableHead>{t('nextRunAt')}</TableHead>
              <TableHead>{t('executionStats')}</TableHead>
              <TableHead className="w-[150px]">{tCommon('actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {tasks.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} className="text-center text-muted-foreground py-8">
                  {t('noTasks')}
                </TableCell>
              </TableRow>
            ) : (
              tasks.map((task) => (
                <TableRow key={task.id}>
                  <TableCell>
                    <div>
                      <div className="font-medium">{task.taskName}</div>
                      <div className="text-sm text-muted-foreground">{task.description || task.taskCode}</div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <code className="text-sm bg-muted px-2 py-1 rounded">{task.cronExpression}</code>
                  </TableCell>
                  <TableCell>
                    {task.isActive ? (
                      <Badge variant="default" className="bg-green-500">{t('enabled')}</Badge>
                    ) : (
                      <Badge variant="secondary">{t('disabled')}</Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    <div className="text-sm">
                      <div>{formatDate(task.lastRunAt) || '-'}</div>
                      {task.lastRunStatus && (
                        <div className="mt-1">{getStatusBadge(task.lastRunStatus)}</div>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="text-sm">{formatDate(task.nextRunAt) || '-'}</TableCell>
                  <TableCell>
                    <div className="text-sm">
                      <span className="text-green-600">{task.runCount} {t('times')}</span>
                      {task.failCount > 0 && (
                        <span className="text-red-600 ml-2">({task.failCount} {t('failed')})</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleToggle(task)}
                        disabled={actionLoading === task.id}
                        title={task.isActive ? t('disable') : t('enable')}
                      >
                        {task.isActive ? (
                          <Pause className="h-4 w-4" />
                        ) : (
                          <Play className="h-4 w-4" />
                        )}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleTrigger(task)}
                        disabled={actionLoading === task.id}
                        title={t('trigger')}
                      >
                        <Clock className="h-4 w-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* 创建任务对话框 */}
      <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{t('createDialog')}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="taskCode">{t('taskCode')} *</Label>
              <Input
                id="taskCode"
                value={formData.taskCode}
                onChange={(e) => setFormData({ ...formData, taskCode: e.target.value })}
                placeholder={t('taskCodePlaceholder')}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="taskName">{t('taskName')} *</Label>
              <Input
                id="taskName"
                value={formData.taskName}
                onChange={(e) => setFormData({ ...formData, taskName: e.target.value })}
                placeholder={t('taskNamePlaceholder')}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="description">{t('description')}</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder={t('descriptionPlaceholder')}
                rows={2}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="handler">{t('handler')} *</Label>
              <Select
                value={formData.handler}
                onValueChange={(value) => setFormData({ ...formData, handler: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t('handlerPlaceholder')} />
                </SelectTrigger>
                <SelectContent>
                  {handlers.map((handler) => (
                    <SelectItem key={handler.name} value={handler.name}>
                      {handler.description}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="cronExpression">{t('cronExpression')} *</Label>
              <Input
                id="cronExpression"
                value={formData.cronExpression}
                onChange={(e) => setFormData({ ...formData, cronExpression: e.target.value })}
                placeholder={t('cronExpressionPlaceholder')}
              />
              <p className="text-xs text-muted-foreground">
                {t('cronExpressionHelp')}
              </p>
            </div>
            <div className="flex items-center justify-between">
              <Label htmlFor="isActive">{t('enableImmediately')}</Label>
              <Switch
                id="isActive"
                checked={formData.isActive}
                onCheckedChange={(checked) => setFormData({ ...formData, isActive: checked })}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>
              {tCommon('cancel')}
            </Button>
            <Button onClick={handleCreate} disabled={creating}>
              {creating ? tCommon('submitting') : tCommon('create')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useRef, useEffect, useCallback } from 'react'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import {
  MapPin,
  ScanLine,
  Minus,
  Plus,
  Save,
  RotateCcw,
  X,
  ClipboardList,
  Calendar,
  Package,
} from 'lucide-react'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { Separator } from '@/components/ui/separator'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { formatDate } from '@/lib/utils/date-formatter'

interface LocationInfo {
  id: string
  locationCode: string
  zoneId: string
  zoneName: string | null
  zoneQualityType?: string
  warehouseId: string
}

interface SkuInfo {
  id: string
  skuCode: string
  skuName: string | null
  barcode: string | null
  isSerialManaged: boolean
  clientId: string
}

interface PutawayTaskInfo {
  id: string
  skuId: string
  skuCode: string
  skuName?: string | null
  remainingQty: number
  qualityType?: string
  batchNumber?: string | null
  expiryDate?: string | null
}

interface PutawayOrderInfo {
  id: string
  putawayOrderNumber: string
  status: string
  putawayTasks?: PutawayTaskInfo[]
}

interface SkuShelvingPanelProps {
  onSave: (data: {
    locationId: string
    locationCode: string
    skuId: string
    skuCode: string
    quantity: number
    serialNumbers: string[]
    warehouseId: string
    clientId: string
    // 选中的任务信息
    putawayLineId?: string
    batchNumber?: string | null
    expiryDate?: string | null
  }) => Promise<void>
  quantity: number
  setQuantity: (qty: number) => void
  currentSku: SkuInfo | null
  setCurrentSku: (sku: SkuInfo | null) => void
  currentLocation: LocationInfo | null
  setCurrentLocation: (location: LocationInfo | null) => void
  isSubmitting: boolean
  // 上架单相关
  putawayOrderInput: string
  setPutawayOrderInput: (value: string) => void
  currentPutawayOrder: PutawayOrderInfo | null
  onLoadPutawayOrder: (orderNumber: string) => Promise<void>
  onClearPutawayOrder: () => void
  isLoadingOrder: boolean
}

export function SkuShelvingPanel({
  onSave,
  quantity,
  setQuantity,
  currentSku,
  setCurrentSku,
  currentLocation,
  setCurrentLocation,
  isSubmitting,
  putawayOrderInput,
  setPutawayOrderInput,
  currentPutawayOrder,
  onLoadPutawayOrder,
  onClearPutawayOrder,
  isLoadingOrder,
}: SkuShelvingPanelProps) {
  const t = useTranslations('shelving')
  const tCommon = useTranslations('common')

  // 上架单是否已完成
  const isOrderCompleted = currentPutawayOrder?.status === 'COMPLETED'

  const [locationInput, setLocationInput] = useState('')
  const [skuInput, setSkuInput] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [maxQuantity, setMaxQuantity] = useState<number>(0)
  // 匹配的任务列表（按质量类型过滤后）
  const [matchingTasks, setMatchingTasks] = useState<PutawayTaskInfo[]>([])
  // 选中的效期和批次（分开选择）
  const [selectedExpiry, setSelectedExpiry] = useState<string>('')
  const [selectedBatch, setSelectedBatch] = useState<string>('')

  const orderInputRef = useRef<HTMLInputElement>(null)
  const locationInputRef = useRef<HTMLInputElement>(null)
  const skuInputRef = useRef<HTMLInputElement>(null)
  const quantityInputRef = useRef<HTMLInputElement>(null)

  // 自动聚焦
  useEffect(() => {
    if (!currentPutawayOrder && orderInputRef.current) {
      orderInputRef.current.focus()
    } else if (currentPutawayOrder && !currentSku && skuInputRef.current) {
      skuInputRef.current.focus()
    } else if (currentSku && !currentLocation && locationInputRef.current) {
      locationInputRef.current.focus()
    }
  }, [currentPutawayOrder, currentSku, currentLocation])

  // 上架单号提交
  const handleOrderSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!putawayOrderInput.trim()) return
    await onLoadPutawayOrder(putawayOrderInput.trim())
  }

  // 货位提交
  const handleLocationSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = locationInput.trim()
    if (!trimmed || !currentSku) return

    setIsLoading(true)
    try {
      const response = await fetch(
        `/api/v1/shelving/location?locationCode=${encodeURIComponent(trimmed)}`
      )

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || t('messages.locationNotFound'))
      }

      const data = await response.json()
      const location = data.data

      // 获取当前SKU对应的所有未完成任务
      const allMatchingTasks = currentPutawayOrder?.putawayTasks?.filter(
        task => (task.skuId === currentSku.id || task.skuCode === currentSku.skuCode) && task.remainingQty > 0
      ) || []

      const zoneQualityType = location.zoneQualityType || 'GOOD'

      // 根据货位质量类型，筛选匹配的任务（可能有多个不同效期/批次）
      const filteredTasks = allMatchingTasks.filter(task => {
        const taskQualityType = task.qualityType || 'GOOD'
        // 良品库区匹配良品任务，非良品库区匹配非良品任务
        if (zoneQualityType === 'GOOD') {
          return taskQualityType === 'GOOD'
        } else {
          return taskQualityType !== 'GOOD'
        }
      })

      // 如果没有找到匹配的任务，说明质量类型不匹配
      if (filteredTasks.length === 0) {
        if (zoneQualityType === 'GOOD') {
          throw new Error(`该货位是良品库区，但该SKU没有待上架的良品任务`)
        } else {
          throw new Error(`该货位是${location.zoneName || '不良品'}库区，但该SKU没有待上架的不良品任务`)
        }
      }

      setCurrentLocation({
        id: location.id,
        locationCode: location.locationCode,
        zoneId: location.zoneId,
        zoneName: location.zoneName,
        zoneQualityType: location.zoneQualityType,
        warehouseId: location.warehouseId,
      })
      setLocationInput('')
      setQuantity(0)

      // 保存匹配的任务列表
      setMatchingTasks(filteredTasks)

      // 提取唯一的效期和批次列表，默认选择第一个
      const expirySet = new Set(filteredTasks.map(t => t.expiryDate || ''))
      const batchSet = new Set(filteredTasks.map(t => t.batchNumber || ''))
      const firstExpiry = Array.from(expirySet)[0] || ''
      const firstBatch = Array.from(batchSet)[0] || ''

      setSelectedExpiry(firstExpiry)
      setSelectedBatch(firstBatch)

      // 找到匹配的任务并设置 maxQuantity
      const matchedTask = filteredTasks.find(t =>
        (t.expiryDate || '') === firstExpiry && (t.batchNumber || '') === firstBatch
      )
      if (matchedTask) {
        setMaxQuantity(matchedTask.remainingQty)
      } else if (filteredTasks.length > 0) {
        // 如果没有精确匹配，使用第一个任务
        setMaxQuantity(filteredTasks[0].remainingQty)
      }

      toast.success(t('messages.locationLoaded'))
      // 聚焦到数量输入框
      setTimeout(() => quantityInputRef.current?.focus(), 50)
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : t('messages.locationNotFound')
      toast.error(msg)
      setLocationInput('')
      setTimeout(() => locationInputRef.current?.focus(), 50)
    } finally {
      setIsLoading(false)
    }
  }

  // 计算唯一的效期列表和批次列表
  const uniqueExpiries = Array.from(new Set(matchingTasks.map(t => t.expiryDate || '')))
  const uniqueBatches = Array.from(new Set(matchingTasks.map(t => t.batchNumber || '')))

  // 根据选中的效期和批次，找到对应的任务
  const selectedTask = matchingTasks.find(t =>
    (t.expiryDate || '') === selectedExpiry && (t.batchNumber || '') === selectedBatch
  ) || (matchingTasks.length === 1 ? matchingTasks[0] : null)

  // 效期选择变更
  const handleExpiryChange = (expiry: string) => {
    setSelectedExpiry(expiry)
    // 更新 maxQuantity
    const task = matchingTasks.find(t =>
      (t.expiryDate || '') === expiry && (t.batchNumber || '') === selectedBatch
    )
    if (task) {
      setMaxQuantity(task.remainingQty)
      if (quantity > task.remainingQty) {
        setQuantity(0)
      }
    }
  }

  // 批次选择变更
  const handleBatchChange = (batch: string) => {
    setSelectedBatch(batch)
    // 更新 maxQuantity
    const task = matchingTasks.find(t =>
      (t.expiryDate || '') === selectedExpiry && (t.batchNumber || '') === batch
    )
    if (task) {
      setMaxQuantity(task.remainingQty)
      if (quantity > task.remainingQty) {
        setQuantity(0)
      }
    }
  }

  // 清除货位
  const handleClearLocation = () => {
    setCurrentLocation(null)
    setLocationInput('')
    setMatchingTasks([])
    setSelectedExpiry('')
    setSelectedBatch('')
    setMaxQuantity(0)
    setTimeout(() => locationInputRef.current?.focus(), 100)
  }

  // SKU提交
  const handleSkuSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = skuInput.trim()
    if (!trimmed) return

    setIsLoading(true)
    try {
      // 查询SKU信息
      const response = await fetch(
        `/api/v1/shelving/sku?barcode=${encodeURIComponent(trimmed)}`
      )

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.message || t('skuMode.skuNotFound'))
      }

      const data = await response.json()
      const sku = data.data

      // 检查该SKU在上架单中是否已完成
      if (currentPutawayOrder) {
        // 找到所有匹配该SKU的任务
        const matchingTasks = currentPutawayOrder.putawayTasks?.filter(
          task => task.skuId === sku.id || task.skuCode === sku.skuCode
        ) || []

        if (matchingTasks.length > 0) {
          // 检查是否所有任务都已完成（所有任务的剩余数量都为0）
          const allCompleted = matchingTasks.every(task => task.remainingQty <= 0)

          if (allCompleted) {
            toast.warning(t('messages.skuAlreadyCompleted'))
            setSkuInput('')
            setTimeout(() => skuInputRef.current?.focus(), 50)
            return
          }
        }
      }

      setCurrentSku({
        id: sku.id,
        skuCode: sku.skuCode,
        skuName: sku.skuName,
        barcode: sku.barcode,
        isSerialManaged: sku.isSerialManaged,
        clientId: sku.clientId,
      })
      setSkuInput('')

      setTimeout(() => locationInputRef.current?.focus(), 50)
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : t('skuMode.skuNotFound')
      toast.error(msg)
    } finally {
      setIsLoading(false)
    }
  }, [skuInput, currentPutawayOrder, t, setQuantity, setCurrentSku])

  // 清除SKU
  const handleClearSku = () => {
    setCurrentSku(null)
    setCurrentLocation(null)
    setSkuInput('')
    setLocationInput('')
    setQuantity(0)
    setMatchingTasks([])
    setSelectedExpiry('')
    setSelectedBatch('')
    setMaxQuantity(0)
    setTimeout(() => skuInputRef.current?.focus(), 100)
  }

  // 数量输入
  const handleQtyChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value
    // 允许清空输入框
    if (value === '') {
      setQuantity(0)
      return
    }
    const numValue = parseInt(value, 10)
    if (!isNaN(numValue) && numValue > 0) {
      // 限制不能超过最大数量
      const finalValue = Math.min(numValue, maxQuantity)
      setQuantity(finalValue)
      // 如果输入的值超过最大值，提示用户
      if (numValue > maxQuantity) {
        toast.warning(t('messages.qtyExceedsRemaining', { max: maxQuantity }))
      }
    }
  }

  // 增减数量
  const adjustQuantity = (delta: number) => {
    const newQty = quantity + delta
    if (newQty > 0 && newQty <= maxQuantity) {
      setQuantity(newQty)
    }
  }

  // 是否可以保存
  const canSave = currentLocation && currentSku && quantity > 0 && selectedTask

  // 保存
  const handleSave = async () => {
    if (!canSave || !currentLocation || !currentSku || !selectedTask) return

    await onSave({
      locationId: currentLocation.id,
      locationCode: currentLocation.locationCode,
      skuId: currentSku.id,
      skuCode: currentSku.skuCode,
      quantity,
      serialNumbers: [],
      warehouseId: currentLocation.warehouseId,
      clientId: currentSku.clientId,
      // 传递选中任务的信息
      putawayLineId: selectedTask.id,
      batchNumber: selectedTask.batchNumber,
      expiryDate: selectedTask.expiryDate,
    })
  }

  // 重置
  const handleReset = () => {
    setCurrentSku(null)
    setSkuInput('')
    setQuantity(0)
    setTimeout(() => skuInputRef.current?.focus(), 100)
  }

  return (
    <Card>
      <CardContent className="p-4 space-y-4">
        {/* 上架单号扫描 */}
        <div className="space-y-2">
          <Label className="flex items-center gap-2">
            <ClipboardList className="h-4 w-4" />
            {t('putawayOrder.scanLabel')}
          </Label>
          {currentPutawayOrder ? (
            <div className="flex items-center gap-2">
              <Badge variant="secondary" className="flex-1 justify-center py-2">
                {currentPutawayOrder.putawayOrderNumber}
              </Badge>
              <Button
                variant="ghost"
                size="icon"
                onClick={onClearPutawayOrder}
                disabled={isLoadingOrder || isSubmitting}
              >
                <X className="h-4 w-4" />
              </Button>
            </div>
          ) : (
            <form onSubmit={handleOrderSubmit}>
              <Input
                ref={orderInputRef}
                value={putawayOrderInput}
                onChange={(e) => setPutawayOrderInput(e.target.value)}
                placeholder={t('putawayOrder.scanPlaceholder')}
                disabled={isLoadingOrder}
              />
            </form>
          )}
        </div>

        {/* SKU扫描 */}
        <div className="space-y-2">
          <Label className="flex items-center gap-2">
            <ScanLine className="h-4 w-4" />
            {t('sku.label')}
          </Label>
          {currentSku ? (
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="flex-1 justify-center py-2">
                  {currentSku.skuCode}
                </Badge>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleClearSku}
                  disabled={isLoading || isSubmitting}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
              {currentSku.skuName && (
                <p className="text-sm text-muted-foreground truncate">
                  {currentSku.skuName}
                </p>
              )}
            </div>
          ) : (
            <form onSubmit={handleSkuSubmit}>
              <Input
                ref={skuInputRef}
                value={skuInput}
                onChange={(e) => setSkuInput(e.target.value)}
                placeholder={t('sku.placeholder')}
                disabled={isLoading || !currentPutawayOrder || isOrderCompleted}
              />
            </form>
          )}
        </div>

        {/* 货位扫描 */}
        <div className="space-y-2">
          <Label className="flex items-center gap-2">
            <MapPin className="h-4 w-4" />
            {t('location.label')}
          </Label>
          {currentLocation ? (
            <div className="flex items-center gap-2">
              <Badge variant="secondary" className="flex-1 justify-center py-2">
                {currentLocation.locationCode}
                {currentLocation.zoneName && (
                  <span className="ml-2 text-muted-foreground">
                    ({currentLocation.zoneName})
                  </span>
                )}
              </Badge>
              <Button
                variant="ghost"
                size="icon"
                onClick={handleClearLocation}
                disabled={isLoading || isSubmitting}
              >
                <X className="h-4 w-4" />
              </Button>
            </div>
          ) : (
            <form onSubmit={handleLocationSubmit}>
              <Input
                ref={locationInputRef}
                value={locationInput}
                onChange={(e) => setLocationInput(e.target.value)}
                placeholder={t('location.placeholder')}
                disabled={isLoading || !currentSku || isOrderCompleted}
              />
            </form>
          )}
        </div>

        {/* 数量输入 */}
        {currentSku && currentLocation && (
          <>
            <Separator />
            <div className="space-y-2">
              <Label className="flex items-center justify-between">
                <span>{t('quantity.label')}</span>
                {maxQuantity > 0 && (
                  <span className="text-sm text-muted-foreground">
                    {t('quantity.max')}: {maxQuantity}
                  </span>
                )}
              </Label>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => adjustQuantity(-1)}
                  disabled={quantity <= 1 || isSubmitting}
                >
                  <Minus className="h-4 w-4" />
                </Button>
                <Input
                  ref={quantityInputRef}
                  type="number"
                  value={quantity || ''}
                  onChange={handleQtyChange}
                  className="text-center"
                  min={1}
                  max={maxQuantity || undefined}
                  disabled={isSubmitting}
                />
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => adjustQuantity(1)}
                  disabled={quantity >= maxQuantity || isSubmitting}
                >
                  <Plus className="h-4 w-4" />
                </Button>
              </div>
            </div>

            {/* 效期选择 - 当有多个效期时显示 */}
            {uniqueExpiries.length > 1 && (
              <div className="space-y-2">
                <Label className="flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {t('expiryBatch.expiry')}
                </Label>
                <Select value={selectedExpiry} onValueChange={handleExpiryChange}>
                  <SelectTrigger>
                    <SelectValue placeholder={t('expiryBatch.selectExpiry')} />
                  </SelectTrigger>
                  <SelectContent>
                    {uniqueExpiries.map(expiry => (
                      <SelectItem key={expiry || 'none'} value={expiry}>
                        {expiry ? formatDate(expiry) : t('expiryBatch.noExpiry')}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* 批次选择 - 当有多个批次时显示 */}
            {uniqueBatches.length > 1 && (
              <div className="space-y-2">
                <Label className="flex items-center gap-2">
                  <Package className="h-4 w-4" />
                  {t('expiryBatch.batch')}
                </Label>
                <Select value={selectedBatch} onValueChange={handleBatchChange}>
                  <SelectTrigger>
                    <SelectValue placeholder={t('expiryBatch.selectBatch')} />
                  </SelectTrigger>
                  <SelectContent>
                    {uniqueBatches.map(batch => (
                      <SelectItem key={batch || 'none'} value={batch}>
                        {batch || t('expiryBatch.noBatch')}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* 显示选中的效期/批次信息 - 当各自只有一个选项时 */}
            {uniqueExpiries.length === 1 && uniqueBatches.length === 1 && selectedTask && (selectedTask.expiryDate || selectedTask.batchNumber) && (
              <div className="text-sm text-muted-foreground bg-muted/50 p-2 rounded">
                {selectedTask.expiryDate && (
                  <span>{t('expiryBatch.expiry')}: {formatDate(selectedTask.expiryDate)}</span>
                )}
                {selectedTask.expiryDate && selectedTask.batchNumber && <span className="mx-2">|</span>}
                {selectedTask.batchNumber && (
                  <span>{t('expiryBatch.batch')}: {selectedTask.batchNumber}</span>
                )}
              </div>
            )}

            {/* 显示剩余数量提示 */}
            {selectedTask && (
              <div className="text-sm text-muted-foreground">
                {t('expiryBatch.remaining')}: {selectedTask.remainingQty}
              </div>
            )}

            <Separator />

            {/* 操作按钮 */}
            <div className="flex gap-2">
              <Button
                variant="outline"
                className="flex-1"
                onClick={handleReset}
                disabled={isSubmitting}
              >
                <RotateCcw className="h-4 w-4 mr-1" />
                {tCommon('reset')}
              </Button>
              <Button
                className="flex-1"
                onClick={handleSave}
                disabled={!canSave || isSubmitting}
              >
                <Save className="h-4 w-4 mr-1" />
                {t('actions.shelve')}
              </Button>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  )
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useTranslations } from 'next-intl'
import {
  LayoutDashboard,
  Package,
  Warehouse,
  ClipboardList,
  Users,
  Shield,
  Settings,
  ChevronLeft,
  ChevronRight,
  ChevronDown,
  MapPin,
  Grid3X3,
  Box,
  Building2,
  Tags,
  Building,
  FileInput,
  PackageCheck,
  Database,
  Truck,
  LayoutGrid,
  Layers,
  PackageSearch,
  FileText,
  BarChart3,
  ListTodo,
  Key,
  ArrowUpToLine,
  Archive,
  ClipboardCheck,
  Clock,
  Printer,
} from 'lucide-react'
import { useState, useEffect, useRef } from 'react'
import { cn } from '@/lib/utils'
import { usePermissions } from '@/contexts/permission-context'

interface MenuItem {
  key: string
  icon: React.ReactNode
  href: string
  permission?: string // 所需权限，为空则所有人可见
}

interface SubMenuGroup {
  key: string
  icon: React.ReactNode
  items: MenuItem[]
}

interface MenuGroup {
  key: string
  icon: React.ReactNode
  items: (MenuItem | SubMenuGroup)[]
}

// 类型守卫函数
function isSubMenuGroup(item: MenuItem | SubMenuGroup): item is SubMenuGroup {
  return 'items' in item && Array.isArray((item as SubMenuGroup).items)
}

export function Sidebar() {
  const pathname = usePathname()
  const t = useTranslations('menu')
  const tGroup = useTranslations('menuGroup')
  const tCommon = useTranslations('common')
  const [collapsed, setCollapsed] = useState(false)
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({
    inbound: false,
    outbound: false,
    inventory: false,
    warehouseInfra: false,
    masterData: false,
    reports: false,
    system: false,
  })
  const [expandedSubGroups, setExpandedSubGroups] = useState<Record<string, boolean>>({})
  const [hoveredGroup, setHoveredGroup] = useState<string | null>(null)
  const [hoverPosition, setHoverPosition] = useState<{ top: number } | null>(null)
  const hoverTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const { hasPermission, loading } = usePermissions()

  // 处理菜单组悬停
  const handleGroupMouseEnter = (groupKey: string, event: React.MouseEvent) => {
    if (!collapsed) return
    // 清除关闭定时器
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current)
      hoverTimeoutRef.current = null
    }
    const rect = (event.currentTarget as HTMLElement).getBoundingClientRect()
    setHoveredGroup(groupKey)
    setHoverPosition({ top: rect.top })
  }

  const handleGroupMouseLeave = () => {
    if (!collapsed) return
    // 延迟关闭，给用户时间移动到浮显菜单
    hoverTimeoutRef.current = setTimeout(() => {
      setHoveredGroup(null)
      setHoverPosition(null)
    }, 150)
  }

  const handlePopoverMouseEnter = () => {
    // 鼠标进入浮显菜单，清除关闭定时器
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current)
      hoverTimeoutRef.current = null
    }
  }

  const handlePopoverMouseLeave = () => {
    // 鼠标离开浮显菜单，立即关闭
    setHoveredGroup(null)
    setHoverPosition(null)
  }

  // Dashboard 单独放在顶部
  const dashboardItem: MenuItem = {
    key: 'dashboard',
    icon: <LayoutDashboard className="h-5 w-5" />,
    href: '/dashboard',
  }

  // 分组菜单 (按业务优先级排序)
  const menuGroups: MenuGroup[] = [
    {
      key: 'inbound',
      icon: <PackageCheck className="h-4 w-4" />,
      items: [
        { key: 'asn', icon: <FileInput className="h-5 w-5" />, href: '/asn', permission: 'asn:read' },
        // 上架管理子菜单组
        {
          key: 'putawayGroup',
          icon: <ArrowUpToLine className="h-5 w-5" />,
          items: [
            { key: 'createPutaway', icon: <PackageCheck className="h-5 w-5" />, href: '/putaway/create', permission: 'putaway:read' },
            { key: 'putawayOrders', icon: <ClipboardList className="h-5 w-5" />, href: '/putaway', permission: 'putaway:read' },
          ],
        },
        // 入库操作子菜单组
        {
          key: 'receivingGroup',
          icon: <PackageCheck className="h-5 w-5" />,
          items: [
            { key: 'asnSignIn', icon: <ClipboardCheck className="h-5 w-5" />, href: '/asn-sign-in', permission: 'asn:sign-in' },
            { key: 'receiving', icon: <PackageCheck className="h-5 w-5" />, href: '/receiving', permission: 'receiving:read' },
            { key: 'shelving', icon: <Archive className="h-5 w-5" />, href: '/shelving', permission: 'shelving:execute' },
          ],
        },
      ],
    },
    {
      key: 'outbound',
      icon: <Truck className="h-4 w-4" />,
      items: [
        { key: 'orders', icon: <ClipboardList className="h-5 w-5" />, href: '/orders', permission: 'order:read' },
        { key: 'waves', icon: <Layers className="h-5 w-5" />, href: '/waves', permission: 'wave:read' },
        { key: 'pickOrders', icon: <ClipboardCheck className="h-5 w-5" />, href: '/pick-orders', permission: 'picking:read' },
        { key: 'sorting', icon: <Grid3X3 className="h-5 w-5" />, href: '/sorting', permission: 'sorting-wall:read' },
        { key: 'packing', icon: <PackageCheck className="h-5 w-5" />, href: '/packing', permission: 'packing:execute' },
        { key: 'checkout', icon: <ClipboardCheck className="h-5 w-5" />, href: '/checkout', permission: 'checkout:execute' },
        { key: 'checkoutOrders', icon: <FileText className="h-5 w-5" />, href: '/checkout-orders', permission: 'checkout:read' },
        // { key: 'manifestMount', icon: <Link2 className="h-5 w-5" />, href: '/manifest-mount', permission: 'manifest-order:read' },
        { key: 'manifestOrders', icon: <Archive className="h-5 w-5" />, href: '/manifest-orders', permission: 'manifest-order:read' },
        { key: 'sortingWalls', icon: <LayoutGrid className="h-5 w-5" />, href: '/sorting-walls', permission: 'sorting-wall:read' },
        // { key: 'shipping', icon: <Send className="h-5 w-5" />, href: '/shipping', permission: 'shipping:ship' }, // 已移除
        // { key: 'shipments', icon: <Truck className="h-5 w-5" />, href: '/shipments', permission: 'shipping:read' }, // 已移除
        // 包材管理子菜单组
        {
          key: 'packagingMaterialsGroup',
          icon: <Box className="h-5 w-5" />,
          items: [
            { key: 'packagingMaterials', icon: <Box className="h-5 w-5" />, href: '/packaging-materials', permission: 'packaging-material:read' },
            { key: 'packagingMaterialInventory', icon: <Package className="h-5 w-5" />, href: '/packaging-material-inventory', permission: 'packaging-material-inventory:read' },
            { key: 'packagingMaterialTransactions', icon: <FileText className="h-5 w-5" />, href: '/packaging-material-transactions', permission: 'packaging-material-transaction:read' },
          ],
        },
      ],
    },
    {
      key: 'inventory',
      icon: <Package className="h-4 w-4" />,
      items: [
        { key: 'inventorySummary', icon: <Package className="h-5 w-5" />, href: '/inventory', permission: 'inventory:read' },
        { key: 'inventoryDetail', icon: <PackageSearch className="h-5 w-5" />, href: '/inventory/wm', permission: 'inventory:read' },
        { key: 'inventoryTransactions', icon: <FileText className="h-5 w-5" />, href: '/inventory/transactions', permission: 'inventory:read' },
        // { key: 'inventoryAdjustments', icon: <ClipboardEdit className="h-5 w-5" />, href: '/inventory/adjustments', permission: 'inventory:adjust' }, // 暂时禁用
        // { key: 'inventoryTransfers', icon: <ArrowLeftRight className="h-5 w-5" />, href: '/inventory/transfers', permission: 'inventory:transfer' }, // 暂时禁用
        // { key: 'inventoryFreezes', icon: <Snowflake className="h-5 w-5" />, href: '/inventory/freezes', permission: 'inventory:freeze' }, // 暂时禁用
        // { key: 'inventoryAlerts', icon: <Bell className="h-5 w-5" />, href: '/inventory/alerts', permission: 'inventory:read' }, // 暂时禁用
      ],
    },
    {
      key: 'warehouseInfra',
      icon: <Warehouse className="h-4 w-4" />,
      items: [
        { key: 'warehouses', icon: <Warehouse className="h-5 w-5" />, href: '/warehouses', permission: 'warehouse:read' },
        { key: 'zones', icon: <MapPin className="h-5 w-5" />, href: '/zones', permission: 'zone:read' },
        { key: 'binLocations', icon: <Grid3X3 className="h-5 w-5" />, href: '/bin-locations', permission: 'bin:read' },
        { key: 'containers', icon: <Box className="h-5 w-5" />, href: '/containers', permission: 'container:read' },
      ],
    },
    {
      key: 'masterData',
      icon: <Database className="h-4 w-4" />,
      items: [
        { key: 'clients', icon: <Building2 className="h-5 w-5" />, href: '/clients', permission: 'client:read' },
        { key: 'sku', icon: <Tags className="h-5 w-5" />, href: '/sku', permission: 'sku:read' },
      ],
    },
    {
      key: 'reports',
      icon: <BarChart3 className="h-4 w-4" />,
      items: [
        { key: 'reportsOverview', icon: <BarChart3 className="h-5 w-5" />, href: '/reports', permission: 'report:read' },
        { key: 'inventoryReports', icon: <Package className="h-5 w-5" />, href: '/reports/inventory', permission: 'report:read' },
        { key: 'inboundReports', icon: <PackageCheck className="h-5 w-5" />, href: '/reports/inbound', permission: 'report:read' },
        { key: 'outboundReports', icon: <Truck className="h-5 w-5" />, href: '/reports/outbound', permission: 'report:read' },
      ],
    },
    {
      key: 'system',
      icon: <Settings className="h-4 w-4" />,
      items: [
        { key: 'jobs', icon: <ListTodo className="h-5 w-5" />, href: '/jobs', permission: 'job:read' },
        { key: 'scheduledTasks', icon: <Clock className="h-5 w-5" />, href: '/scheduled-tasks', permission: 'scheduled-task:read' },
        { key: 'users', icon: <Users className="h-5 w-5" />, href: '/users', permission: 'user:read' },
        { key: 'roles', icon: <Shield className="h-5 w-5" />, href: '/roles', permission: 'role:read' },
        { key: 'tenants', icon: <Building className="h-5 w-5" />, href: '/tenants', permission: 'tenant:read' },
        { key: 'audits', icon: <FileText className="h-5 w-5" />, href: '/audits', permission: 'audit:read' },
        { key: 'apiKeys', icon: <Key className="h-5 w-5" />, href: '/api-keys', permission: 'api-key:read' },
        { key: 'printSettings', icon: <Printer className="h-5 w-5" />, href: '/settings/print', permission: 'print:settings' },
        // { key: 'settings', icon: <Settings className="h-5 w-5" />, href: '/settings' }, // 暂时隐藏
      ],
    },
  ]

  // 自动展开包含当前激活菜单项的菜单组
  useEffect(() => {
    const findActiveGroup = () => {
      for (const group of menuGroups) {
        for (const item of group.items) {
          if (isSubMenuGroup(item)) {
            // 检查子菜单组
            for (const subItem of item.items) {
              if (pathname === subItem.href || pathname.startsWith(subItem.href + '/')) {
                setExpandedGroups((prev) => ({ ...prev, [group.key]: true }))
                setExpandedSubGroups((prev) => ({ ...prev, [item.key]: true }))
                return
              }
            }
          } else {
            if (pathname === item.href || pathname.startsWith(item.href + '/')) {
              setExpandedGroups((prev) => ({ ...prev, [group.key]: true }))
              return
            }
          }
        }
      }
    }
    findActiveGroup()
  }, [pathname])

  const toggleSubGroup = (subGroupKey: string) => {
    setExpandedSubGroups((prev) => ({
      ...prev,
      [subGroupKey]: !prev[subGroupKey],
    }))
  }

  // 过滤菜单项的辅助函数
  const filterMenuItem = (item: MenuItem): boolean => {
    return !item.permission || hasPermission(item.permission)
  }

  // 过滤子菜单组的辅助函数
  const filterSubMenuGroup = (subGroup: SubMenuGroup): SubMenuGroup | null => {
    const filteredItems = subGroup.items.filter(filterMenuItem)
    if (filteredItems.length === 0) return null
    return { ...subGroup, items: filteredItems }
  }

  // 根据权限过滤分组中的菜单项（支持子菜单组）
  const visibleGroups = menuGroups
    .map((group) => ({
      ...group,
      items: group.items
        .map((item) => {
          if (isSubMenuGroup(item)) {
            return filterSubMenuGroup(item)
          }
          return filterMenuItem(item) ? item : null
        })
        .filter((item): item is MenuItem | SubMenuGroup => item !== null),
    }))
    .filter((group) => group.items.length > 0)

  // 收集所有菜单项的 href，用于精确匹配
  const collectHrefs = (items: (MenuItem | SubMenuGroup)[]): string[] => {
    return items.flatMap((item) => {
      if (isSubMenuGroup(item)) {
        return item.items.map((subItem) => subItem.href)
      }
      return [item.href]
    })
  }

  const allMenuHrefs = [
    dashboardItem.href,
    ...menuGroups.flatMap((group) => collectHrefs(group.items)),
  ]

  // 判断菜单项是否激活 - 优先精确匹配，避免父路径误匹配
  const isMenuItemActive = (itemHref: string) => {
    // 精确匹配
    if (pathname === itemHref) return true

    // 检查是否有更精确的匹配项（避免 /inventory 匹配 /inventory/adjustments）
    const hasMoreSpecificMatch = allMenuHrefs.some(
      (href) => href !== itemHref && href.startsWith(itemHref + '/') && pathname.startsWith(href)
    )
    if (hasMoreSpecificMatch) return false

    // 前缀匹配（用于详情页，如 /inventory/adjustments/123）
    return pathname.startsWith(itemHref + '/')
  }

  const toggleGroup = (groupKey: string) => {
    setExpandedGroups((prev) => ({
      ...prev,
      [groupKey]: !prev[groupKey],
    }))
  }

  const renderMenuItem = (item: MenuItem) => {
    const isActive = isMenuItemActive(item.href)
    return (
      <li key={item.key}>
        <Link
          href={item.href}
          className={cn(
            'flex items-center gap-3 px-3 py-2 rounded-lg transition-colors',
            isActive
              ? 'bg-primary text-primary-foreground'
              : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
          )}
          title={collapsed ? t(item.key) : undefined}
        >
          {item.icon}
          {!collapsed && <span className="text-sm font-medium">{t(item.key)}</span>}
        </Link>
      </li>
    )
  }

  const renderSubMenuGroup = (subGroup: SubMenuGroup) => {
    const isExpanded = expandedSubGroups[subGroup.key]
    // 检查子菜单组中是否有激活的菜单项
    const hasActiveItem = subGroup.items.some((item) => isMenuItemActive(item.href))

    return (
      <li key={subGroup.key}>
        <button
          onClick={() => !collapsed && toggleSubGroup(subGroup.key)}
          className={cn(
            'w-full flex items-center gap-3 px-3 py-2 rounded-lg transition-colors',
            hasActiveItem
              ? 'text-primary'
              : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
          )}
          title={collapsed ? t(subGroup.key) : undefined}
        >
          {subGroup.icon}
          {!collapsed && (
            <>
              <span className="text-sm font-medium flex-1 text-left">{t(subGroup.key)}</span>
              <ChevronDown
                className={cn(
                  'h-4 w-4 transition-transform',
                  !isExpanded && '-rotate-90'
                )}
              />
            </>
          )}
        </button>
        {!collapsed && isExpanded && (
          <ul className="ml-6 space-y-1 mt-1 border-l-2 border-sidebar-border pl-2">
            {subGroup.items.map((item) => renderMenuItem(item))}
          </ul>
        )}
      </li>
    )
  }

  const renderGroupItem = (item: MenuItem | SubMenuGroup) => {
    if (isSubMenuGroup(item)) {
      return renderSubMenuGroup(item)
    }
    return renderMenuItem(item)
  }

  // 浮显菜单专用渲染函数 - 始终显示文字
  const renderPopoverMenuItem = (item: MenuItem) => {
    const isActive = isMenuItemActive(item.href)
    return (
      <li key={item.key}>
        <Link
          href={item.href}
          className={cn(
            'flex items-center gap-3 px-3 py-2 rounded-lg transition-colors',
            isActive
              ? 'bg-primary text-primary-foreground'
              : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
          )}
        >
          {item.icon}
          <span className="text-sm font-medium">{t(item.key)}</span>
        </Link>
      </li>
    )
  }

  const renderPopoverSubMenuGroup = (subGroup: SubMenuGroup) => {
    const hasActiveItem = subGroup.items.some((item) => isMenuItemActive(item.href))

    return (
      <li key={subGroup.key} className="space-y-1">
        <div
          className={cn(
            'flex items-center gap-3 px-3 py-2 rounded-lg',
            hasActiveItem
              ? 'text-primary'
              : 'text-muted-foreground'
          )}
        >
          {subGroup.icon}
          <span className="text-sm font-medium">{t(subGroup.key)}</span>
        </div>
        <ul className="ml-6 space-y-1 border-l-2 border-sidebar-border pl-2">
          {subGroup.items.map((item) => renderPopoverMenuItem(item))}
        </ul>
      </li>
    )
  }

  const renderPopoverGroupItem = (item: MenuItem | SubMenuGroup) => {
    if (isSubMenuGroup(item)) {
      return renderPopoverSubMenuGroup(item)
    }
    return renderPopoverMenuItem(item)
  }

  return (
    <aside
      className={cn(
        'h-screen bg-sidebar border-r border-sidebar-border text-sidebar-foreground flex flex-col transition-all duration-300',
        collapsed ? 'w-16' : 'w-56'
      )}
    >
      {/* Logo */}
      <div className="h-14 flex items-center justify-center border-b border-sidebar-border">
        {collapsed ? (
          <span className="text-xl font-bold text-primary">W</span>
        ) : (
          <span className="text-lg font-bold text-primary">KEC WMS</span>
        )}
      </div>

      {/* Menu */}
      <nav className="flex-1 py-4 overflow-y-auto overflow-x-hidden [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
        <div className="space-y-4">
          {/* Dashboard */}
          <ul className="space-y-1 px-2">
            {renderMenuItem(dashboardItem)}
          </ul>

          {/* Grouped Menus - 权限加载期间显示所有菜单，加载完成后过滤 */}
          {(loading ? menuGroups : visibleGroups).map((group) => (
            <div
              key={group.key}
              className="relative"
              onMouseEnter={(e) => handleGroupMouseEnter(group.key, e)}
              onMouseLeave={handleGroupMouseLeave}
            >
              {/* Group Header */}
              <button
                onClick={() => !collapsed && toggleGroup(group.key)}
                className={cn(
                  'w-full flex items-center gap-2 px-4 py-1.5 text-xs font-semibold text-sidebar-foreground/60 uppercase tracking-wider',
                  !collapsed && 'hover:text-sidebar-foreground cursor-pointer',
                  collapsed && 'hover:bg-accent rounded-lg mx-2'
                )}
                title={collapsed ? tGroup(group.key) : undefined}
              >
                {collapsed ? (
                  <div className="w-full flex justify-center">{group.icon}</div>
                ) : (
                  <>
                    <ChevronDown
                      className={cn(
                        'h-3 w-3 transition-transform',
                        !expandedGroups[group.key] && '-rotate-90'
                      )}
                    />
                    <span>{tGroup(group.key)}</span>
                  </>
                )}
              </button>

              {/* Group Items - 展开模式 */}
              {!collapsed && expandedGroups[group.key] && (
                <ul className="space-y-1 px-2 mt-1 ml-2 border-l-2 border-sidebar-border">
                  {group.items.map((item) => renderGroupItem(item))}
                </ul>
              )}
            </div>
          ))}
        </div>
      </nav>

      {/* 收起模式下的浮显菜单 - 使用 Portal 渲染到 body */}
      {collapsed && hoveredGroup && hoverPosition && (
        <div
          className="fixed left-16 z-[9999] min-w-48 max-h-[80vh] overflow-y-auto bg-sidebar border border-sidebar-border rounded-lg shadow-lg py-2 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]"
          style={{ top: hoverPosition.top }}
          onMouseEnter={handlePopoverMouseEnter}
          onMouseLeave={handlePopoverMouseLeave}
        >
          <div className="px-3 py-1.5 text-xs font-semibold text-sidebar-foreground/60 uppercase tracking-wider border-b border-sidebar-border mb-1">
            {tGroup(hoveredGroup)}
          </div>
          <ul className="space-y-1 px-2">
            {(loading ? menuGroups : visibleGroups)
              .find((g) => g.key === hoveredGroup)
              ?.items.map((item) => renderPopoverGroupItem(item))}
          </ul>
        </div>
      )}

      {/* Collapse Button */}
      <div className="p-2 border-t border-sidebar-border">
        <button
          onClick={() => setCollapsed(!collapsed)}
          className="w-full flex items-center justify-center gap-2 px-3 py-2 text-sidebar-foreground/70 hover:text-sidebar-foreground hover:bg-accent rounded-lg transition-colors"
        >
          {collapsed ? (
            <ChevronRight className="h-5 w-5" />
          ) : (
            <>
              <ChevronLeft className="h-5 w-5" />
              <span className="text-sm">{tCommon('collapse')}</span>
            </>
          )}
        </button>
      </div>
    </aside>
  )
}

