'use client'

import { useState, useMemo, useEffect } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { toast } from 'sonner'
import { Eye, Pencil, MoreHorizontal, Power, PowerOff, Package, Printer, Loader2, Copy } from 'lucide-react'
import { usePrintStore } from '@/stores/print-store'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { SkuStatusBadge } from './sku-status-badge'
import { StorageConditionBadge } from './storage-condition-badge'

interface Sku {
  id: string
  skuCode: string
  skuName: string
  barcode?: string | null
  unit: string
  storageCondition?: string | null
  abcClass?: string | null
  isBatchManaged: boolean
  isSerialManaged: boolean
  isFirstReceiving: boolean
  isSelfPackaged: boolean
  imageUrl?: string | null
  status: string
  createdAt: string
  client: {
    id: string
    clientCode: string
    clientName: string
  }
  category?: {
    id: string
    categoryCode: string
    categoryName: string
  } | null
  _count: {
    uoms: number
    barcodes: number
    inventoryBuckets: number
  }
}

interface SkuTableProps {
  skus: Sku[]
  onRefresh?: () => void
}

export function SkuTable({ skus, onRefresh }: SkuTableProps) {
  const router = useRouter()
  const t = useTranslations('sku')
  const tCommon = useTranslations('common')

  const [loadingId, setLoadingId] = useState<string | null>(null)
  const [selectedSkuIds, setSelectedSkuIds] = useState<Set<string>>(new Set())
  const [printing, setPrinting] = useState(false)

  // 初始化打印中间件连接
  const { connect, disconnect } = usePrintStore()

  useEffect(() => {
    connect()
    return () => disconnect()
  }, [connect, disconnect])

  // 处理全选/取消全选
  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      // 只选择启用状态的 SKU
      const activeSkuIds = skus
        .filter((sku) => sku.status === 'ACTIVE')
        .map((sku) => sku.id)
      setSelectedSkuIds(new Set(activeSkuIds))
    } else {
      setSelectedSkuIds(new Set())
    }
  }

  // 处理单个选择
  const handleSelectSku = (skuId: string, checked: boolean) => {
    const newSelected = new Set(selectedSkuIds)
    if (checked) {
      newSelected.add(skuId)
    } else {
      newSelected.delete(skuId)
    }
    setSelectedSkuIds(newSelected)
  }

  // 获取选中的 SKU 列表
  const selectedSkus = useMemo(() => {
    return skus.filter((sku) => selectedSkuIds.has(sku.id))
  }, [skus, selectedSkuIds])

  // 批量打印标签
  const handleBatchPrint = async () => {
    if (selectedSkuIds.size === 0) return

    setPrinting(true)
    try {
      // 生成打印 URL（带 token）
      const response = await fetch('/api/v1/print-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          documentType: 'sku-label',
          ids: Array.from(selectedSkuIds),
        }),
      })

      if (!response.ok) {
        throw new Error('生成打印 URL 失败')
      }

      const { data } = await response.json()
      const pdfUrl = data.url

      // 检查打印中间件连接状态
      const { isConnected } = usePrintStore.getState()
      console.log('打印中间件连接状态:', isConnected)

      if (isConnected) {
        // 方式1：通过打印中间件打印
        console.log('使用打印中间件打印')
        await printViaPrintAgent(pdfUrl)
      } else {
        // 方式2：浏览器打印（降级方案）
        console.log('使用浏览器打印（降级方案）')
        await printViaBrowser(pdfUrl)
      }

      toast.success(`成功打印 ${selectedSkuIds.size} 个 SKU 标签`)

      // 清除选择
      setSelectedSkuIds(new Set())
    } catch (error) {
      const message = error instanceof Error ? error.message : '打印失败'
      toast.error(message)
    } finally {
      setPrinting(false)
    }
  }

  // 浏览器打印
  const printViaBrowser = async (pdfUrl: string) => {
    const response = await fetch(pdfUrl)
    const blob = await response.blob()
    const url = URL.createObjectURL(blob)

    const printWindow = window.open(url, '_blank')
    if (printWindow) {
      printWindow.onload = () => {
        printWindow.print()
      }
    }

    setTimeout(() => URL.revokeObjectURL(url), 60000)
  }

  // 打印中间件打印
  const printViaPrintAgent = async (pdfUrl: string) => {
    console.log('开始通过打印中间件打印...')

    // 获取 PDF
    const response = await fetch(pdfUrl)
    const blob = await response.blob()

    // 转换为 base64
    const reader = new FileReader()
    const pdfBase64 = await new Promise<string>((resolve, reject) => {
      reader.onloadend = () => {
        const base64 = reader.result as string
        resolve(base64.split(',')[1]) // 移除 data:application/pdf;base64, 前缀
      }
      reader.onerror = reject
      reader.readAsDataURL(blob)
    })

    // 获取默认打印设备和模板
    console.log('查询默认打印设备和模板...')
    const templateResponse = await fetch('/api/v1/print-templates?labelType=SKU_LABEL&isDefault=true')
    const templateData = await templateResponse.json()
    console.log('模板查询结果:', templateData)
    const defaultTemplate = templateData.data?.[0]
    const defaultDevice = defaultTemplate?.defaultDevice

    if (!defaultDevice) {
      // 如果没有配置默认设备，降级到浏览器打印
      console.warn('未配置默认打印设备，降级到浏览器打印')
      toast.warning('未配置默认打印设备，使用浏览器打印')
      await printViaBrowser(pdfUrl)
      return
    }

    console.log('找到默认设备:', defaultDevice)

    // 发送打印任务
    const { print } = usePrintStore.getState()
    const status = await print({
      jobId: `sku-label-${Date.now()}`,
      deviceConfig: {
        connectionType: defaultDevice.connectionType,
        ipAddress: defaultDevice.ipAddress,
        port: defaultDevice.port,
      },
      pdfBase64,
      copies: 1,
    })

    if (status !== 'SUCCESS') {
      throw new Error('打印任务失败')
    }

    // 记录打印历史
    try {
      await fetch('/api/v1/print-history', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          deviceId: defaultDevice.id,
          templateId: defaultTemplate?.id,
          labelType: 'SKU_LABEL',
          relatedIds: Array.from(selectedSkuIds),
          relatedType: 'SKU',
          pageCount: selectedSkuIds.size,
          status: 'SUCCESS',
        }),
      })
    } catch (error) {
      // 打印历史记录失败不影响打印结果
      console.error('记录打印历史失败:', error)
    }
  }

  const handleStatusChange = async (skuId: string, status: string) => {
    setLoadingId(skuId)
    try {
      const response = await fetch(`/api/v1/skus/${skuId}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      })

      const result = await response.json()

      if (result.success) {
        toast.success(t('statusUpdateSuccess'))
        onRefresh?.()
        router.refresh()
      } else {
        toast.error(result.message || tCommon('error'))
      }
    } catch {
      toast.error(tCommon('error'))
    } finally {
      setLoadingId(null)
    }
  }

  // 计算可选择的 SKU 数量（仅启用状态）
  const activeSkuCount = skus.filter((sku) => sku.status === 'ACTIVE').length
  const allActiveSelected = activeSkuCount > 0 && selectedSkuIds.size === activeSkuCount

  return (
    <>
      {/* 批量操作工具栏 */}
      {selectedSkuIds.size > 0 && (
        <div className="flex items-center gap-4 p-3 bg-muted rounded-lg mb-4">
          <span className="text-sm">
            已选择 {selectedSkuIds.size} 个 SKU
          </span>
          <Button
            size="sm"
            onClick={handleBatchPrint}
            disabled={printing}
          >
            {printing && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            <Printer className="h-4 w-4 mr-1" />
            批量打印标签
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setSelectedSkuIds(new Set())}
          >
            取消选择
          </Button>
        </div>
      )}

      <div className="rounded-md border">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-12">
                <Checkbox
                  checked={allActiveSelected}
                  onCheckedChange={handleSelectAll}
                  aria-label="全选"
                />
              </TableHead>
              <TableHead className="w-[80px]">{t('image')}</TableHead>
              <TableHead>{t('code')}</TableHead>
              <TableHead>{t('name')}</TableHead>
              <TableHead>{t('client')}</TableHead>
              <TableHead>{t('category')}</TableHead>
              <TableHead>{t('unit')}</TableHead>
              <TableHead>{t('storageConditionLabel')}</TableHead>
              <TableHead>{t('statusLabel')}</TableHead>
              <TableHead className="text-right">{tCommon('actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {skus.length === 0 ? (
              <TableRow>
                <TableCell colSpan={10} className="text-center py-8 text-muted-foreground">
                  {tCommon('noData')}
                </TableCell>
              </TableRow>
            ) : (
              skus.map((sku) => (
