  open,
  onOpenChange,
  onSuccess,
}: CreateWaveDialogProps) {
  const [orders, setOrders] = useState<OutboundOrder[]>([])
  const [selectedOrderIds, setSelectedOrderIds] = useState<string[]>([])
  const [warehouseId, setWarehouseId] = useState<string>('')
  const [waveType, setWaveType] = useState<string>('STANDARD')
  const [pickStrategy, setPickStrategy] = useState<string>('ORDER')
  const [search, setSearch] = useState('')
  const [ordersLoading, setOrdersLoading] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // 获取仓库列表
  useEffect(() => {
    if (open) {
      // WarehouseSelect 组件内部自行加载，无需在此 fetch
    }
  }, [open])

  // 仓库变化时获取订单
  useEffect(() => {
    if (warehouseId) {
      fetchOrders()
      setSelectedOrderIds([])
    } else {
      setOrders([])
    }
  }, [warehouseId])

  const fetchOrders = async () => {
    if (!warehouseId) return
    setOrdersLoading(true)
    try {
      const params = new URLSearchParams({
        warehouseId,
        pageSize: '100',
      })
      // 只获取可加入波次的订单状态
      // ALLOCATED 和 PENDING_WAVE 状态的订单可以加入波次
      if (search) params.set('search', search)

      const res = await fetch(`/api/v1/outbound-orders?${params}`)
      const data = await res.json()
      if (data.success) {
        // 过滤出可加入波次的订单（状态为 ALLOCATED 或 PENDING_WAVE，且未关联波次）
        const availableOrders = data.data.filter(
          (order: OutboundOrder & { waveId?: string }) =>
            ['ALLOCATED', 'PENDING_WAVE'].includes(order.status) && !order.waveId
        )
        setOrders(availableOrders)
      }
    } catch (error) {
      console.error('Failed to fetch orders:', error)
    } finally {
      setOrdersLoading(false)
    }
  }

  const handleSearch = () => {
    fetchOrders()
  }

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedOrderIds(orders.map((o) => o.id))
    } else {
      setSelectedOrderIds([])
    }
  }

  const handleSelectOrder = (orderId: string, checked: boolean) => {
    if (checked) {
      setSelectedOrderIds([...selectedOrderIds, orderId])
    } else {
      setSelectedOrderIds(selectedOrderIds.filter((id) => id !== orderId))
    }
  }

  const handleSubmit = async () => {
    if (!warehouseId || selectedOrderIds.length === 0) {
      toast.error('请选择仓库和订单')
      return
    }

    setIsSubmitting(true)
    try {
      const res = await fetch('/api/v1/waves', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          warehouseId,
          waveType,
          pickStrategy,
          orderIds: selectedOrderIds,
        }),
      })

      const data = await res.json()
      if (data.success) {
        toast.success(`波次 ${data.data.waveNumber} 创建成功`)
        handleClose()
        onSuccess()
      } else {
        toast.error(data.message || '创建失败')
      }
    } catch (error) {
      console.error('Failed to create wave:', error)
      toast.error('创建波次失败')
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleClose = () => {
    setWarehouseId('')
    setWaveType('STANDARD')
    setPickStrategy('ORDER')
    setSelectedOrderIds([])
    setOrders([])
    setSearch('')
    onOpenChange(false)
  }

  // 计算汇总
  const selectedOrders = orders.filter((o) => selectedOrderIds.includes(o.id))
  const totalQty = selectedOrders.reduce((sum, o) => sum + o.totalOrderedQty, 0)
  const isAllSelected = orders.length > 0 && selectedOrderIds.length === orders.length

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-4xl max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>新建波次</DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-hidden flex flex-col gap-4">
          {/* 基本信息 */}
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label>仓库 *</Label>
              <WarehouseSelect value={warehouseId} onValueChange={setWarehouseId} />
            </div>
            <div className="space-y-2">
              <Label>波次类型</Label>
              <Select value={waveType} onValueChange={setWaveType}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="STANDARD">标准</SelectItem>
                  <SelectItem value="EXPRESS">加急</SelectItem>
                  <SelectItem value="BATCH">批量</SelectItem>
                  <SelectItem value="SINGLE">单品</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>拣货策略</Label>
              <Select value={pickStrategy} onValueChange={setPickStrategy}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ORDER">按单拣货</SelectItem>
                  <SelectItem value="BATCH">批量拣货</SelectItem>
                  <SelectItem value="ZONE">分区拣货</SelectItem>
                  <SelectItem value="CLUSTER">集群拣货</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* 订单搜索 */}
          {warehouseId && (
            <div className="flex items-center gap-2">
              <Input
                placeholder="搜索订单号..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-64"
                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
              />
              <Button variant="outline" size="icon" onClick={handleSearch}>
                <Search className="h-4 w-4" />
              </Button>
              <span className="text-sm text-muted-foreground ml-2">
                可选订单: {orders.length} 单
              </span>
            </div>
          )}

          {/* 订单表格 */}
          <div className="flex-1 border rounded-md overflow-auto min-h-[200px]">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12">
                    <Checkbox
                      checked={isAllSelected}
                      onCheckedChange={handleSelectAll}
                      disabled={orders.length === 0}
                    />
                  </TableHead>
                  <TableHead>订单号</TableHead>
                  <TableHead>客户</TableHead>
                  <TableHead>收货人</TableHead>
                  <TableHead>优先级</TableHead>
                  <TableHead className="text-right">数量</TableHead>
                  <TableHead>创建时间</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {!warehouseId ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                      请先选择仓库
                    </TableCell>
                  </TableRow>
                ) : ordersLoading ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-8">
                      <Loader2 className="h-4 w-4 animate-spin mx-auto" />
                    </TableCell>
                  </TableRow>
                ) : orders.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                      暂无可加入波次的订单
                    </TableCell>
                  </TableRow>
                ) : (
                  orders.map((order) => (
                    <TableRow key={order.id}>
                      <TableCell>
                        <Checkbox
                          checked={selectedOrderIds.includes(order.id)}
                          onCheckedChange={(checked) =>
                            handleSelectOrder(order.id, checked as boolean)
                          }
                        />
                      </TableCell>
                      <TableCell className="font-medium">{order.orderNumber}</TableCell>
                      <TableCell>{order.client?.clientName}</TableCell>
                      <TableCell>{order.address?.contactName || '-'}</TableCell>
                      <TableCell>
                        <Badge className={priorityColors[order.priority] || 'bg-gray-500'}>
                          {order.priority}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">{order.totalOrderedQty}</TableCell>
                      <TableCell>
                        {formatDate(order.createdAt) || '-'}
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          {/* 已选汇总 */}
          {selectedOrderIds.length > 0 && (
            <div className="border rounded-md p-4 bg-muted/50">
              <div className="flex items-center gap-6 text-sm">
                <div>
                  已选: <span className="font-medium">{selectedOrderIds.length}</span> 单
                </div>
                <div>
                  总数量: <span className="font-medium text-primary">{totalQty}</span> 件
                </div>
              </div>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>
            取消
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={!warehouseId || selectedOrderIds.length === 0 || isSubmitting}
          >
            {isSubmitting ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                创建中...
              </>
            ) : (
              `创建波次 (${selectedOrderIds.length} 单)`
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { AsyncLocalStorage } from 'async_hooks'
import { Prisma, PrismaClient } from '@prisma/client'
import { pushAuditToQueue } from '../queue/audit-queue'

// 用于审计扩展内部查询的独立 Prisma Client（避免循环依赖）
let internalPrisma: PrismaClient | null = null
function getInternalPrisma(): PrismaClient {
  if (!internalPrisma) {
    internalPrisma = new PrismaClient({ log: ['error'] })
  }
  return internalPrisma
}

// 请求上下文类型
export interface AuditContext {
  tenantId?: string
  operatorId?: string
  operatorName?: string
  ipAddress?: string
  userAgent?: string
  requestPath?: string
  requestMethod?: string
}

// 全局单例，避免 Next.js 热重载导致创建多个实例
const globalForAuditContext = globalThis as unknown as {
  auditContext: AsyncLocalStorage<AuditContext> | undefined
}

// 用于存储请求上下文的 AsyncLocalStorage（全局单例）
export const auditContext = globalForAuditContext.auditContext ?? new AsyncLocalStorage<AuditContext>()

// 保存到全局，确保热重载后仍是同一个实例
if (!globalForAuditContext.auditContext) {
  globalForAuditContext.auditContext = auditContext
  console.log('[Audit Context] Created new AsyncLocalStorage instance')
}

/**
 * 为 Worker/后台任务设置审计上下文
 * 使用方式:
 * await withWorkerAuditContext({ tenantId, operatorId, operatorName }, async () => {
 *   // 业务逻辑
 * })
 */
export async function withWorkerAuditContext<T>(
  ctx: AuditContext,
  handler: () => Promise<T>
): Promise<T> {
  return auditContext.run(ctx, handler)
}

// 需要排除的表（不记录审计日志）
const EXCLUDED_MODELS = new Set([
  'Audit', // 审计表自身
  'LoginHistory', // 登录历史
  'OperationLog', // 操作日志
  'BackgroundJob', // 后台任务
  'ScheduledTaskLog', // 定时任务日志
  'ApiKey', // API 密钥（每次请求都会更新 lastUsedAt，产生大量日志）
  'SkuInventorySummary', // SKU 库存汇总快照（高频更新，不需要审计）
  'LocationInventorySnapshot', // 库位库存快照（高频更新，不需要审计）
])

/**
 * 展开复合唯一索引语法为单独字段
 * Prisma upsert 支持 `field1_field2: { field1: ..., field2: ... }` 语法
 * 但 findFirst 不支持，需要展开为 `{ field1: ..., field2: ... }`
 */
function expandCompositeKey(where: Record<string, any>): Record<string, any> {
  if (!where || typeof where !== 'object') return where

  const result: Record<string, any> = {}

  for (const [key, value] of Object.entries(where)) {
    // 检测复合键语法：键名包含下划线且值是对象
    if (
      key.includes('_') &&
      value &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      !(value instanceof Date)
    ) {
      // 检查值对象的所有键是否都包含在复合键名中
      const keyParts = key.split('_')
      const valueKeys = Object.keys(value)
      const isCompositeKey = valueKeys.every(vk => keyParts.includes(vk))

      if (isCompositeKey && valueKeys.length > 0) {
        // 展开复合键：将值对象的字段合并到结果中
        Object.assign(result, value)
        continue
      }
    }

    // 非复合键，直接保留
    result[key] = value
  }

  return result
}

// 敏感字段（需要脱敏）
const SENSITIVE_FIELDS = new Set(['password', 'passwordHash', 'apiKey', 'apiSecret', 'token', 'keyHash'])

/**
 * 提取实体名称（用于显示）
 */
function extractEntityName(entityType: string, data: any): string | null {
  if (!data) return null

  // 根据不同实体类型提取合适的名称字段
  const nameFields = [
    'name',
    'username',
    'tenantName',
    'warehouseName',
    'skuCode',
    'externalNumber',
    'orderNumber',
    'asnNumber',
    'code',
    'title',
  ]

  for (const field of nameFields) {
    if (data[field]) return String(data[field])
  }

  return data.id || null
}

// 关键字段列表（用于 CREATE/DELETE 操作的精简记录）
const KEY_FIELDS = [
  'id',
  'name',
  'username',
  'tenantName',
  'warehouseName',
  'skuCode',
  'externalNumber',
  'orderNumber',
  'asnNumber',
  'code',
  'title',
  'status',
  'roleCode',
  'roleName',
]

/**
 * 提取关键字段（用于 CREATE/DELETE 操作的精简记录）
 */
function extractKeyFields(data: any): Record<string, any> {
  if (!data || typeof data !== 'object') return {}

  const result: Record<string, any> = {}
  for (const field of KEY_FIELDS) {
    if (data[field] !== undefined && data[field] !== null) {
      result[field] = data[field]
    }
  }
  return result
}

/**
 * 对数据进行脱敏处理（同时序列化 BigInt 等特殊类型）
 */
function sanitizeData(data: any): any {
  if (!data || typeof data !== 'object') return serializeValue(data)

  const result: Record<string, any> = {}
  for (const [key, value] of Object.entries(data)) {
    if (SENSITIVE_FIELDS.has(key)) {
      result[key] = '***REDACTED***'
    } else {
      result[key] = serializeValue(value)
    }
  }
  return result
}

/**
 * 安全的 JSON 序列化，处理 BigInt 和 Decimal 类型
 */
function safeStringify(value: any): string {
  return JSON.stringify(value, (_, v) => {
    if (typeof v === 'bigint') return v.toString()
    if (v && typeof v === 'object' && v.constructor?.name === 'Decimal') return v.toString()
    return v
  })
}

/**
 * 转换值为可存储格式（BigInt -> string）
 */
function serializeValue(value: any): any {
  if (typeof value === 'bigint') return value.toString()
  if (value && typeof value === 'object' && value.constructor?.name === 'Decimal') return value.toString()
  if (value instanceof Date) return value.toISOString()
  if (Array.isArray(value)) return value.map(serializeValue)
  if (value && typeof value === 'object') {
    const result: Record<string, any> = {}
    for (const [k, v] of Object.entries(value)) {
      result[k] = serializeValue(v)
    }
    return result
  }
  return value
}

/**
 * 对比两个对象，提取变更的字段，分别返回旧值和新值对象
 */
function extractChanges(oldData: any, newData: any): {
  fields: string[]
  oldValues: Record<string, any>
  newValues: Record<string, any>
} {
  if (!oldData || !newData) return { fields: [], oldValues: {}, newValues: {} }

  const fields: string[] = []
  const oldValues: Record<string, any> = {}
  const newValues: Record<string, any> = {}
  const oldKeys = Object.keys(oldData)
  const newKeys = Object.keys(newData)
  const allKeys = Array.from(new Set([...oldKeys, ...newKeys]))

  for (const key of allKeys) {
    // 跳过系统字段
    if (key === 'updatedAt' || key === 'createdAt') continue

    const oldValue = oldData[key]
    const newValue = newData[key]

    // 深度比较（使用安全序列化）
    if (safeStringify(oldValue) !== safeStringify(newValue)) {
      fields.push(key)
      // 脱敏处理 + 序列化
      oldValues[key] = SENSITIVE_FIELDS.has(key) ? '***REDACTED***' : serializeValue(oldValue)
      newValues[key] = SENSITIVE_FIELDS.has(key) ? '***REDACTED***' : serializeValue(newValue)
    }
  }

  return { fields, oldValues, newValues }
}

// 是否启用调试日志
const DEBUG_AUDIT = process.env.DEBUG_AUDIT === 'true'

/**
 * 捕获审计信息并推送到队列
 * 优化：只记录变更字段的新旧值，减少数据量
 * @param capturedCtx 预先捕获的上下文（解决 AsyncLocalStorage 在 Prisma 回调中丢失的问题）
 */
async function captureAudit(
  operationType: 'CREATE' | 'UPDATE' | 'DELETE',
  entityType: string,
  newData: any,
  oldData?: any,
  capturedCtx?: AuditContext
): Promise<void> {
  try {
    // 跳过排除的表
    if (EXCLUDED_MODELS.has(entityType)) {
      if (DEBUG_AUDIT) console.log(`[Audit] Skipped excluded model: ${entityType}`)
      return
    }

    // 使用预先捕获的上下文（优先），或尝试从 AsyncLocalStorage 获取，最后从数据中提取 tenantId
    const ctx = capturedCtx || auditContext.getStore()
    const tenantId = ctx?.tenantId || newData?.tenantId || oldData?.tenantId

    if (DEBUG_AUDIT) {
      console.log(`[Audit] ${operationType} ${entityType}`, {
        hasContext: !!ctx,
        tenantId,
        entityId: newData?.id || oldData?.id,
      })
    }

    if (!tenantId) {
      if (DEBUG_AUDIT) console.warn(`[Audit] Skipped - no tenantId for ${entityType}`)
      return // 没有租户信息则跳过
    }

    // 根据操作类型构建精简的审计数据
    let auditOldData: any = null
    let auditNewData: any = null
    let changedFields: string[] = []

    if (operationType === 'CREATE') {
      // CREATE：记录完整数据（脱敏处理）
      auditNewData = sanitizeData(newData)
    } else if (operationType === 'DELETE') {
      // DELETE：只记录关键字段
      auditOldData = { deleted: extractKeyFields(oldData) }
    } else if (operationType === 'UPDATE') {
      // UPDATE：旧值放 oldData，新值放 newData，方便前端分别显示
      const { fields, oldValues, newValues } = extractChanges(oldData, newData)
      changedFields = fields
      if (fields.length > 0) {
        auditOldData = oldValues
        auditNewData = newValues
      } else {
        // 没有实际变更，跳过记录
        return
      }
    }

    // 推送到队列
    await pushAuditToQueue({
      operationType,
      entityType,
      entityId: (newData?.id || oldData?.id) as string,
      entityName: extractEntityName(entityType, newData || oldData),
      oldData: auditOldData,
      newData: auditNewData,
      changedFields,
      tenantId,
      operatorId: ctx?.operatorId,
      operatorName: ctx?.operatorName,
      ipAddress: ctx?.ipAddress,
      userAgent: ctx?.userAgent,
      requestPath: ctx?.requestPath,
      requestMethod: ctx?.requestMethod,
      timestamp: new Date().toISOString(),
    })
  } catch (error) {
    // 审计失败不应该影响主业务，只记录错误
    console.error('[Audit Extension] Failed to capture audit:', error)
  }
}

/**
 * Prisma 审计扩展
 * 自动拦截所有数据库的 create/update/delete 操作
 */
export const auditExtension = Prisma.defineExtension({
  name: 'audit',
  query: {
    $allModels: {
      // 拦截 create 操作
      async create({ args, query, model }) {
        // 在调用 query 之前捕获上下文（解决 AsyncLocalStorage 在 Prisma 回调中丢失的问题）
        const ctx = auditContext.getStore()
        const result = await query(args)
        await captureAudit('CREATE', model, result, undefined, ctx)
        return result
      },

      // 拦截 update 操作
      async update({ args, query, model }) {
        // 在调用 query 之前捕获上下文
        const ctx = auditContext.getStore()

        // 先查询旧数据
        let oldData = null
        try {
          const prisma = getInternalPrisma()
          const modelKey = model.charAt(0).toLowerCase() + model.slice(1)
          // @ts-expect-error - 动态模型访问
          oldData = await prisma[modelKey].findFirst({ where: args.where })
        } catch (error) {
          console.error(`[Audit Extension] Failed to fetch old data for ${model}:`, error)
        }

        const result = await query(args)
        await captureAudit('UPDATE', model, result, oldData, ctx)
        return result
      },

      // 拦截 delete 操作
      async delete({ args, query, model }) {
        // 在调用 query 之前捕获上下文
        const ctx = auditContext.getStore()

        // 先查询要删除的数据
        let oldData = null
        try {
          const prisma = getInternalPrisma()
          const modelKey = model.charAt(0).toLowerCase() + model.slice(1)
          // @ts-expect-error - 动态模型访问
          oldData = await prisma[modelKey].findFirst({ where: args.where })
        } catch (error) {
          console.error(`[Audit Extension] Failed to fetch old data for ${model}:`, error)
        }

        const result = await query(args)
        await captureAudit('DELETE', model, null, oldData, ctx)
        return result
      },

      // 拦截 upsert 操作
      async upsert({ args, query, model }) {
        // 在调用 query 之前捕获上下文
        const ctx = auditContext.getStore()

        // 先查询是否存在
        // 注意：upsert 的 where 可能使用复合唯一索引语法，需要展开
        let existing = null
        try {
          const prisma = getInternalPrisma()
          const modelKey = model.charAt(0).toLowerCase() + model.slice(1)
          // 展开复合键语法，使其兼容 findFirst
          const expandedWhere = expandCompositeKey(args.where)
          // @ts-expect-error - 动态模型访问
          existing = await prisma[modelKey].findFirst({ where: expandedWhere })
        } catch (error) {
          console.error(`[Audit Extension] Failed to fetch existing data for ${model}:`, error)
        }

        const result = await query(args)

        if (existing) {
          await captureAudit('UPDATE', model, result, existing, ctx)
        } else {
          await captureAudit('CREATE', model, result, undefined, ctx)
        }

        return result
      },
    },
  },
})

import { Prisma } from '@prisma/client'

/**
 * 递归转换对象中的所有 Decimal 类型为字符串
 * @param obj 要转换的对象
 * @returns 转换后的对象
 */
function convertDecimalsToString(obj: unknown, depth = 0, path = 'root'): unknown {
  if (obj === null || obj === undefined) return obj

  // 如果是原始类型（包括原始字符串），直接返回
  if (typeof obj !== 'object') return obj

  // 如果是 Date 对象，直接返回（不处理，由 timezone 扩展处理）
  if (obj instanceof Date) return obj

  // 检查是否有 Decimal.js 的内部结构 (d, e, s 属性)
  const decimalObj = obj as any
  const hasDecimalStructure =
    decimalObj.d !== undefined &&
    Array.isArray(decimalObj.d) &&
    decimalObj.e !== undefined &&
    typeof decimalObj.e === 'number' &&
    decimalObj.s !== undefined &&
    typeof decimalObj.s === 'number'

  if (hasDecimalStructure) {
    // 使用 Decimal 对象自己的方法来转换
    if (typeof decimalObj.toFixed === 'function') {
      return decimalObj.toFixed()
    } else {
      // 如果没有 toFixed 方法，尝试 toString
      return decimalObj.toString ? decimalObj.toString() : String(decimalObj)
    }
  }

  // 如果是数组，递归处理每个元素
  if (Array.isArray(obj)) {
    return obj.map((item, index) => convertDecimalsToString(item, depth + 1, `${path}[${index}]`))
  }

  // 如果是普通对象，递归处理每个属性
  const converted: Record<string, unknown> = {}
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      converted[key] = convertDecimalsToString((obj as Record<string, unknown>)[key], depth + 1, `${path}.${key}`)
    }
  }
  return converted
}

/**
 * Prisma Decimal 扩展
 * 自动将所有查询结果中的 Decimal 字段转换为字符串
 */
export const decimalExtension = Prisma.defineExtension({
  name: 'decimal',
  query: {
    $allModels: {
      async $allOperations({ operation, args, query }) {
        const result = await query(args)

        // 只对查询操作进行转换（不影响写入）
        const readOperations = [
          'findUnique',
          'findUniqueOrThrow',
          'findFirst',
          'findFirstOrThrow',
          'findMany',
          'create',
          'createMany',
          'update',
          'updateMany',
          'upsert',
          'delete',
          'deleteMany',
          'aggregate',
          'groupBy',
          'count',
        ]

        if (readOperations.includes(operation)) {
          return convertDecimalsToString(result)
        }

        return result
      },
    },
  },
})

import Redis from 'ioredis'

let redis: Redis | null = null

function getRedisClient(): Redis {
  if (!redis) {
    const redisUrl = process.env.REDIS_URL

    if (!redisUrl) {
      // 如果没有配置 Redis URL，使用默认配置
      redis = new Redis({
        host: 'localhost',
        port: 6379,
        maxRetriesPerRequest: 3,
        retryStrategy(times) {
          const delay = Math.min(times * 50, 2000)
          return delay
        },
        lazyConnect: true,
      })
    } else {
      redis = new Redis(redisUrl, {
        maxRetriesPerRequest: 3,
        retryStrategy(times) {
          const delay = Math.min(times * 50, 2000)
          return delay
        },
        lazyConnect: true,
      })
    }
  }

  return redis
}

export { getRedisClient }
export default { get: () => getRedisClient() }

/**
 * E2E 测试 API 客户端
 * 用于调用后端 API 进行测试
 */

export interface ApiClientConfig {
  baseUrl: string
  tenantCode?: string
  username?: string
  password?: string
}

export interface ApiResponse<T = unknown> {
  success: boolean
  data?: T
  message?: string
  code?: string
}

const AUTH_ERROR_CODE_SEPARATOR = ':'

function buildE2ELoginIp(tenantCode: string, username: string): string {
  const seed = `${tenantCode}:${username}`
  let hash = 0

  for (const char of seed) {
    hash = (hash * 31 + char.charCodeAt(0)) >>> 0
  }

  return `127.0.0.${(hash % 200) + 1}`
}

function getAuthErrorMessage(error?: string | null, code?: string | null): string {
  if (code) {
    const [key, detail] = code.split(AUTH_ERROR_CODE_SEPARATOR)

    switch (key) {
      case 'pleaseInputComplete':
        return '请填写完整的登录信息'
      case 'tooManyRequests':
        return '请求过于频繁，请稍后再试'
      case 'tenantNotFound':
        return '租户不存在或已禁用'
      case 'userNotFound':
        return '用户名或密码错误'
      case 'accountDisabled':
        return '账号已被禁用'
      case 'accountLocked':
        return '账号已被锁定，请联系管理员'
      case 'accountSuspended':
        return '账号已被暂停，请联系管理员'
      case 'accountLockedMinutes':
        return `账号已被锁定，请${detail ?? '0'}分钟后再试`
      case 'wrongPassword':
        return `用户名或密码错误，还剩${detail ?? '0'}次尝试机会`
      default:
        break
    }
  }

  if (error === 'CredentialsSignin') {
    return '用户名或密码错误'
  }

  return '登录失败'
}

function parseAuthErrorFromLocation(location: string | null, baseUrl: string): string | null {
  if (!location) return null

  const url = new URL(location, baseUrl)
  const error = url.searchParams.get('error')
  const code = url.searchParams.get('code')

  if (!error && !code) return null

  return getAuthErrorMessage(error, code)
}

// 单例模式：复用登录会话，避免重复登录
let sharedClient: E2eApiClient | null = null
let sharedLoginPromise: Promise<boolean> | null = null

export class E2eApiClient {
  private baseUrl: string
  private cookies: string[] = []
  private isLoggedIn = false
  private loginTime: number = 0
  private currentTenantCode: string | null = null  // 记录当前登录的租户
  private currentUsername: string | null = null    // 记录当前登录的用户
  private static SESSION_TIMEOUT = 30 * 60 * 1000 // 30 分钟

  constructor(config: ApiClientConfig) {
    this.baseUrl = config.baseUrl || 'http://localhost:3000'
  }

  // 获取共享客户端实例（单例模式）
  static getSharedClient(baseUrl = 'http://localhost:3000'): E2eApiClient {
    if (!sharedClient) {
      sharedClient = new E2eApiClient({ baseUrl })
    }
    return sharedClient
  }

  // 重置共享客户端
  static resetSharedClient(): void {
    sharedClient = null
    sharedLoginPromise = null
  }

  // 检查会话是否仍然有效
  private isSessionValid(): boolean {
    if (!this.isLoggedIn) return false
    const elapsed = Date.now() - this.loginTime
    return elapsed < E2eApiClient.SESSION_TIMEOUT
  }

  // 登录获取 Session（带防重入锁）
  async login(tenantCode: string, username: string, password: string): Promise<boolean> {
    // 检查是否需要重新登录：
    // 1. 会话已过期
    // 2. 租户或用户不匹配（切换账号场景）
    const needsRelogin = !this.isSessionValid() ||
      this.currentTenantCode !== tenantCode ||
      this.currentUsername !== username

    if (!needsRelogin) {
      return true
    }

    // 如果切换了租户/用户，重置状态
    if (this.currentTenantCode !== tenantCode || this.currentUsername !== username) {
      console.log(`🔄 切换租户/用户: ${this.currentTenantCode}/${this.currentUsername} -> ${tenantCode}/${username}`)
      this.cookies = []
      this.isLoggedIn = false
    }

    // 如果有正在进行的登录，等待其完成
    if (sharedLoginPromise && this === sharedClient) {
      return sharedLoginPromise
    }

    const loginPromise = this.doLogin(tenantCode, username, password)
    if (this === sharedClient) {
      sharedLoginPromise = loginPromise
    }

    try {
      return await loginPromise
    } finally {
      if (this === sharedClient) {
        sharedLoginPromise = null
      }
    }
  }

  private async doLogin(tenantCode: string, username: string, password: string): Promise<boolean> {
    const forwardedFor = buildE2ELoginIp(tenantCode, username)

    try {
      // 重置 cookies（避免旧 cookie 干扰）
      this.cookies = []

      // 先获取 CSRF token（如果需要）
      const csrfRes = await fetch(`${this.baseUrl}/api/auth/csrf`)
      const csrfData = await csrfRes.json()
      const csrfToken = csrfData.csrfToken

      // 获取 cookies
      const csrfCookies = csrfRes.headers.getSetCookie?.() || []
      this.cookies = [...csrfCookies]

      // 执行登录
      const loginRes = await fetch(`${this.baseUrl}/api/auth/callback/credentials`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Cookie: this.cookies.join('; '),
          'x-forwarded-for': forwardedFor,
          'x-real-ip': forwardedFor,
        },
        body: new URLSearchParams({
          csrfToken,
          tenantCode,
          username,
          password,
          callbackUrl: `${this.baseUrl}/dashboard`,
          json: 'true',
        }),
        redirect: 'manual',
      })
      const loginError = parseAuthErrorFromLocation(loginRes.headers.get('location'), this.baseUrl)

      // 获取 session cookies（替换而非追加）
      const loginCookies = loginRes.headers.getSetCookie?.() || []
      // 合并 cookies，相同名称的用新值替换
      const cookieMap = new Map<string, string>()
      for (const cookie of [...this.cookies, ...loginCookies]) {
        const name = cookie.split('=')[0]
        cookieMap.set(name, cookie)
      }
      this.cookies = Array.from(cookieMap.values())

      // 验证登录成功
      const sessionRes = await fetch(`${this.baseUrl}/api/auth/session`, {
        headers: { Cookie: this.cookies.join('; ') },
      })
      const session = await sessionRes.json()

      this.isLoggedIn = !!session?.user
      if (!this.isLoggedIn) {
        throw new Error(loginError || 'E2E 自动登录未建立会话')
      }

      this.loginTime = Date.now()
      this.currentTenantCode = tenantCode
      this.currentUsername = username
      return true
    } catch (error) {
      this.isLoggedIn = false
      this.currentTenantCode = null
      this.currentUsername = null
      const message = error instanceof Error ? error.message : String(error)
      console.error('Login failed:', message)
      throw new Error(message)
    }
  }

  // 通用 API 请求
  async request<T>(
    method: string,
    path: string,
    body?: unknown
  ): Promise<ApiResponse<T>> {
    const url = `${this.baseUrl}${path}`
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    }

    if (this.cookies.length > 0) {
      headers.Cookie = this.cookies.join('; ')
    }

    try {
      const res = await fetch(url, {
        method,
        headers,
        body: body ? JSON.stringify(body) : undefined,
      })

      const text = await res.text()
      try {
        return JSON.parse(text)
      } catch {
        // 非 JSON 响应
        return { success: false, message: text || `HTTP ${res.status}` } as ApiResponse<T>
      }
    } catch (error) {
      return { success: false, message: error instanceof Error ? error.message : String(error) } as ApiResponse<T>
    }
  }

  // GET 请求
  async get<T>(path: string): Promise<ApiResponse<T>> {
    return this.request<T>('GET', path)
  }

  // POST 请求
  async post<T>(path: string, body?: unknown): Promise<ApiResponse<T>> {
    return this.request<T>('POST', path, body)
  }

  // PUT 请求
  async put<T>(path: string, body?: unknown): Promise<ApiResponse<T>> {
    return this.request<T>('PUT', path, body)
  }

