  // 2. 创建测试用户
  const passwordHash = await hash(E2E_ADMIN_PASSWORD, 10)
  const user = await prisma.user.upsert({
    where: { tenantId_username: { tenantId: tenant.id, username: E2E_ADMIN_USERNAME } },
    update: {
      email: 'e2e-admin@test.com',
      passwordHash,
      status: 'ACTIVE',
      isActive: true,
