  params: Record<string, unknown>
}> {
  const instances: Array<{ code: string; name: string; params: Record<string, unknown> }> = []

  // 根据模板类型生成不同的预设组合
  if (template.code === 'RECV-NORMAL' || template.code === 'PUT-NORMAL' || template.code === 'OUTBOUND-FULL') {
    // SKU 类型变体
    for (const preset of SKU_TYPE_PRESETS) {
      instances.push({
        code: `${template.code}-${preset.suffix}`,
        name: `${template.name}-${preset.name}`,
        params: { ...preset.params, quantity: 10 },
      })
    }
  } else if (template.code === 'RECV-QUANTITY') {
    // 数量变体
    for (const preset of QUANTITY_PRESETS) {
      instances.push({
        code: `${template.code}-${preset.suffix}`,
        name: `${template.name}-${preset.name}`,
        params: preset.params,
      })
    }
  } else if (template.code === 'RECV-QUALITY') {
    // 质量比例变体
    instances.push({ code: `${template.code}-73`, name: `${template.name}-良品70%`, params: { goodQty: 70, damagedQty: 30, expectedQty: 100 } })
    instances.push({ code: `${template.code}-37`, name: `${template.name}-良品30%`, params: { goodQty: 30, damagedQty: 70, expectedQty: 100 } })
    instances.push({ code: `${template.code}-DAMAGED`, name: `${template.name}-全残`, params: { goodQty: 0, damagedQty: 100, expectedQty: 100 } })
  } else if (template.code === 'RECV-NEGATIVE' || template.code === 'PUT-FAIL') {
    // 异常类型变体
    const exceptionTypes = template.parameters.exceptionType?.enum || []
    for (const exType of exceptionTypes.slice(0, 5)) { // 取前5个常用的
      instances.push({
        code: `${template.code}-${exType.toUpperCase().replace(/_/g, '-')}`,
        name: `${template.name}-${exType}`,
        params: { exceptionType: exType },
      })
    }
  } else {
    // 默认：只生成一个基础实例
    instances.push({
      code: template.code,
      name: template.name,
      params: {},
    })
  }

  return instances
}

// ==================== 同步函数 ====================

async function cleanupLegacySeedScenarios(db: ScenarioSyncPrisma): Promise<{
  categoriesDeleted: number
  scenariosDeleted: number
  resultsDeleted: number
}> {
  const legacyCategories = await db.e2eScenarioCategory.findMany({
    where: { code: { in: LEGACY_SEED_CATEGORY_CODES } },
    select: { id: true },
  })

  if (legacyCategories.length === 0) {
    return { categoriesDeleted: 0, scenariosDeleted: 0, resultsDeleted: 0 }
  }

  const legacyCategoryIds = legacyCategories.map((category) => category.id)
  const legacyScenarios = await db.e2eScenario.findMany({
    where: { categoryId: { in: legacyCategoryIds } },
    select: { id: true },
  })

  const legacyScenarioIds = legacyScenarios.map((scenario) => scenario.id)
  const resultsDeleted = legacyScenarioIds.length > 0
    ? (await db.e2eScenarioResult.deleteMany({ where: { scenarioId: { in: legacyScenarioIds } } })).count
    : 0

  const scenariosDeleted = (await db.e2eScenario.deleteMany({
    where: { categoryId: { in: legacyCategoryIds } },
  })).count

  const categoriesDeleted = (await db.e2eScenarioCategory.deleteMany({
    where: { id: { in: legacyCategoryIds } },
  })).count

  return { categoriesDeleted, scenariosDeleted, resultsDeleted }
}

export async function syncScenarioTemplates(
  db: ScenarioSyncPrisma = appPrisma,
  options: { cleanupLegacySeedData?: boolean } = {},
): Promise<{
  categoriesCreated: number
  scenariosSynced: number
  categoriesDeleted: number
  scenariosDeleted: number
  resultsDeleted: number
}> {
  console.log('\n' + '='.repeat(60))
  console.log('🔄 同步场景模板到数据库')
  console.log('='.repeat(60))
  console.log(`📦 模板总数: ${ALL_TEMPLATES.length}`)

  let categoriesCreated = 0
  let scenariosSynced = 0
  let categoriesDeleted = 0
  let scenariosDeleted = 0
  let resultsDeleted = 0

  if (options.cleanupLegacySeedData) {
    const cleanupResult = await cleanupLegacySeedScenarios(db)
    categoriesDeleted = cleanupResult.categoriesDeleted
    scenariosDeleted = cleanupResult.scenariosDeleted
    resultsDeleted = cleanupResult.resultsDeleted

    if (categoriesDeleted || scenariosDeleted || resultsDeleted) {
      console.log(
        `🧹 已清理旧 seed 场景: ${categoriesDeleted} 分类 / ${scenariosDeleted} 场景 / ${resultsDeleted} 结果`,
      )
    }
  }

  // 1. 创建/更新分类
  for (const cat of TEMPLATE_CATEGORIES) {
    await db.e2eScenarioCategory.upsert({
      where: { code: cat.code },
      create: { code: cat.code, name: cat.name, description: cat.description, sortOrder: cat.sortOrder },
      update: { name: cat.name, description: cat.description, sortOrder: cat.sortOrder },
    })
    categoriesCreated++
  }
  console.log(`✅ 分类同步完成: ${categoriesCreated} 个`)

  // 2. 为每个模板生成场景实例
  for (const template of ALL_TEMPLATES) {
    const category = TEMPLATE_CATEGORIES.find(c =>
      template.code.startsWith(c.templatePrefix) ||
      (c.domain === template.domain && template.code.startsWith(c.templatePrefix.split('-')[0]))
    )
    if (!category) {
      console.warn(`⚠️ 模板 ${template.code} 未找到匹配分类，跳过`)
      continue
    }

    const categoryRecord = await db.e2eScenarioCategory.findUnique({ where: { code: category.code } })
    if (!categoryRecord) continue

    const instances = generateScenarioInstances(template)

    for (const instance of instances) {
      const config = template.buildConfig(instance.params)
      const expected = template.buildExpected(instance.params)

      await db.e2eScenario.upsert({
        where: { code: instance.code },
        create: {
          categoryId: categoryRecord.id,
          code: instance.code,
          name: instance.name,
          description: `${template.description} [模板: ${template.code}]`,
          config: config as any,
          expected: expected as any,
          sortOrder: scenariosSynced,
          isActive: true,
        },
        update: {
          name: instance.name,
          description: `${template.description} [模板: ${template.code}]`,
          config: config as any,
          expected: expected as any,
        },
      })
      scenariosSynced++
    }
    console.log(`  📝 ${template.code}: ${instances.length} 个实例`)
  }

  console.log('='.repeat(60))
  console.log(`✅ 同步完成: ${categoriesCreated} 分类, ${scenariosSynced} 场景`)
  console.log('='.repeat(60) + '\n')

  return { categoriesCreated, scenariosSynced, categoriesDeleted, scenariosDeleted, resultsDeleted }
}

// 直接运行
if (require.main === module) {
  syncScenarioTemplates()
    .then(() => process.exit(0))
    .catch((e) => { console.error(e); process.exit(1) })
}

/**
 * Webhook处理器
 */

import { v4 as uuidv4 } from 'uuid'
import type {
  WebhookConfig,
  WebhookEvent,
  WebhookEventType,
  ApiResponse,
} from '../types'
import { SignatureVerifier } from './signature-verifier'
import { DEFAULT_RETRY_CONFIG } from '../config'

interface WebhookDeliveryResult {
  webhookId: string
  eventId: string
  success: boolean
  statusCode?: number
  error?: string
  duration: number
  retryCount: number
}

export class WebhookHandler {
  private webhooks: Map<string, WebhookConfig> = new Map()
  private signatureVerifier: SignatureVerifier

  constructor() {
    this.signatureVerifier = new SignatureVerifier()
  }

  /** 注册Webhook */
  register(config: WebhookConfig): void {
    this.webhooks.set(config.id, config)
  }

  /** 注销Webhook */
  unregister(webhookId: string): void {
    this.webhooks.delete(webhookId)
  }

  /** 获取Webhook配置 */
  getWebhook(webhookId: string): WebhookConfig | undefined {
    return this.webhooks.get(webhookId)
  }

  /** 获取所有Webhook */
  getAllWebhooks(): WebhookConfig[] {
    return Array.from(this.webhooks.values())
  }

  /** 触发事件 */
  async dispatch<T>(
    eventType: WebhookEventType,
    data: T,
    tenantId: string
  ): Promise<WebhookDeliveryResult[]> {
    const results: WebhookDeliveryResult[] = []

    // 查找订阅了该事件的Webhook
    const subscribedWebhooks = Array.from(this.webhooks.values()).filter(
      (webhook) => webhook.enabled && webhook.events.includes(eventType)
    )

    // 创建事件
    const event: WebhookEvent<T> = {
      id: uuidv4(),
      type: eventType,
      data,
      tenantId,
      timestamp: new Date(),
      version: '1.0',
    }

    // 并行发送到所有订阅的Webhook
    const deliveryPromises = subscribedWebhooks.map((webhook) =>
      this.deliver(webhook, event)
    )

    const deliveryResults = await Promise.allSettled(deliveryPromises)

    for (let i = 0; i < deliveryResults.length; i++) {
      const result = deliveryResults[i]
      if (result.status === 'fulfilled') {
        results.push(result.value)
      } else {
        results.push({
          webhookId: subscribedWebhooks[i].id,
          eventId: event.id,
          success: false,
          error: result.reason?.message || 'Unknown error',
          duration: 0,
          retryCount: 0,
        })
      }
    }

    return results
  }

  /** 发送Webhook */
  private async deliver<T>(
    webhook: WebhookConfig,
    event: WebhookEvent<T>
  ): Promise<WebhookDeliveryResult> {
    const startTime = Date.now()
    const maxRetries = webhook.retry?.maxRetries ?? DEFAULT_RETRY_CONFIG.maxRetries
    let retryCount = 0
    let lastError: string | undefined

    while (retryCount <= maxRetries) {
      try {
        // 生成签名
        const signature = this.signatureVerifier.sign(
          JSON.stringify(event),
          webhook.secret
        )

        // 发送请求
        const response = await fetch(webhook.url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Webhook-ID': webhook.id,
            'X-Event-ID': event.id,
            'X-Event-Type': event.type,
            'X-Signature': signature,
            'X-Timestamp': event.timestamp.toISOString(),
            ...webhook.headers,
          },
          body: JSON.stringify(event),
        })

        if (response.ok) {
          return {
            webhookId: webhook.id,
            eventId: event.id,
            success: true,
            statusCode: response.status,
            duration: Date.now() - startTime,
            retryCount,
          }
        }

        lastError = `HTTP ${response.status}: ${response.statusText}`

        // 检查是否应该重试
        if (![408, 429, 500, 502, 503, 504].includes(response.status)) {
          break
        }
      } catch (error) {
        lastError = error instanceof Error ? error.message : 'Network error'
      }

      retryCount++
      if (retryCount <= maxRetries) {
        // 指数退避
        await this.delay(1000 * Math.pow(2, retryCount - 1))
      }
    }

    return {
      webhookId: webhook.id,
      eventId: event.id,
      success: false,
      error: lastError,
      duration: Date.now() - startTime,
      retryCount,
    }
  }

  /** 延迟 */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
  }
}

import { createSocket } from 'dgram'
import { createConnection } from 'net'
import { deflate } from 'zlib'
import { promisify } from 'util'
import { hostname } from 'os'
import { BaseChannel } from './base-channel'
import type { LogRecord, GelfChannelConfig } from '../types'

const deflateAsync = promisify(deflate)

// GELF 级别映射（syslog 标准）
const GELF_LEVEL_MAP: Record<string, number> = {
  EMERGENCY: 0, ALERT: 1, CRITICAL: 2, ERROR: 3,
  WARNING: 4,   NOTICE: 5, INFO: 6,   DEBUG: 7,
}

interface GelfMessage {
  version: '1.1'
  host: string
  short_message: string
  full_message?: string
  timestamp: number
  level: number
  facility?: string
  [key: string]: unknown
}

export class GelfChannel extends BaseChannel {
  readonly name = 'gelf'
  private config: GelfChannelConfig
  private host: string

  constructor(config: GelfChannelConfig) {
    super(config.level)
    this.config = config
    this.host = process.env.HOSTNAME || hostname()
  }

  private buildGelfMessage(record: LogRecord): GelfMessage {
    const msg: GelfMessage = {
      version: '1.1',
      host: this.host,
      short_message: record.message,
      timestamp: new Date(record.timestamp).getTime() / 1000,
      level: GELF_LEVEL_MAP[record.level] ?? 7,
      facility: this.config.facility,
      _channel: record.channel,
      _level_name: record.level,
      _request_id: record.request_id,
      _user_id: record.user_id,
      _tenant_id: record.tenant_id,
      _ip: record.ip,
      _path: record.path,
      _method: record.method,
    }

    // 展开 context 字段（GELF 自定义字段必须以 _ 开头）
    if (record.context) {
      for (const [k, v] of Object.entries(record.context)) {
        msg[`_${k}`] = typeof v === 'object' ? JSON.stringify(v) : v
      }
    }

    if (record.error) {
      msg._error_name = record.error.name
      msg._error_message = record.error.message
      msg.full_message = record.error.stack
    }

    // 追加额外字段
    if (this.config.additionalFields) {
      for (const [k, v] of Object.entries(this.config.additionalFields)) {
        msg[`_${k}`] = v
      }
    }

    // 清理 undefined 字段
    return Object.fromEntries(
      Object.entries(msg).filter(([, v]) => v !== undefined)
    ) as GelfMessage
  }

  async write(record: LogRecord): Promise<void> {
    if (!this.shouldLog(record)) return
    const gelf = this.buildGelfMessage(record)
    const payload = Buffer.from(JSON.stringify(gelf))
    try {
      if (this.config.transport === 'udp') {
        await this.sendUdp(payload)
      } else {
        await this.sendTcp(payload)
      }
    } catch (err) {
      // GELF 发送失败不影响主业务，降级到 stderr
      process.stderr.write(`[Logger/GELF] Send failed: ${err}\n`)
    }
  }

  private async sendUdp(payload: Buffer): Promise<void> {
    const compressed = await deflateAsync(payload)
    if (compressed.length <= 8192) {
      return new Promise((resolve, reject) => {
        const socket = createSocket('udp4')
        socket.send(compressed, this.config.port, this.config.host, (err) => {
          socket.close()
          err ? reject(err) : resolve()
        })
      })
    }
    // Chunking：每块最大 1420 字节（MTU 安全值）
    const CHUNK_SIZE = 1420
    const chunks = Math.ceil(compressed.length / CHUNK_SIZE)
    const msgId = Buffer.allocUnsafe(8)
    msgId.writeBigUInt64BE(BigInt(Date.now()))

    return new Promise((resolve, reject) => {
      const socket = createSocket('udp4')
      let sent = 0
      for (let i = 0; i < chunks; i++) {
        const chunk = compressed.subarray(i * CHUNK_SIZE, (i + 1) * CHUNK_SIZE)
        // GELF chunk header: magic(2) + msgId(8) + seqNum(1) + seqCount(1)
        const header = Buffer.from([0x1e, 0x0f, ...msgId, i, chunks])
        const packet = Buffer.concat([header, chunk])
        socket.send(packet, this.config.port, this.config.host, (err) => {
          if (err) { socket.close(); reject(err); return }
          if (++sent === chunks) { socket.close(); resolve() }
        })
      }
    })
  }

  private sendTcp(payload: Buffer): Promise<void> {
    return new Promise((resolve, reject) => {
      const client = createConnection(this.config.port, this.config.host, () => {
        // GELF TCP：消息以 null byte 结尾
        client.write(Buffer.concat([payload, Buffer.from([0x00])]))
        client.end()
        resolve()
      })
      client.on('error', reject)
      client.setTimeout(5000, () => {
        client.destroy()
        reject(new Error('GELF TCP timeout'))
      })
    })
  }
}

