                <Text style={[styles.tableCell, styles.tableCellLpn]}>{line.lpn || '-'}</Text>
                <Text style={[styles.tableCell, styles.tableCellQty]}>{line.expectedQty}</Text>
              </View>
            ))}
          </View>

          <View style={styles.footer}>
            <Text>第 {pageIndex + 1} / {pages.length} 页</Text>
            <Text>共 {lines.length} 行</Text>
          </View>
        </Page>
      ))}
    </Document>
  )
}

/**
 * 报表导出 Worker
 */

import { Job } from 'bullmq'
import { prismaRead, prisma } from '@/lib/db/prisma'
import { BaseWorker } from './base-worker'
import { JobContext, ReportExportJobData, ReportExportResult } from '../types'
import { FileStorage } from '../utils/file-storage'
import * as XLSX from 'xlsx'

export class ReportExportWorker extends BaseWorker<
  ReportExportJobData,
  ReportExportResult
> {
  private fileStorage = new FileStorage()

  protected async process(
    job: Job<ReportExportJobData, ReportExportResult>,
    context: JobContext
  ): Promise<ReportExportResult> {
    const { reportType, filters, format, columns } = job.data

    // 更新进度
    await this.updateProgress(context.jobId, {
      progress: 10,
      message: '正在获取数据...',
    })

    // 获取报表数据
    const data = await this.fetchReportData(
      reportType,
      context.tenantId,
      filters
    )

    await this.updateProgress(context.jobId, {
      progress: 50,
      message: `正在处理 ${data.length} 条记录...`,
      totalCount: data.length,
    })

    // 生成文件
    const fileName = this.generateFileName(reportType, format)
    const fileBuffer = this.generateFile(data, format, columns)

    await this.updateProgress(context.jobId, {
      progress: 80,
      message: '正在保存文件...',
    })

    // 保存文件
    const filePath = await this.fileStorage.saveFile(
      context.tenantId,
      context.jobId,
      fileName,
      fileBuffer
    )

    const expiresAt = new Date()
    expiresAt.setDate(expiresAt.getDate() + 7) // 7天过期

    // 更新任务文件信息
    await prisma.backgroundJob.update({
      where: { id: context.jobId },
      data: {
        resultFilePath: filePath,
        resultFileName: fileName,
        resultFileSize: fileBuffer.length,
        resultExpiresAt: expiresAt,
      },
    })

    return {
      filePath,
      fileName,
      fileSize: fileBuffer.length,
      rowCount: data.length,
      expiresAt,
    }
  }

  /**
   * 获取报表数据
   */
  private async fetchReportData(
    reportType: string,
    tenantId: string,
    filters: Record<string, unknown>
  ): Promise<unknown[]> {
    const where = { tenantId, ...filters }

    switch (reportType) {
      case 'INVENTORY':
        return prismaRead.inventorySnapshot.findMany({
          where,
          include: {
            warehouse: { select: { warehouseCode: true, warehouseName: true } },
            zone: { select: { zoneCode: true, zoneName: true } },
            location: { select: { locationCode: true } },
          },
        })

      case 'TRANSACTIONS':
        return prismaRead.inventoryEvent.findMany({
          where,
          orderBy: { createdAt: 'desc' },
        })

      case 'ORDERS':
        return prismaRead.outboundOrder.findMany({
          where,
          include: { lines: true },
        })

      case 'ASN':
        return prismaRead.asn.findMany({
          where,
          include: { asnLines: true },
        })

      case 'SHIPMENTS':
        return prismaRead.shipment.findMany({
          where,
          include: { order: true },
        })

      case 'SKU':
        return prismaRead.sku.findMany({
          where,
          include: {
            client: { select: { clientCode: true, clientName: true } },
            category: { select: { categoryName: true } },
          },
        })

      case 'CLIENT':
        return prismaRead.client.findMany({
          where,
        })

      default:
        throw new Error(`未知的报表类型: ${reportType}`)
    }
  }

  /**
   * 生成文件名
   */
  private generateFileName(reportType: string, format: string): string {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
    return `${reportType.toLowerCase()}_export_${timestamp}.${format}`
  }

  /**
   * 生成文件
   */
  private generateFile(
    data: unknown[],
    format: string,
    columns?: string[]
  ): Buffer {
    if (format === 'xlsx') {
      const worksheet = XLSX.utils.json_to_sheet(data as object[])
      const workbook = XLSX.utils.book_new()
      XLSX.utils.book_append_sheet(workbook, worksheet, 'Data')
      return Buffer.from(
        XLSX.write(workbook, { type: 'buffer', bookType: 'xlsx' })
      )
    } else {
      // CSV 格式
      const worksheet = XLSX.utils.json_to_sheet(data as object[])
      const csv = XLSX.utils.sheet_to_csv(worksheet)
      return Buffer.from(csv, 'utf-8')
    }
  }
}

/**
 * 库存事件服务
 * 负责创建和管理库存事件（事件溯源的核心）
 *
 * 事件类型：
 * - PUTAWAY: 上架（增加 AVAILABLE）
 * - ALLOCATE: 分配（AVAILABLE -> ALLOCATED）
 * - DEALLOCATE: 取消分配（ALLOCATED -> AVAILABLE）
 * - PICK: 拣货（ALLOCATED -> PICKING）
 * - UNPICK: 取消拣货（PICKING -> ALLOCATED）
 * - SHIP: 发货（PICKING -> 出库）
 * - FREEZE: 冻结（AVAILABLE -> FROZEN）
 * - UNFREEZE: 解冻（FROZEN -> AVAILABLE）
 * - ADJUST: 调整（任意桶类型的数量调整）
 * - TRANSFER: 移库（跨库位转移）
 * - QC_HOLD: 质检暂扣
 * - QC_RELEASE: 质检放行
 * - COUNT_HOLD: 盘点暂扣
 * - COUNT_RELEASE: 盘点放行
 */

import { prisma, type TransactionClient } from '@/lib/db/prisma'
import { Prisma } from '@prisma/client'
import { withBucketLock, withMultipleBucketLocks } from './inventory-lock-service'
import { Log } from '@/lib/logger'

// 事件类型枚举
export const InventoryEventType = {
  PUTAWAY: 'PUTAWAY',
  ALLOCATE: 'ALLOCATE',
  DEALLOCATE: 'DEALLOCATE',
  PICK: 'PICK',
  UNPICK: 'UNPICK',
  SHIP: 'SHIP',
  FREEZE: 'FREEZE',
  UNFREEZE: 'UNFREEZE',
  ADJUST: 'ADJUST',
  TRANSFER_OUT: 'TRANSFER_OUT',
  TRANSFER_IN: 'TRANSFER_IN',
  QC_HOLD: 'QC_HOLD',
  QC_RELEASE: 'QC_RELEASE',
  COUNT_HOLD: 'COUNT_HOLD',
  COUNT_RELEASE: 'COUNT_RELEASE',
  DEFECTIVE_IN: 'DEFECTIVE_IN',
  DEFECTIVE_OUT: 'DEFECTIVE_OUT',
} as const

export type InventoryEventTypeValue = (typeof InventoryEventType)[keyof typeof InventoryEventType]

// 桶类型枚举
export const BucketType = {
  AVAILABLE: 'AVAILABLE',
  ALLOCATED: 'ALLOCATED',
  PICKING: 'PICKING',
  FROZEN: 'FROZEN',
  DEFECTIVE: 'DEFECTIVE',
  QC_HOLD: 'QC_HOLD',
  COUNT_HOLD: 'COUNT_HOLD',
} as const

export type BucketTypeValue = (typeof BucketType)[keyof typeof BucketType]

// 事件创建参数
export interface CreateEventParams {
  tenantId: string
  clientId: string
  warehouseId: string
  locationId: string
  skuId: string
  skuCode: string
  batchNumber?: string | null
  lpn?: string | null
  eventType: InventoryEventTypeValue
  eventSubType?: string | null
  bucketType: BucketTypeValue
  quantityDelta: number
  referenceType?: string | null
  referenceId?: string | null
  referenceNumber?: string | null
  referenceLineId?: string | null
  reasonCode?: string | null
  reasonDescription?: string | null
  unitCost?: Prisma.Decimal | null
  expiryDate?: Date | null
  productionDate?: Date | null
  fifoDate?: Date | null
  operatorId?: string | null
  metadata?: Prisma.JsonValue
}

// 生成事件编号
function generateEventNumber(): string {
  const timestamp = Date.now().toString(36)
  const random = Math.random().toString(36).substring(2, 8)
  return `EVT-${timestamp}-${random}`.toUpperCase()
}

// 生成幂等键
function generateIdempotencyKey(params: CreateEventParams): string {
  // 将时间戳和随机数放在前面，确保唯一性不会被截断
  const timestamp = Date.now().toString(36)
  const random = Math.random().toString(36).substring(2, 10)
  const parts = [
    timestamp,
    random,
    params.eventType,
    params.bucketType,
    params.referenceType || '',
    params.referenceId || params.referenceNumber || '',
    params.referenceLineId || '',
  ]
  return parts.join(':').substring(0, 128)
}

/**
 * 创建库存事件
 * 这是事件溯源的核心方法，所有库存变动都通过此方法记录
 */
export async function createInventoryEvent(
  params: CreateEventParams,
  tx?: TransactionClient
): Promise<{ id: string; eventNumber: string }> {
  const client = tx || prisma
  const eventNumber = generateEventNumber()
  const idempotencyKey = generateIdempotencyKey(params)

  // 查询当前库存数量（变更前）
  const currentBucket = await client.inventoryBucket.findFirst({
    where: {
      tenantId: params.tenantId,
      warehouseId: params.warehouseId,
      locationId: params.locationId,
      skuId: params.skuId,
      batchNumber: params.batchNumber || '',
      lpn: params.lpn || '',
      bucketType: params.bucketType,
    },
    select: { quantity: true },
  })
  const quantityBefore = currentBucket?.quantity || 0
  const quantityAfter = quantityBefore + params.quantityDelta

  const event = await client.inventoryEvent.create({
    data: {
      tenantId: params.tenantId,
      clientId: params.clientId,
      warehouseId: params.warehouseId,
      locationId: params.locationId,
      skuId: params.skuId,
      skuCode: params.skuCode,
      batchNumber: params.batchNumber || '',
      lpn: params.lpn || '',
      eventNumber,
      idempotencyKey,
      eventDate: new Date(),
      eventType: params.eventType,
      eventSubType: params.eventSubType,
      bucketType: params.bucketType,
      quantityBefore,
      quantityAfter,
      quantityDelta: params.quantityDelta,
      referenceType: params.referenceType,
      referenceId: params.referenceId,
      referenceNumber: params.referenceNumber,
      referenceLineId: params.referenceLineId,
      reasonCode: params.reasonCode,
      reasonDesc: params.reasonDescription,
      unitCost: params.unitCost,
      operatorId: params.operatorId,
    },
    select: { id: true, eventNumber: true },
  })

  return event
}

/**
 * 批量创建库存事件
 * 注意：批量创建时 quantityBefore 设为 0，适用于初始化场景
 */
export async function createInventoryEvents(
  events: CreateEventParams[],
  tx?: TransactionClient
): Promise<{ count: number }> {
  const client = tx || prisma

  if (events.length === 0) {
    return { count: 0 }
  }

  const data = events.map((params) => ({
    tenantId: params.tenantId,
    clientId: params.clientId,
    warehouseId: params.warehouseId,
    locationId: params.locationId,
    skuId: params.skuId,
    skuCode: params.skuCode,
    batchNumber: params.batchNumber || '',
    lpn: params.lpn || '',
    eventNumber: generateEventNumber(),
    idempotencyKey: generateIdempotencyKey(params),
    eventDate: new Date(),
    eventType: params.eventType,
    eventSubType: params.eventSubType,
    bucketType: params.bucketType,
    quantityBefore: 0, // 批量创建时设为 0
    quantityAfter: params.quantityDelta, // 批量创建时等于 delta
    quantityDelta: params.quantityDelta,
    referenceType: params.referenceType,
    referenceId: params.referenceId,
    referenceNumber: params.referenceNumber,
    referenceLineId: params.referenceLineId,
    reasonCode: params.reasonCode,
    reasonDesc: params.reasonDescription,
    unitCost: params.unitCost,
    operatorId: params.operatorId,
  }))

  try {
    const result = await client.inventoryEvent.createMany({ data })

    // 验证创建结果
    if (result.count !== events.length) {
      Log.warning('[InventoryEvent] 创建事件数量不匹配', { expected: events.length, actual: result.count })
    }

    Log.info('[InventoryEvent] 成功创建库存事件', { count: result.count })
    return { count: result.count }
  } catch (error) {
    Log.error('[InventoryEvent] 创建库存事件失败', { error, event_data: JSON.stringify(data) })
    throw error
  }
}

/**
 * 上架事件
 * 将库存放入指定库位的 AVAILABLE 桶
 */
export async function createPutawayEvent(
  params: Omit<CreateEventParams, 'eventType' | 'bucketType' | 'quantityDelta'> & {
    quantity: number
  },
  tx?: TransactionClient
) {
  return createInventoryEvent(
    {
      ...params,
      eventType: InventoryEventType.PUTAWAY,
      bucketType: BucketType.AVAILABLE,
      quantityDelta: params.quantity,
    },
    tx
  )
}

/**
 * 分配事件
 * 从 AVAILABLE 桶转移到 ALLOCATED 桶
 */
export async function createAllocateEvents(
  params: Omit<CreateEventParams, 'eventType' | 'bucketType' | 'quantityDelta'> & {
    quantity: number
  },
  tx?: TransactionClient
) {
  const client = tx || prisma

  // 创建两个事件：AVAILABLE 减少，ALLOCATED 增加
  const events = [
    {
      ...params,
      eventType: InventoryEventType.ALLOCATE,
      bucketType: BucketType.AVAILABLE,
      quantityDelta: -params.quantity,
    },
    {
      ...params,
      eventType: InventoryEventType.ALLOCATE,
      bucketType: BucketType.ALLOCATED,
      quantityDelta: params.quantity,
    },
  ]

  return createInventoryEvents(events as CreateEventParams[], client)
}

