/**
 * 生成ASN单号
 * 格式: ASN-{仓库代码}-{日期YYMMDD}-{4位流水号}
 * 例如: ASN-WH01-260204-0001
 */
export async function generateAsnNumber(
  tenantId: string,
  warehouseCode: string
): Promise<string> {
  const today = new Date()
  const dateStr = today
    .toISOString()
    .slice(2, 10)
    .replace(/-/g, '')
  const prefix = `ASN-${warehouseCode}-${dateStr}-`

  // 查找今天该仓库的最大流水号
  const lastAsn = await prisma.asn.findFirst({
    where: {
      tenantId,
      asnNumber: {
        startsWith: prefix,
      },
    },
    orderBy: {
      asnNumber: 'desc',
    },
    select: {
      asnNumber: true,
    },
  })

  let sequence = 1
  if (lastAsn) {
    const lastSequence = parseInt(lastAsn.asnNumber.slice(-4), 10)
    if (!isNaN(lastSequence)) {
      sequence = lastSequence + 1
    }
  }

  return `${prefix}${sequence.toString().padStart(4, '0')}`
}

